eRunStartMode GetRunStartModeNum(AnsiString ModeName)                           //Steven 20120609 : 修改Start Mode切換方式
{
    eRunStartMode Ret=rsmNull;
    for(int i=0; i<rsmRunModeTotal; i++)
    {
        if(StartModeName[i]==ModeName)
        {
            Ret=eRunStartMode(i);
            break;
        }
    }
    return Ret;
}
//------------------------------------------------------------------------------
bool CheckSMCDLLVersion()                                                       //Isaac 20190606 : SMCC.dll版本檢查
{
    if(MOTION_CARD_TYPE!=MotionCard_Contec)
    {
        return true;
    }
    AnsiString str="", strtemp="";
    int ret=-1;

    ret=DoCheckSMCDLLVersion();
    if(ret!=0)
    {
        str.sprintf("SMC Driver using version is :%s \r\nEXE Folder using version is :%s\r\n\r\nThe version should be %s\r\n\r\n", strSMCVersion[0], strSMCVersion[1], CSMCDLLRevision);

        if(ret==1)
        {
            strtemp.sprintf("Please install packages [SMC_Driver_V%s], and restart the computer!! ", CSMCDLLRevision);
        }
        else if(ret==2)
        {
            strtemp.sprintf("Please check file[CSMC.dll] on path:[%s]", ExtractFilePath(Application->ExeName));
        }
        else                                                                    //ret==3，都錯
        {
            strtemp.sprintf("Please install packages [SMC_Driver_V%s],\r\ncheck file[CSMC.dll] on path:[%s] and restart the computer!! ", CSMCDLLRevision, ExtractFilePath(Application->ExeName));
        }
        str+=strtemp+"\r\n\r\n";

        MessageDlg(str, mtConfirmation, TMsgDlgButtons()<<mbOK, 0);

        return false;
    }
    return true;
}
//------------------------------------------------------------------------------
int DoCheckSMCDLLVersion()                                                      //Isaac 20190606 : SMCC.dll版本檢查
{
    AnsiString strFilePath[2]={"", ""};
    WORD iFileVerMajor=0, iFileVerMinor=0, iFileVerRelease=0, iFileVerBuild=0;

    strFilePath[0]="C:\\Windows\\System32\\CSMC.dll";
    strFilePath[1]=ExtractFilePath(Application->ExeName)+"\\CSMC.dll";

    for(int i=0; i<2 ; i++)
    {
        VerInfo().GetAppVersion(strFilePath[i], iFileVerMajor, iFileVerMinor, iFileVerRelease, iFileVerBuild);
        strSMCVersion[i].sprintf("%d.%d.%d.%d", iFileVerMajor, iFileVerMinor, iFileVerRelease, iFileVerBuild);
    }

    if(strSMCVersion[0]!=CSMCDLLRevision && strSMCVersion[1]!=CSMCDLLRevision)
    {
        return 3;
    }
    else if(strSMCVersion[0]!=CSMCDLLRevision)
    {
        return 1;
    }
    else if(strSMCVersion[1]!=CSMCDLLRevision)
    {
        return 2;
    }
    else
    {
        return 0;
    }
}
//------------------------------------------------------------------------------
bool CheckATPDLLVersion()                                                       //JerryYang 20220317 : Check ATP remote control dll version
{
    AnsiString str="",strtemp="";
    int ret=-1;
    if(CosFunction.bDLLCommands==false)
        return true;

    ret=DoCheckATPDLLVersion();
    if(ret!=0)
    {
        str.sprintf("NsHandlerAgentUtils.dll using version is :%s \r\nThe version should be %s\r\n\r\n", sATPDLLVersion, ATPDLLVersion);
        strtemp.sprintf("Please use the instller to get [NsHandlerAgentUtils.dll_V%s]!! ", ATPDLLVersion);
        str+=strtemp+"\r\n\r\n";
        MessageDlg(str, mtConfirmation, TMsgDlgButtons()<<mbOK, 0);
        return false;
    }
    return true;
}
//------------------------------------------------------------------------------
int DoCheckATPDLLVersion()                                                      //JerryYang 20220317 : Check ATP remote control dll version
{
    AnsiString strFilePath="";
    unsigned short iFileVerMajor=0, iFileVerMinor=0, iFileVerRelease=0, iFileVerBuild=0;
    strFilePath="C:\\Windows\\System32\\NsHandlerAgentUtils.dll";

    VerInfo().GetAppVersion(strFilePath, iFileVerMajor, iFileVerMinor, iFileVerRelease, iFileVerBuild);
    sATPDLLVersion.sprintf("%d.%d.%d.%d", iFileVerMajor, iFileVerMinor, iFileVerRelease, iFileVerBuild);
    if(sATPDLLVersion!=ATPDLLVersion)
    {
        return 1;
    }
    else
    {
        return 0;                                                               //OK
    }
}
