void __fastcall TfMain::AdjZLedPos()
{
    TALed *Ptr[][MAX_SOCKET_COL]=                                               //4->8
    {
        {ledInArmAa, ledInArmAb, ledInArmAc, ledInArmAd ,ledInArmAe, ledInArmAf, ledInArmAg, ledInArmAh},
        {ledInArmBa, ledInArmBb, ledInArmBc, ledInArmBd ,ledInArmBe, ledInArmBf, ledInArmBg, ledInArmBh},
        {ledOutArmAa, ledOutArmAb, ledOutArmAc, ledOutArmAd ,ledOutArmAe, ledOutArmAf, ledOutArmAg, ledOutArmAh},
        {ledOutArmBa, ledOutArmBb, ledOutArmBc, ledOutArmBd ,ledOutArmBe, ledOutArmBf, ledOutArmBg, ledOutArmBh}
    };

    if(USE_PICKER_COUNT==ep1Picker)
    {
        for(int i=0; i<4; i++)
            for(int j=0; j<8; j++)
                Ptr[i][j]->Visible=false;

        ledInArmAa->Visible=true;
        ledOutArmAa->Visible=true;
        pnlInArmX->Width=35;
        pnlOutArmX->Width=35;
    }
    else if(USE_IN_OUT_ARM_Y_PITCH!=iXYPitch16Picker &&
            USE_IN_OUT_ARM_Y_PITCH!=iXYPitch16Bd_Be)
    {
        for(int i=0; i<4; i++)
            for(int j=4; j<8; j++)
                Ptr[i][j]->Visible=false;
        pnlInArmX->Width=92;
        pnlOutArmX->Width=92;
    }
}
//----------------------------------------------------------------------------
void __fastcall TfMain::MainFormChange()
{
    int i, j;
    int iCol=0;
    bool SingleRow=false;

    //Eliot 2009_12_25 start
    TALed *Ptr[][MAX_SOCKET_COL]=                                               //4->8
    {
        {led_BLCarryKit_0,led_BL2CarryKit_0,led_BLCarryKit_1,led_BL2CarryKit_1,led_BL3CarryKit_0,led_BL4CarryKit_0,led_BL3CarryKit_1,led_BL4CarryKit_1},
        {led_BLCarryKit_2,led_BL2CarryKit_2,led_BLCarryKit_3,led_BL2CarryKit_3,led_BL3CarryKit_2,led_BL4CarryKit_2,led_BL3CarryKit_3,led_BL4CarryKit_3},

        {led_BRCarryKit_0,led_BR2CarryKit_0,led_BRCarryKit_1,led_BR2CarryKit_1,led_BR3CarryKit_0,led_BR4CarryKit_0,led_BR3CarryKit_1,led_BR4CarryKit_1},
        {led_BRCarryKit_2,led_BR2CarryKit_2,led_BRCarryKit_3,led_BR2CarryKit_3,led_BR3CarryKit_2,led_BR4CarryKit_2,led_BR3CarryKit_3,led_BR4CarryKit_3},

        {led_BTestSuckAa,led_BTestSuckAb,led_BTestSuckAc,led_BTestSuckAd,led_BTestSuckAe,led_BTestSuckAf,led_BTestSuckAg,led_BTestSuckAh},
        {led_BTestSuckBa,led_BTestSuckBb,led_BTestSuckBc,led_BTestSuckBd,led_BTestSuckBe,led_BTestSuckBf,led_BTestSuckBg,led_BTestSuckBh},

        {led_FTestSuckAa,led_FTestSuckAb,led_FTestSuckAc,led_FTestSuckAd,led_FTestSuckAe,led_FTestSuckAf,led_FTestSuckAg,led_FTestSuckAh},
        {led_FTestSuckBa,led_FTestSuckBb,led_FTestSuckBc,led_FTestSuckBd,led_FTestSuckBe,led_FTestSuckBf,led_FTestSuckBg,led_FTestSuckBh},

        {led_FLCarryKit_0,led_FL2CarryKit_0,led_FLCarryKit_1,led_FL2CarryKit_1,led_FL3CarryKit_0,led_FL4CarryKit_0,led_FL3CarryKit_1,led_FL4CarryKit_1},
        {led_FLCarryKit_2,led_FL2CarryKit_2,led_FLCarryKit_3,led_FL2CarryKit_3,led_FL3CarryKit_2,led_FL4CarryKit_2,led_FL3CarryKit_3,led_FL4CarryKit_3},

        {led_FRCarryKit_0,led_FR2CarryKit_0,led_FRCarryKit_1,led_FR2CarryKit_1,led_FR3CarryKit_0,led_FR4CarryKit_0,led_FR3CarryKit_1,led_FR4CarryKit_1},
        {led_FRCarryKit_2,led_FR2CarryKit_2,led_FRCarryKit_3,led_FR2CarryKit_3,led_FR3CarryKit_2,led_FR4CarryKit_2,led_FR3CarryKit_3,led_FR4CarryKit_3},

        {ledSocketAa,ledSocketAb,ledSocketAc,ledSocketAd,ledSocketAe,ledSocketAf,ledSocketAg,ledSocketAh},
        {ledSocketBa,ledSocketBb,ledSocketBc,ledSocketBd,ledSocketBe,ledSocketBf,ledSocketBg,ledSocketBh},
        {ledSocketCa,ledSocketCb,ledSocketCc,ledSocketCd,ledSocketCe,ledSocketCf,ledSocketCg,ledSocketCh},
        {ledSocketDa,ledSocketDb,ledSocketDc,ledSocketDd,ledSocketDe,ledSocketDf,ledSocketDg,ledSocketDh}
    };

    TALed *PtrSort[][MAX_SOCKET_COL]=                                           //RogerYang 20250506 Add for 9046AU
    {
        {led_SortShtKit_0,led_SortSht2Kit_0,led_SortShtKit_1,led_SortSht2Kit_1,led_SortSht3Kit_0,led_SortSht4Kit_0,led_SortSht3Kit_1,led_SortSht4Kit_1},
        {led_SortShtKit_2,led_SortSht2Kit_2,led_SortShtKit_3,led_SortSht2Kit_3,led_SortSht3Kit_2,led_SortSht4Kit_2,led_SortSht3Kit_3,led_SortSht4Kit_3}
    };

    for(i=0; i<16; i++)                                                         //ChungHung 20130708 alter 14--->16
        for(j=0; j<8; j++)
            Ptr[i][j]->Visible=false;

    for(i=0; i<2; i++)                                                          //RogerYang 20250506 Add for 9046AU
    {
        for(j=0; j<8; j++)
        {
            PtrSort[i][j]->Visible=false;
        }
    }

    if(TestIF_File.iTestMode==DualSite)                                         //1x2
    {
        SingleRow=true;
        iCol=2;
    }
    else if(TestIF_File.iTestMode==SingleSite)                                  //1x1 SingleSite
    {
        SingleRow=true;
        iCol=1;
    }
    else if(TestIF_File.iTestMode==TriSite1X3)                                  //1x3 //Frank 20160329 add for 1x3_4
    {
        SingleRow=true;
        iCol=3;
    }
    else if(TestIF_File.iTestMode==_6Site2X3N)                                  //Steven 20220425 : 2X3NN Mode
    {
        iCol=3;
    }
    else if(TestIF_File.iTestMode==QualSite1X4)                                 //1x4
    {
        SingleRow=true;
        iCol=4;
    }
    else if(TestIF_File.iTestMode==_8Site2X4N)                                  //Wei 20231211 : 2X4NN Mode
    {
        iCol=4;
    }
    else if(TestIF_File.iTestMode==DualSite2x1)                                 //2x1
    {
        iCol=1;
    }
    else if(TestIF_File.iTestMode==QualSite2X2N)                                //2x2       //Frank 20200520 2X2NN Mode
    {
        iCol=2;
    }
    else if(TestIF_File.iTestMode==QualSite2X2)                                 //2x2
    {
        iCol=2;
    }
    else if(TestIF_File.iTestMode==_6Site2X3)                                   //ChungHung 20140115 add for 2x3_6
    {
        iCol=4;
    }
    else if(TestIF_File.iTestMode==_8Site1X4)                                   //ChungHung 20150528 add for 海思 _8Site1x4
    {
        SingleRow=true;
        iCol=4;
    }
    else if(TestIF_File.iTestMode==_8Site2X4 || TestIF_File.iTestMode==_16Site4X4)                                      //Sam 20190226 : 16Site4X4 //2x4
    {
        iCol=4;
    }
    else if(TestIF_File.iTestMode==_16Site2X8)                                  //2x8  //Eliot 2009_12_25
    {
        iCol=8;
    }
    else if(TestIF_File.iTestMode==_12Site2X6)                                  //2x6
    {
        iCol=8;
    }
    else if(TestIF_File.iTestMode==_10Site2X5)                                  //2x5  //wei 20190614 10 site
    {
        iCol=8;
    }
    else if(TestIF_File.iTestMode==_32Site4X8M || TestIF_File.iTestMode==_32Site4X8N)                                   //4x8
    {
        iCol=8;
    }

    for(i=0; i<14; i++)
    {
        for(j=0; j<iCol; j++)
        {
            if(SingleRow && i%2==0)
            {
                Ptr[i][j]->Visible=true;
            }
            else
            {
                if(SingleRow==false)
                    Ptr[i][j]->Visible=true;
            }
        }
    }

    for(i=0; i<2; i++)                                                          //RogerYang 20250506 Add for 9046AU
    {
        for(j=0; j<iCol; j++)
        {
            if(SingleRow && i%2==0)
            {
                PtrSort[i][j]->Visible=true;
            }
            else
            {
                if(SingleRow==false)
                    PtrSort[i][j]->Visible=true;
            }
        }
    }

    if(IsNNMode()==NN_1Row)
    {
        for(i=0; i<12; i++)
        {
            for(j=0; j<iCol; j++)
            {
                if(i%2==1)
                    Ptr[i][j]->Visible=false;
            }
        }

        for(i=0; i<2; i++)                                                      //RogerYang 20250506 Add for 9046AU
        {
            for(j=0; j<iCol; j++)
            {
                if(i%2==1)
                    PtrSort[i][j]->Visible=false;
            }
        }
    }

    if(IsNNMode()==NN_2Row)
    {
        for(i=14; i<16; i++)
        {
            for(j=0; j<iCol; j++)
            {
                Ptr[i][j]->Visible=true;
            }
        }
    }

    //jou 980717 start : add from ht9040 show alarm enabled
    AnsiString S;
    if(IniConfig.bG04ShowFailAlarmCount)
    {
        labFailAlarmCnt->Visible=true;
        S="Fail alarm count:";

        if(Prod.bContsFailBySocket)
        {
            S+="All=";
            S+=AnsiString(Prod.iContsFailSocketAlarmCT);
            S+="  ";
        }

        if(Prod.bContsFailByHead)
        {
            S+="Site=";
            S+=AnsiString(Prod.iContsFailHeadAlarmCT);
            S+="  ";
        }
        labFailAlarmCnt->Caption=S;
    }
    else
    {
        labFailAlarmCnt->Visible=false;
        labFailAlarmCnt->Caption="";
    }
    //jou 980717 end
}
//------------------------------------------------------------------------------
void __fastcall TfMain::ProcessKeyFlush()
{
    static bool Oldflag;
    int i;
    TBtnPanel *Ptr[7]={BtnReset, BtnHome, BtnAlarmReset, BtnCleanOut, BtnPause, BtnStart, BtnTrayEnd};
    if(fNote->fShow)
        return;
    if(MyMessageBox->fShow)
        return;
    if(SystemStart)
    {
        if(BtnCleanOut->Enabled)   BtnCleanOut->Enabled=false;
        if(BtnTrayEnd->Enabled)    BtnTrayEnd->Enabled=false;
        if(BtnHome->Enabled)       BtnHome->Enabled=false;
        if(BtnReset->Enabled)      BtnReset->Enabled=false;
        if(BtnAlarmReset->Enabled) BtnAlarmReset->Enabled=false;
    }
    else
    {
        if(fAllMotorHome==false || iOneCycle)
        {
            if(BtnCleanOut->Enabled)    BtnCleanOut->Enabled=false;
            if(BtnTrayEnd->Enabled)     BtnTrayEnd->Enabled=false;
            //if(BtnReset->Enabled)       BtnReset->Enabled=false;   //ChungHung 20120524 delete
            if(IniConfig.bO01_ResetNeedClearAndCheckHP)
            {
                if(fAllMotorHome==false)
                {
                    if(BtnReset->Enabled)
                        BtnReset->Enabled=false;
                }
                else
                {
                    if(!BtnReset->Enabled)
                        BtnReset->Enabled=true;
                }
            }
            else
            {
                if(BtnReset->Enabled)   BtnReset->Enabled=false;
            }

            if(BtnAlarmReset->Enabled)  BtnAlarmReset->Enabled=false;
        }
        else
        {
            if(!BtnCleanOut->Enabled)   BtnCleanOut->Enabled=true;
            if(!BtnTrayEnd->Enabled)    BtnTrayEnd->Enabled=true;
            if(!BtnReset->Enabled)      BtnReset->Enabled=true;
            if(!BtnAlarmReset->Enabled) BtnAlarmReset->Enabled=true;
        }

        if(!BtnHome->Enabled)           BtnHome->Enabled=true;
    }
    for(i=0; i<7; i++)
        if(Ptr[i]->Down)
            Ptr[i]->Down=false;

    if(BtnPause->Down || BtnStart->Down)
        return;

    static bool OldSystemStart=true;
    OldSystemStart=SystemStart;

    if(OldSystemStart)                                                          // now machine is running
    {
        BtnStart->FalseColor=clBlue;
        BtnStart->FalseFontColor=clYellow;
        BtnPause->FalseColor=(TColor)0x00804000;
        BtnPause->FalseFontColor=clSilver;
        bLampStart=true;
        bLampPause=false;
    }
    else
    {
        if(bMotorPowerState==true && MotorPowerOnDelay==0)
        {
            BtnPause->FalseColor=clBlue;
            BtnPause->FalseFontColor=clYellow;
        }
        else
        {
            BtnPause->FalseColor=(TColor)0x00804000;
            BtnPause->FalseFontColor=clSilver;
        }

        BtnStart->FalseColor=(TColor)0x00804000;
        BtnStart->FalseFontColor=clSilver;
        bLampStart=false;
        bLampPause=true;
    }

    if(Oldflag!=FlushFlag && bMotorPowerState==true && MotorPowerOnDelay==0)
    {
        Oldflag=FlushFlag;
        if(OldSystemStart)
        {
            if(Oldflag)
                BtnPause->FalseFontColor=clSilver;
            else
                BtnPause->FalseFontColor=(TColor)0x00804000;
        }
        else
        {
            if(Oldflag)
                BtnStart->FalseFontColor=clSilver;
            else
                BtnStart->FalseFontColor=(TColor)0x00804000;
        }
    }

    if(BtnOneCycle->Down)
    {
        if(iOneCycle==0 && bOneCycle_BackUp==false && BtnOneCycle->TrueColor!=(TColor)0x00804000)                       //JerryYang 20161223 (jou) 修正one cycle燈號未即時亮起
            BtnOneCycle->TrueColor=(TColor)0x00804000;
        else if((iOneCycle || bOneCycle_BackUp==false) && BtnOneCycle->TrueColor!=clYellow)
            BtnOneCycle->TrueColor=clYellow;
    }

    if(iOneCycle)
    {
        BtnOneCycle->TrueFontColor=clBlue;
    }
    else
    {
        if(BtnOneCycle->Enabled)   BtnOneCycle->TrueFontColor=clWhite;
        else                       BtnOneCycle->TrueFontColor=clBlue;
    }
    int *iPtr[5]={&iCleanOut, &iReset, &iHome, &iTrayFeed};
    bool *lamp[5]={&bLampCleanOut, &bLampReset, &bLampHome, &bLampTrayFeed};
    TBtnPanel *ptrBtnPanel[5]={BtnCleanOut, BtnReset, BtnHome, BtnTrayEnd};
    for(i=0; i<4; i++)
    {
        if(*iPtr[i])
        {
            if(ptrBtnPanel[i]->FalseColor!=clYellow)
                ptrBtnPanel[i]->FalseColor=clYellow;
            if(ptrBtnPanel[i]->Enabled)
                ptrBtnPanel[i]->FalseFontColor=clBlue;
            else
                ptrBtnPanel[i]->FalseFontColor=clSilver;
            ptrBtnPanel[i]->FalseFontColor=clBlue;
            *lamp[i]=true;
        }
        else
        {
            if(ptrBtnPanel[i]->FalseColor!=(TColor)0x00804000)
                ptrBtnPanel[i]->FalseColor=(TColor)0x00804000;
            if(ptrBtnPanel[i]->Enabled)
                ptrBtnPanel[i]->FalseFontColor=clWhite;
            else
                ptrBtnPanel[i]->FalseFontColor=clBlue;
            if(ptrBtnPanel[i]->Enabled)
                ptrBtnPanel[i]->FalseFontColor=clWhite;
            else
                ptrBtnPanel[i]->FalseFontColor=clBlue;
            *lamp[i]=false;
        }
    }

    if(bAlarmBuzzer)
    {
        bLampAlarmReset=FlushFlag;
    }
}
