//------------------------------------------------------------------------------
bool TfMain::ResetServoOff()                                                    //Steven 20120322 : 按下Reset後,要Servo Off In Out Arm
{
    bool bServoOff=false;
    if(IniConfig.bResetCanServoOff)                                             //Steven 20111228 : 按下Reset時,若In/Out Arm沒IC,就Servo Off
    {
        if(fAllMotorHome==true && SoftStart==false)
        {
            if(InArmSuck.HasIC() || OutArmSuck.HasIC() || ShuttleHasIC() ||
               IndexHasIC())
            {
                if(IniConfig.bResetPutUntestToErrorBin)                         //Steven 20120924 : For SCS, 使用Reset Mode,但是已測的要繼續分Bin
                {
                    if(fNote->bMyServoOffInArm==false)
                    {
                        if(InArmZSafe(DETECT_ALL_FLAG)==-1)                     //如果Z軸在上才可以推
                        {
                            fNote->iMyServoOffInArmPosX=MOT[MInArmX].ReadEncoderPos();
                            fNote->iMyServoOffInArmPosY=MOT[MInArmY].ReadEncoderPos();                                  //要在ServoOff之前
                            MySleep(200);
                            MOT[MInArmX].ServoOnOff(false);
                            MOT[MInArmY].ServoOnOff(false);

                            fNote->bMyServoOffInArm=true;
                            bServoOff=true;
                        }
                    }

                    if(fNote->bMyServoOffOutArm==false)
                    {
                        if(OutArmZSafe(DETECT_ALL_FLAG)==-1)                    //如果Z軸在上才可以推
                        {
                            fNote->iMyServoOffOutArmPosX=MOT[MOutArmX].ReadEncoderPos();
                            fNote->iMyServoOffOutArmPosY=MOT[MOutArmY].ReadEncoderPos();                                //要在ServoOff之前
                            MySleep(200);
                            MOT[MOutArmX].ServoOnOff(false);
                            MOT[MOutArmY].ServoOnOff(false);
                            fNote->bMyServoOffOutArm=true;
                            bServoOff=true;
                        }
                    }
                }
            }
            else
            {
                //ChungHung 20120912 Hangup 解除
                if(fNote->bMyServoOffInArm==false && (MOT[MInArmX].IsCanMove() && MOT[MInArmY].IsCanMove()))
                {
                    if(InArmZSafe(DETECT_ALL_FLAG)==-1)                         //如果Z軸在上才可以推
                    {
                        fNote->iMyServoOffInArmPosX=MOT[MInArmX].ReadEncoderPos();
                        fNote->iMyServoOffInArmPosY=MOT[MInArmY].ReadEncoderPos();                                      //要在ServoOff之前
                        MySleep(200);
                        MOT[MInArmX].ServoOnOff(false);
                        MOT[MInArmY].ServoOnOff(false);

                        fNote->bMyServoOffInArm=true;
                        bServoOff=true;
                    }
                }
                //ChungHung 20120912 Hangup 解除
                if(fNote->bMyServoOffOutArm==false && (MOT[MOutArmX].IsCanMove() && MOT[MOutArmY].IsCanMove()))
                {
                    if(OutArmZSafe(DETECT_ALL_FLAG)==-1)                        //如果Z軸在上才可以推
                    {
                        fNote->iMyServoOffOutArmPosX=MOT[MOutArmX].ReadEncoderPos();
                        fNote->iMyServoOffOutArmPosY=MOT[MOutArmY].ReadEncoderPos();                                    //要在ServoOff之前
                        MySleep(200);
                        MOT[MOutArmX].ServoOnOff(false);
                        MOT[MOutArmY].ServoOnOff(false);
                        fNote->bMyServoOffOutArm=true;
                        bServoOff=true;
                    }
                }
            }

            if(bServoOff)
                return true;
        }
    }
    return false;
}
