//------------------------------------------------------------------------------
bool __fastcall TfMain::Reset(AnsiString Func)                                  //kevin 20141108
{
    int iAuto, ret;                                                             //JerryYang 20151007 : ResetMode可選OneCycle或CleanOut
    AnsiString asString;

    if(bSECSGEMAlarm==true &&
       CUSTOMER_CODE==CC_KYEC_LEE &&
       bEnableEmployeeIDCheck)                                                  //Ifor 20180910 :Add KYEC ID確認流程中鎖定面板
        return false;
    if(bEnableEmployeeIDCheck==true)                                            //Ifor 20180911 (Steven) : Add 啟動 Employee ID Check
        return false;
    if(IniConfig.bA17RESETButtonDisable)                                        //kevin 20170502 (wei) Disible Reset
        return false;

    if(bOutShuttleMissIC==false)                                                //wei 20160509 Out Shuttle Miss IC
    {
        if(SystemStart==true || bResetMode==true ||                             //must in system pause
            bResetModeAndCleanOut==true)                                        //JerryYang 20151007 : ResetMode可選OneCycle或CleanOut
            return false;
        if(fAllMotorHome==false)
            return false;
        if(SoftStart)                                                           //must in system pause
            return false;                                                       //kevin 20141108

        if(bRunAutoClean)                                                       //Jou 2014-03-11 : Auto Clean時不能Reset
            return false;                                                       //kevin 20141108
    }

    NewRecordProcess("MES2113", "RESET pressed", Func);

    if(IniConfig.bEnable_SECS_GEM==true)                                        //Steven 20140528 : Secs Gem
        EventReport(SECS_EVENT.DoReset);                                        //33     按下 Reset

    IsTest=false;                                                               //JerryYang 20160318 增加防護 RESET時要重置GPIB
    RunTestProgram(false);

    if(IniConfig.bResetPutUntestToErrorBin)                                     //Steven 20120924 : For SCS, 使用Reset Mode,但是已測的要繼續分Bin
    {
        if(IniConfig.bNewResetFunction && bRunAutoClean==false)                 //Steven 20130625 : 新的Reset方式
        {
            iReset=1;
            bResetIsPressed=true;
        }
        else
        {
            if(BtnOneCycle->Down==false)
            {
                InitOneCycle("Reset Put Untest To Error Bin");
                BtnOneCycle->Down=true;
            }
        }

        for(int i=0; i<MAX_Index_Row; i++)
        {
            for(int j=0; j<NEW_MAX_Index_Col; j++)
            {
                if(FTestSuck.Item[i][j]!=NULL_IC && FTestSuck.Item[i][j]!=HAS_NULL_IC && FTestSuck.Item[i][j]<TEST_PASS)
                {
                    FTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    FTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, FTestSuck.cSBin[i][j], "RESET");         //Frank 20160505 add
                }

                if(BTestSuck.Item[i][j]!=NULL_IC && BTestSuck.Item[i][j]!=HAS_NULL_IC && BTestSuck.Item[i][j]<TEST_PASS)
                {
                    BTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    BTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, BTestSuck.cSBin[i][j], "RESET");         //Frank 20160505 add
                }

                if(TestSocket.Item[i][j]!=NULL_IC && TestSocket.Item[i][j]!=HAS_NULL_IC && TestSocket.Item[i][j]<TEST_PASS)
                {
                    TestSocket.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    TestSocket.PordRec[i][j].AddTestResultRecord(iTestBinCount, TestSocket.cSBin[i][j], "RESET");       //Frank 20160505 add
                }
            }
        }

        if(bBin16HangUp)                                                        //Steven 20100412 Start: For Bin 15 Hang Up
        {
            fMain->CloseGpibProgram(__FUNC__);
            bBin16HangUp=false;
        }

        Cylinder[C_LoaderCarEdgePush].Off();                                    //Jimmychiu 20220408 解開Loader側邊固定
        Cylinder[C_TrayY_Fixer].Off();
        Cylinder[C_LoaderEdgePush].Off();
        Cylinder[C_LoaderUpPress].Off();                                        //JerryYang 20181120 (Steven) : (Steven) : 獨立控制loader壓tray
        for(int i=eAuto1; i<=iAutoRight; i++)
        {
            iAuto=iAutoIndex[i];
            Cylinder[C_AutoSide_Fixer[iAuto]].Off();
            Cylinder[C_AutoEdgePush[iAuto]].Off();
            Cylinder[C_AutoUpPress[iAuto]].Off();                               //JerryYang 20190423 新增unloader壓tray
        }

        ResetServoOff();

        bLampReset=true;

        if(IniConfig.bNewResetFunction==false)
        {
            bResetMode=true;
            OutArmTask=1;
            InitInArmTask();
        }

        iWhoTriggerPiggyBack=pbtReset;                                          //Steven 20111207 : 誰觸發了Piggy Back

        //jou 2010-11-23 start
        asString.sprintf("Reset Record: InArm=%d , OutArm=%d , InSH1=%d , InSH2=%d",
            InArmSuck.CountRealIC(),
            OutArmSuck.CountRealIC(),
            FLCarryKit.CountRealIC(),
            BLCarryKit.CountRealIC());
        MyDBIProcess("Message", asString);
        asString.sprintf("Reset Record: OutSH1=%d , OutSH2=%d , Index1=%d , Index2=%d",
            FRCarryKit.CountRealIC(),
            BRCarryKit.CountRealIC(),
            FTestSuck.CountRealIC(),
            BTestSuck.CountRealIC());
        MyDBIProcess("Message", asString);
        asString.sprintf("Reset Record: Total=%d",
            InArmSuck.CountRealIC()+
            OutArmSuck.CountRealIC()+
            FLCarryKit.CountRealIC()+
            BLCarryKit.CountRealIC()+
            FRCarryKit.CountRealIC()+
            BRCarryKit.CountRealIC()+
            FTestSuck.CountRealIC()+
            BTestSuck.CountRealIC());
        MyDBIProcess("Message", asString);
        //jou 2010-11-23 end
    }
    else if(IniConfig.bO01_ResetNeedClearAndCheckHP &&
            bCanUseHotPlateCheck &&                                             //Steven 20120322 : RESET後,清空In Arm吸嘴資料與HotPlate資料,然後作HotPlate檢查
            IniConfig.bResetClearArmIC==false)                                  //Steven 20120920 : 要清手臂上IC的,暫時不檢查HotPlate
    {
        InArmSuck.ClearAll();

        MOT[MMPlate1].Tray.ClearData();
        MOT[MMPlate2].Tray.ClearData();
         //ChungHung 20120418 delete
        bNeedTrySuckHotPlate=true;                                              //ChungHung 20120206 Hotplate check
        bOneTimeHotPlateCheckAll=true;                                          //ChungHung 20120206 Hotplate check
        bTryPickFromHotPlateShowError=false;                                    //ChungHung 20120206 Hotplate check
        bTrySuckHotPlateOneCycle=false;
        bTrySuckHotPlateCleanOut=false;
        bHotPlateCheckNeedTrayFeed=false;                                       //Steven 20120322
        //ChungHung 20120418 delete
        //ChungHung 20120525 add
        iCleanOut=0;
        iOneCycle=0;
        //ChungHung 20120525 add
        //InitialTrayFeedTask(); //ChungHung 20120418 delete
        ResetHotPlateSearchParameter();
        InitInArmTask();
        bPlaceToHotplate=false;
        bPickFromHotplate=false;
        MOT[MInShuttle1].EnableMotorMove();
        MOT[MInShuttle2].EnableMotorMove();
        ShowMyMessage("Please remove the devices on in arm picker!", "", "", false, true);
    }
    else
    {
        if(ResetServoOff())
            return false;                                                       //kevin 20141108

        if(IniConfig.bResetClearArmIC)                                          //Steven 20120830 : Reset按下時,把吸嘴上的IC清空
        {
            if(IniConfig.bO02ResetNotClearPlate)
            {
                MOT[MMPlate1].Tray.ClearData();
                MOT[MMPlate2].Tray.ClearData();
                ResetHotPlateSearchParameter();
            }
            Cylinder[C_TrayY_Fixer].Off();
            Cylinder[C_LoaderEdgePush].Off();
            Cylinder[C_LoaderUpPress].Off();                                    //JerryYang 20181120 (Steven) : (Steven) : 獨立控制loader壓tray
            for(int i=0; i<6; i++)                                              //Steven 20230907 : For HT-9011UC
            {
                iAuto=iAutoIndex[i];
                Cylinder[C_AutoSide_Fixer[iAuto]].Off();
                Cylinder[C_AutoEdgePush[iAuto]].Off();
                Cylinder[C_AutoUpPress[iAuto]].Off();                           //JerryYang 20190423 新增unloader壓tray
            }

            InArmSuck.ClearAll();
            FLCarryKit.ClearAll();
            FRCarryKit.ClearAll();
            BLCarryKit.ClearAll();
            BRCarryKit.ClearAll();
            FTestSuck.ClearAll();
            BTestSuck.ClearAll();
            OutArmSuck.ClearAll();
            TestSocket.ClearAll();
            fAllMotorHome=false;
            //iHome=true;   kevin 20160321
            iHome=1;
            bLampReset=true;
            bFinshTest=true;
            bInitStartDelayNotFinish=true;                                      //Ifor 20181220 : add Init Start Delay Time Not Finish
            bTJControlMode=false;                                               //Ifor 20190328 : add TJ Temp Over Range
            bRearHeadICFallDown=false;
            SetInitialICCheck();

            //Eliot 2010_03_05 start
            if(IniConfig.bO05ResetNeedRemoveAllTray)
            {
                for(int i=iFixMin; i<=iFixMax; i++)
                {
                    ClearFixTray(i, "Reset");                                   //Steven 20160414 : 整合Fix盤設定
                }

                MOT[MTrayX].ClearTray(__FUNC__);
                MOT[MMTrayY].ClearTray(__FUNC__);
                MOT[MMTrayY_Car].ClearTray(__FUNC__);

                for(int i=eAuto1; i<=iAutoRight; i++)
                {
                    MOT[iMMAuto[i]].ClearTray(__FUNC__);
                    MOT[iMMAuto_Car[i]].ClearTray(__FUNC__);
                }

                MOT[MMEmpty].ClearTray(__FUNC__);
                MOT[MMColor].ClearTray(__FUNC__);
                MOT[MMEmpty_Car].ClearTray(__FUNC__);
                MOT[MMColor_Car].ClearTray(__FUNC__);
                MOT[MMEmpty1].ClearTray(__FUNC__);
                MOT[MMEmpty1_Car].ClearTray(__FUNC__);

                if(CosFunction.bShowHPICCount)                                  //Steven 20221228 : 計算加熱盤IC數量
                {
                    fSortCT->pnlLoad->Caption=MOT[MMTrayY].Tray.HowManyIC();
                }
            }
            //Eliot 2010_03_05 end
        }
        else
        {
            if(IniConfig.bKoreaFunction)                                        //jou 981219 start : reset mode
            {
                if(fNote->fShow==false)
                {
                    return false;                                               //kevin 20141108
                }
            }

            if(CosFunction.bResetModeIncludeCleanOut && fNote->fShow==false)    //JerryYang 20151007 START:ResetMode可選Onecycle或CleanOut
            {
                if(bResetNotMsg)                                                //Sam 20240215 : Tester time out show reset all ic
                    ret=K_CLEAN_OUT;
                else
                    ret=ShowErrorMessage("MES1652", K_ONECYCLE|K_CLEAN_OUT, MMSystem, false, "Main--Reset");            //ResetMode可選Onecycle或CleanOut

                if(ret==K_ONECYCLE)
                {
                    if(BtnOneCycle->Down==false)
                    {
                        InitOneCycle("ResetModeIncludeCleanOut");
                        BtnOneCycle->Down=true;
                        bResetMode=true;
                    }
                }
                else if(ret==K_CLEAN_OUT)
                {
                    if(BtnCleanOut->Down==false)
                    {
                        InitCleanOutFunction();
                        BtnCleanOut->Down=true;
                        bResetModeAndCleanOut=true;
                    }
                }
            }
            else
            {
                bResetMode=true;                                                //JerryYang 20250430 : fix One cycle的時候沒有跳reset finish
                if(BtnOneCycle->Down==false)
                {
                    InitOneCycle("RESET");
                    BtnOneCycle->Down=true;
                }
            }

            for(int i=0; i<MAX_Index_Row; i++)
            {
                for(int j=0; j<NEW_MAX_Index_Col; j++)
                {
                    if(FRCarryKit.Item[i][j]!=NULL_IC && FRCarryKit.Item[i][j]!=HAS_NULL_IC)
                    {
                        FRCarryKit.SetItemData(i, j, TEST_PASS+iTestBinCount);
                        FRCarryKit.PordRec[i][j].AddTestResultRecord(iTestBinCount, FRCarryKit.cSBin[i][j], "RESET");   //Frank 20160505 add
                    }

                    if(BRCarryKit.Item[i][j]!=NULL_IC && BRCarryKit.Item[i][j]!=HAS_NULL_IC)
                    {
                        BRCarryKit.SetItemData(i, j, TEST_PASS+iTestBinCount);
                        BRCarryKit.PordRec[i][j].AddTestResultRecord(iTestBinCount, BRCarryKit.cSBin[i][j], "RESET");   //Frank 20160505 add
                    }

                    if(FTestSuck.Item[i][j]!=NULL_IC && FTestSuck.Item[i][j]!=HAS_NULL_IC)
                    {
                        FTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                        FTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, FTestSuck.cSBin[i][j], "RESET");     //Frank 20160505 add
                    }

                    if(BTestSuck.Item[i][j]!=NULL_IC && BTestSuck.Item[i][j]!=HAS_NULL_IC)
                    {
                        BTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                        BTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, BTestSuck.cSBin[i][j], "RESET");     //Frank 20160505 add
                    }

                    if(TestSocket.Item[i][j]!=NULL_IC && TestSocket.Item[i][j]!=HAS_NULL_IC)
                    {
                        TestSocket.SetItemData(i, j, TEST_PASS+iTestBinCount);
                        TestSocket.PordRec[i][j].AddTestResultRecord(iTestBinCount, TestSocket.cSBin[i][j], "RESET");   //Frank 20160505 add
                    }
                }
            }

            for(int i=0; i<InArmSuck.iMaxRow; i++)
            {
                for(int j=0; j<InArmSuck.iMaxCol; j++)
                {
                    if(OutArmSuck.Item[i][j]!=NULL_IC && OutArmSuck.Item[i][j]!=HAS_NULL_IC)
                    {
                        OutArmSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                        OutArmSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, OutArmSuck.cSBin[i][j], "RESET");   //Frank 20160505 add
                        OutArmSuck.iWhichAuto[i][j]=Prod.iIfErrorT6;
                    }
                }
            }

            if(bBin16HangUp)                                                    //Steven 20100412 Start: For Bin 15 Hang Up
            {
                fMain->CloseGpibProgram(__FUNC__);
                bBin16HangUp=false;
            }

            OutArmTask=1;
            bLampReset=true;
            iWhoTriggerPiggyBack=pbtReset;                                      //Steven 20111207 : 誰觸發了Piggy Back

            asString.sprintf("Reset Record: InArm=%d , OutArm=%d , InSH1=%d , InSH2=%d",
                              InArmSuck.CountRealIC(),
                              OutArmSuck.CountRealIC(),
                              FLCarryKit.CountRealIC(),
                              BLCarryKit.CountRealIC());
            MyDBIProcess("Message", asString);
            asString.sprintf("Reset Record: OutSH1=%d , OutSH2=%d , Index1=%d , Index2=%d",
                              FRCarryKit.CountRealIC(),
                              BRCarryKit.CountRealIC(),
                              FTestSuck.CountRealIC(),
                              BTestSuck.CountRealIC());
            MyDBIProcess("Message", asString);
            asString.sprintf("Reset Record: Total=%d",
                              InArmSuck.CountRealIC()+
                              OutArmSuck.CountRealIC()+
                              FLCarryKit.CountRealIC()+
                              BLCarryKit.CountRealIC()+
                              FRCarryKit.CountRealIC()+
                              BRCarryKit.CountRealIC()+
                              FTestSuck.CountRealIC()+
                              BTestSuck.CountRealIC());
            MyDBIProcess("Message", asString);
        }
    }
    return true;                                                                //kevin 20141108
}
//------------------------------------------------------------------------------
void __fastcall TfMain::ResetForESC(AnsiString Msg)                             //Steven 20201022 : For RFMD Empty Socket Check Funstion.
{
    if(TestIF_File.iGpibMode==InterfaceType_15BinQorvo)                         //Steven 20201022 : For RFMD
    {
        if(bDoEmptySocketOneCycle==false)
        {
            bTriggerESC=true;
            RecordProcess(Msg);
        }
    }
}
//------------------------------------------------------------------------------
void __fastcall TfMain::ProcessForESC()                                         //Steven 20260121 : For RFMD Empty Socket Check Funstion.
{                                                                               //Steven 20220831 : 針對已測的, 還是要分Bin, 只針對未測的設定成Error Bin
    AnsiString asString;                                                        //Steven 20220817 : Bin of ESC function iTestBinCount --> IniConfig.iI41_BinOfESC
    if(TestIF_File.iGpibMode==InterfaceType_15BinQorvo &&                       //Steven 20201022 : For RFMD
       bTriggerESC==true &&
       IsTest==false &&
       TestSocket.HasIC()==false &&
       InArmSuck.CheckDestoryFinish()==true &&
       OutArmSuck.CheckDestoryFinish()==true &&
       FTestSuck.CheckDestoryFinish()==true &&
       BTestSuck.CheckDestoryFinish()==true)
    {
        iESC_IndexContactCount=0;
        bDoEmptySocketOneCycle=true;
        IsTest=false;                                                           //JerryYang 20160318 增加防護 RESET時要重置GPIB
        RunTestProgram(false);

        if(BtnOneCycle->Down==false)
        {
            InitOneCycle("Reset For ESC");
            BtnOneCycle->Down=true;
        }
        bResetMode=true;

        for(int i=0; i<MAX_Index_Row; i++)
        {
            for(int j=0; j<NEW_MAX_Index_Col; j++)
            {
                if(FTestSuck.Item[i][j]!=NULL_IC &&
                   FTestSuck.Item[i][j]!=HAS_NULL_IC &&
                   FTestSuck.Item[i][j]<TEST_PASS)
                {
                    FTestSuck.iBinData[i][j]=IniConfig.iI41_BinOfESC;
                    FTestSuck.SetItemData(i, j, TEST_PASS+IniConfig.iI41_BinOfESC);
                    FTestSuck.PordRec[i][j].AddTestResultRecord(IniConfig.iI41_BinOfESC, FTestSuck.cSBin[i][j], "RESET");                                       //Frank 20160505 add
                }

                if(BTestSuck.Item[i][j]!=NULL_IC &&
                   BTestSuck.Item[i][j]!=HAS_NULL_IC &&
                   BTestSuck.Item[i][j]<TEST_PASS)
                {
                    BTestSuck.iBinData[i][j]=IniConfig.iI41_BinOfESC;
                    BTestSuck.SetItemData(i, j, TEST_PASS+IniConfig.iI41_BinOfESC);
                    BTestSuck.PordRec[i][j].AddTestResultRecord(IniConfig.iI41_BinOfESC, BTestSuck.cSBin[i][j], "RESET");                                       //Frank 20160505 add
                }

                if(TestSocket.Item[i][j]!=NULL_IC && TestSocket.Item[i][j]!=HAS_NULL_IC &&
                   TestSocket.Item[i][j]<TEST_PASS)
                {
                    TestSocket.iBinData[i][j]=IniConfig.iI41_BinOfESC;
                    TestSocket.SetItemData(i, j, TEST_PASS+IniConfig.iI41_BinOfESC);
                    TestSocket.PordRec[i][j].AddTestResultRecord(IniConfig.iI41_BinOfESC, TestSocket.cSBin[i][j], "RESET");                                     //Frank 20160505 add
                }
            }
        }

        if(bBin16HangUp)
        {
            fMain->CloseGpibProgram(__FUNC__);
            bBin16HangUp=false;
        }

        OutArmTask=1;
        bLampReset=true;
        iWhoTriggerPiggyBack=pbtReset;                                          //Steven 20111207 : 誰觸發了Piggy Back

        asString.sprintf("Reset Record: InArm=%d , OutArm=%d , InSH1=%d , InSH2=%d",
                          InArmSuck.CountRealIC(),
                          OutArmSuck.CountRealIC(),
                          FLCarryKit.CountRealIC(),
                          BLCarryKit.CountRealIC());
        MyDBIProcess("Message", asString);
        asString.sprintf("Reset Record: OutSH1=%d , OutSH2=%d , Index1=%d , Index2=%d",
                          FRCarryKit.CountRealIC(),
                          BRCarryKit.CountRealIC(),
                          FTestSuck.CountRealIC(),
                          BTestSuck.CountRealIC());
        MyDBIProcess("Message", asString);
        asString.sprintf("Reset Record: Total=%d",
                          InArmSuck.CountRealIC()+
                          OutArmSuck.CountRealIC()+
                          FLCarryKit.CountRealIC()+
                          BLCarryKit.CountRealIC()+
                          FRCarryKit.CountRealIC()+
                          BRCarryKit.CountRealIC()+
                          FTestSuck.CountRealIC()+
                          BTestSuck.CountRealIC());
        MyDBIProcess("Message", asString);
        RecordProcess("Start RESET by Empty Socket Check...");
        bTriggerESC=false;
    }
}
//------------------------------------------------------------------------------
void __fastcall TfMain::ResetRecordforPiggyBack(AnsiString asWriteMessage)      //jou 2015-08-21 After conditional error, all units will go to Error bin ,follow by Index check or piggy back check
{                                                                               //jou 20171211 (Steven) : After index pick up error, device go to Error bin ,follow by Index check or piggy back check
    AnsiString asString;

    if(SystemStart==true || bResetMode==true||                                  //must in system pause
        bResetModeAndCleanOut==true)                                            //JerryYang 20151007 : ResetMode可選OneCycle或CleanOut
        return;
    if(fAllMotorHome==false)
        return;
    if(SoftStart)                                                               //must in system pause
        return;

    if(bRunAutoClean)                                                           //Jou 2014-03-11 : Auto Clean時不能Reset
        return;

    for(int i=0; i<MAX_Index_Row; i++)
    {
        for(int j=0; j<NEW_MAX_Index_Col; j++)
        {
            if(FLCarryKit.Item[i][j]!=NULL_IC && FLCarryKit.Item[i][j]!=HAS_NULL_IC)
            {
                FLCarryKit.SetItemData(i, j, TEST_PASS+iTestBinCount);
                FLCarryKit.PordRec[i][j].AddTestResultRecord(iTestBinCount, FLCarryKit.cSBin[i][j], asWriteMessage);    //Frank 20160505 add
            }

            if(BLCarryKit.Item[i][j]!=NULL_IC && BLCarryKit.Item[i][j]!=HAS_NULL_IC)
            {
                BLCarryKit.SetItemData(i, j, TEST_PASS+iTestBinCount);
                BLCarryKit.PordRec[i][j].AddTestResultRecord(iTestBinCount, BLCarryKit.cSBin[i][j], asWriteMessage);    //Frank 20160505 add
            }

            if(FTestSuck.Item[i][j]!=NULL_IC && FTestSuck.Item[i][j]!=HAS_NULL_IC)
            {
                FTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                FTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, FTestSuck.cSBin[i][j], asWriteMessage);      //Frank 20160505 add
            }

            if(BTestSuck.Item[i][j]!=NULL_IC && BTestSuck.Item[i][j]!=HAS_NULL_IC)
            {
                BTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                BTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, BTestSuck.cSBin[i][j], asWriteMessage);      //Frank 20160505 add
            }

            if(TestSocket.Item[i][j]!=NULL_IC && TestSocket.Item[i][j]!=HAS_NULL_IC)
            {
                TestSocket.SetItemData(i, j, TEST_PASS+iTestBinCount);
                TestSocket.PordRec[i][j].AddTestResultRecord(iTestBinCount, TestSocket.cSBin[i][j], asWriteMessage);    //Frank 20160505 add
            }
        }
    }

    for(int i=0; i<InArmSuck.iMaxRow; i++)
    {
        for(int j=0; j<InArmSuck.iMaxCol; j++)
        {
            if(LastSet.iTemperature==Tempture_Hot)                              //JerryYang 20210609 : 高溫模式input arm上的HAS_IC不需要設為ERROR BIN
            {
                if(InArmSuck.Item[i][j]!=NULL_IC && InArmSuck.Item[i][j]!=HAS_NULL_IC && InArmSuck.Item[i][j]!=HAS_IC)
                {
                    InArmSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    InArmSuck.iWhichAuto[i][j]=Prod.iIfErrorT6;
                    InArmSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, InArmSuck.cSBin[i][j], asWriteMessage);  //Frank 20160505 add
                }
            }
            else
            {
                if(InArmSuck.Item[i][j]!=NULL_IC && InArmSuck.Item[i][j]!=HAS_NULL_IC)
                {
                    InArmSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    InArmSuck.iWhichAuto[i][j]=Prod.iIfErrorT6;
                    InArmSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, InArmSuck.cSBin[i][j], asWriteMessage);  //Frank 20160505 add
                }
            }
        }
    }

    InitInArmTask();
    bIndexArmNoTestting=true;

    asString.sprintf("Reset Record: InArm=%d , InSH1=%d , InSH2=%d",
    InArmSuck.CountRealIC(),
    FLCarryKit.CountRealIC(),
    BLCarryKit.CountRealIC());
    MyDBIProcess("Message", asString);

    asString.sprintf("Reset Record:  Index1=%d , Index2=%d",
    FTestSuck.CountRealIC(),
    BTestSuck.CountRealIC());
    MyDBIProcess("Message", asString);
    asString.sprintf("Reset Record: Total=%d",
    InArmSuck.CountRealIC()+
    FLCarryKit.CountRealIC()+
    BLCarryKit.CountRealIC()+
    FTestSuck.CountRealIC()+
    BTestSuck.CountRealIC());
    MyDBIProcess("Message", asString);
}
