//------------------------------------------------------------------------------
void __fastcall TfMain::UnloaderInfo(TStringGrid *sgTemp)                       //ChungHung 20150205 add for ATK
{
    AnsiString aSiteName[32]={"Aa", "Ab", "Ac", "Ad", "Ae", "Af", "Ag", "Ah",
                              "Ba", "Bb", "Bc", "Bd", "Be", "Bf", "Bg", "Bh",
                              "Ca", "Cb", "Cc", "Cd", "Ce", "Cf", "Cg", "Ch",   //Steven 20240320 : 補上宣告
                              "Da", "Db", "Dc", "Dd", "De", "Df", "Dg", "Dh"};

    static bool flag=true;
    static int XItem, YItem;
    AnsiString Str;
    int iWhichUnloader=0;
    int iSite=0;
    int iArm=0;

    for(iSite=0; iSite<32; iSite++)                                             //Steven 20210806 : 修正UnloaderInfo的Site Map顯示
    {
        for(int i=0; i<MAX_SOCKET_ROW; i++)
        {
            for(int j=0; j<MAX_SOCKET_COL; j++)
            {
                if(TestIF_File.iSiteMap[i][j]-1>=0 &&
                   TestIF_File.iSiteMap[i][j]-1==iSite)
                {
                    aSiteName[iSite].sprintf("%c%c", 'A'+i, 'a'+j);
                }
            }
        }
    }

    if(cbUnloaderinfo->ItemIndex>=0)
    {
        iWhichUnloader=cbUnloaderinfo->ItemIndex;
    }

    if(flag || XItem!=MOT[iMMAuto[iWhichUnloader]].Tray.XItem || YItem!=MOT[iMMAuto[iWhichUnloader]].Tray.YItem)
    {
        XItem=MOT[iMMAuto[iWhichUnloader]].Tray.XItem;
        YItem=MOT[iMMAuto[iWhichUnloader]].Tray.YItem;

        sgTemp->ColCount=XItem+1;
        sgTemp->RowCount=YItem+1;
        if(ChangeToFloatNonPcnt((double)((sgTemp->Width-10)), (double)(sgTemp->ColCount))>0)
            sgTemp->DefaultColWidth=ChangeToFloatNonPcnt((double)((sgTemp->Width-10)), (double)(sgTemp->ColCount))-5;
        for(int x=0; x<XItem; x++)
            sgTemp->Cells[x+1][0]=IntToStr(x+1);
        for(int y=0;y<YItem;y++)
            sgTemp->Cells[0][y+1]=IntToStr(y+1);
    }

    for(int x=0; x<MOT[iMMAuto[iWhichUnloader]].Tray.XItem; x++)
    {
        for(int y=0; y<MOT[iMMAuto[iWhichUnloader]].Tray.YItem; y++)
        {
            if(MOT[iMMAuto[iWhichUnloader]].Tray.Data[x][y]!=NULL_IC)
            {
                if(rgUnloaderInfo->ItemIndex==1)                                //Which Arm
                {
                    iArm=MOT[iMMAuto[iWhichUnloader]].Tray.iWhichIndex[x][y];
                    if(iArm>=0)
                    {
                        sgTemp->Cells[x+1][y+1]=iArm+1;
                    }
                }
                else if(rgUnloaderInfo->ItemIndex==2)                           //Which Site
                {
                    iSite=MOT[iMMAuto[iWhichUnloader]].Tray.iWhichSite[x][y];
                    if(iSite>=0)
                    {
                        Str.sprintf("%s(%d)", aSiteName[iSite], iSite+1);
                        sgTemp->Cells[x+1][y+1]=Str;
                    }
                }
                else                                                            //Bin information
                {
                    if(MOT[iMMAuto[iWhichUnloader]].Tray.iBinCode[x][y]>=0)
                        sgTemp->Cells[x+1][y+1]=MOT[iMMAuto[iWhichUnloader]].Tray.iBinCode[x][y]-TEST_PASS;
                }
            }
            else
            {
                sgTemp->Cells[x+1][y+1]="";
            }
        }
    }
    flag=false;
}
//------------------------------------------------------------------------------
void __fastcall TfMain::ProcessICHotTime(bool bForceAcess)                      //JerryYang 20160909 add bForceAcess
{
    TStringGrid *sgTemp[]={StringGrid4, StringGrid5};
    static int OldMin=-1, OldSec=-1, P, n, XItem[2], YItem[2];
    static bool flag=true;
    int plate, iJam;
    if(SystemInitialOK==false)
        return;

    if(OldMin==-1)
    {
        TDateTime dtPresent = Now();
        DecodeTime(dtPresent, SystemHour, SystemMin, SystemSec, SystemMSec);
        OldMin=SystemMin;
        OldSec=SystemSec;
        return;
    }

    if(OldMin==SystemMin && OldSec==SystemSec && bForceAcess==false)            //JerryYang 20160909 存state record要做完,避免Hot plate缺資料
        return;

    if(fHeaterOK==true)
        StringGrid5->Cells[0][0]=1;
    else
        StringGrid5->Cells[0][0]=0;

    P=OldMin*60+OldSec;                                                         // last time
    n=SystemMin*60+SystemSec;
    if(n<P)
        n+=3600;
    P=n-P;
    if(P>3)
        P=1;                                                                    // maybe user change system time

    OldMin=SystemMin;
    OldSec=SystemSec;
    for(int i=0; i<2; i++)
    {
        if(flag || XItem[i]!=MOT[MMPlate1+i].Tray.XItem || YItem[i]!=MOT[MMPlate1+i].Tray.YItem)
        {
            XItem[i]=MOT[MMPlate1+i].Tray.XItem;
            YItem[i]=MOT[MMPlate1+i].Tray.YItem;

            if(rgHotplateShowMessage->ItemIndex!=6)
            {
                sgTemp[i]->ColCount=XItem[i]+1;
                sgTemp[i]->RowCount=YItem[i]+1;
                if(ChangeToFloatNonPcnt((double)((sgTemp[i]->Width-10)), (double)(sgTemp[i]->ColCount))>0)
                    sgTemp[i]->DefaultColWidth=ChangeToFloatNonPcnt((double)((sgTemp[i]->Width-10)), (double)(sgTemp[i]->ColCount));
                for(int x=0; x<XItem[i]; x++)
                    sgTemp[i]->Cells[x+1][0]=IntToStr(x+1);
                for(int y=0; y<YItem[i]; y++)
                    sgTemp[i]->Cells[0][y+1]=IntToStr(y+1);
            }
        }
    }

    if(LastSet.iTemperature==Tempture_Hot || LastSet.iTemperature==Tempture_AmbientHot)                                 //kevin 20180811 (Steven) : add 恆溫控制
    {
        if(iHeaterWait!=0 && fHeaterOK)
        {
            if(iHeaterWait>=P)
            {
                iHeaterWait-=P;
                if(iHeaterWait<0)                                               //jou 2016-10-03 避免iHeaterWait出現負值
                    iHeaterWait=0;
            }
            else
            {
                iHeaterWait=0;
            }
        }
    }
    else
    {
        if(fHeaterOK==false && iHeaterCooling!=0)
        {
            if(iHeaterCooling>=P)
            {
                iHeaterCooling-=P;
                if(iHeaterCooling<0)                                            //jou 2016-10-03 避免iHeaterCooling出現負值
                    iHeaterCooling=0;
            }
            else
            {
                iHeaterCooling=0;
            }

            if(iHeaterCooling==0)
                fHeaterOK=false;
        }
    }

    if(fHeaterOK==false || (fHeaterOK && iHeaterWait!=0))
        P=0;

    for(plate=0; plate<2; plate++)
    {
        for(int x=0; x<MOT[MMPlate1+plate].Tray.XItem; x++)
        {
            for(int y=0; y<MOT[MMPlate1+plate].Tray.YItem; y++)
            {
                if(P==0)
                {
                    if(fHeaterOK==false && fHeaterOK_Backup==true &&            //jou 2010-10-11
                       MOT[MMPlate1+plate].Tray.Data[x][y]!=NULL_IC)
                    {
                        if(Prod.iHotTime>Temperature.fJamSoakTime)
                        {
                            iJam=Prod.iHotTime-Temperature.fJamSoakTime;
                            HotTime[plate][x][y]=iJam;
                        }
                        else
                        {
                            HotTime[plate][x][y]=0;
                        }
                    }
                    else
                    {
                        HotTime[plate][x][y]=0;
                    }
                }
                else
                {
                    if(IniConfig.bHighModeCanOffTemp==true &&
                       Temperature.iMachineTempMode==0 &&
                       LastSet.iTemperature==Tempture_Ambient)                  //Steven 20110524
                    {
                    }
                    else
                    {
                        HotTime[plate][x][y]+=P;
                    }
                }

                if(MOT[MMPlate1+plate].Tray.Data[x][y]==HAS_IC ||
                   MOT[MMPlate1+plate].Tray.Data[x][y]==HAS_HOT_IC)
                {
                    if(HotTime[plate][x][y]>=Prod.iHotTime)
                        MOT[MMPlate1+plate].SetTraySingleData(x, y, HAS_HOT_IC);
                    else
                        MOT[MMPlate1+plate].SetTraySingleData(x, y, HAS_IC);
                }
                else if(MOT[MMPlate1+plate].Tray.Data[x][y]==HAS_TRY_SUCK_IC)   //ChungHung 20120206 Hotplate check
                {
//                    MOT[MMPlate1+plate].SetTraySingleData(x, y, HAS_TRY_SUCK_IC);
                }
                else if(MOT[MMPlate1+plate].Tray.Data[x][y]==HAS_NULL_IC)
                {
                    MOT[MMPlate1+plate].SetTraySingleData(x, y, HAS_NULL_IC);
                }
                else if(MOT[MMPlate1+plate].Tray.Data[x][y]==HAS_CLEAN_IC)      //kevin 20120217
                {
                    MOT[MMPlate1+plate].SetTraySingleData(x, y, HAS_CLEAN_IC);
                }
                else if(MOT[MMPlate1+plate].Tray.Data[x][y]==HAS_NULL_CLEAN_IC)                                         //kevin 20120217
                {
                    MOT[MMPlate1+plate].SetTraySingleData(x, y, HAS_NULL_CLEAN_IC);
                }
                else
                {
                    MOT[MMPlate1+plate].SetTraySingleData(x, y, NULL_IC);
                    HotTime[plate][x][y]=0;
                }

//                if(rgHotplateShowMessage->ItemIndex!=6 &&
//                   rgHotplateShowMessage->ItemIndex!=1 &&
//                   rgHotplateShowMessage->ItemIndex!=2)
                {
                    if(MOT[MMPlate1+plate].Tray.Data[x][y]!=NULL_IC)
                    {
                        switch(rgHotplateShowMessage->ItemIndex)
                        {
                            case 0:
                                sgTemp[plate]->Cells[x+1][y+1]=IntToStr(HotTime[plate][x][y]);
                                break;
                            case 1:
                                sgTemp[plate]->Cells[x+1][y+1]=IntToStr(iHotWhichShuttle[plate][x][y]);
                                break;
                            case 2:
                                sgTemp[plate]->Cells[x+1][y+1]=IntToStr(iHotWhichKit[plate][x][y]);
                                break;
                            case 3:
                                sgTemp[plate]->Cells[x+1][y+1]=IntToStr(iHotPlateCount[plate][x][y]);
                                break;
                            case 4:                                             //JerryYang 20180718 (wei) : 放料至hot plate記錄吸嘴位置
                                sgTemp[plate]->Cells[x+1][y+1]=IntToStr(iRowOnHotPlate[plate][x][y]);
                                break;
                            case 5:                                             //Steven 20220528 : 顯示加熱盤上IC要放的Site
                                sgTemp[plate]->Cells[x+1][y+1]=IntToStr(MOT[MMPlate1+plate].Tray.iWhichSite[x][y]);
                                break;
                        }
                    }
                    else
                    {
                        sgTemp[plate]->Cells[x+1][y+1]="";
                    }
                }
            }
        }
    }

    flag=true;

    //jou 2011-03-24 start : Auto Site Mapping
    if(IniConfig.bUseAutoSiteMapping)
    {
        if(LastSet.iTemperature==Tempture_Hot && LastSet.iRunStartMode==rsmAutoSiteMap && bSiteMappingCHKOK==false)
        {
            if(IniConfig.bI21AutoSiteMappingUseHotplate==false)                 //Ifor 20171012 Auto Site Mapping 不使用 HOT PLATE才需在蝦頭上等待時間
            {
                if(FLCarryKit.UseSiteHasIC())
                {
                    if(P==0)
                        FLCarryKit.HotCount=0;
                    else
                        FLCarryKit.HotCount+=P;
                }
                else
                {
                    FLCarryKit.HotCount=0;
                }

                if(BLCarryKit.UseSiteHasIC())
                {
                    if(P==0)
                        BLCarryKit.HotCount=0;
                    else
                        BLCarryKit.HotCount+=P;
                }
                else
                {
                    BLCarryKit.HotCount=0;
                }

                if(FLCarryKit.HotCount>0 || BLCarryKit.HotCount>0)
                {
                    if(FLCarryKit.HotCount<BLCarryKit.HotCount)
                        iShuttleHeaterWaitTime=Prod.iHotTime-BLCarryKit.HotCount;
                    else
                        iShuttleHeaterWaitTime=Prod.iHotTime-FLCarryKit.HotCount;
                }
                else
                {
                    iShuttleHeaterWaitTime=0;
                }
            }
        }
    }
    //jou 2011-03-24 end
}
//------------------------------------------------------------------------------
void __fastcall TfMain::UpdateRecordScreen(bool Attr)                           //Steven 20110827 : 重新整理
{
    static Word OldRecordMin=9999;

    int P=HSys.SysTimer.LatchCycleTime();                                       //Steven 20190714 : 計算系統時間 (MS)
    HSys.SysTimer.LatchCycleTime(true);

    //程式打開-------
    if(P>0)
    {
        for(int i=0; i<4; i++)
        {
            if(LastSet.SystemAccSecond[i][stPowerOn]<0)                         //Sam 20241218 : 增加保護避免修正PowerOn負值問題
            {
                NewRecordProcess("", "Reset PowerOn time", IntToStr(i));
                LastSet.SystemAccSecond[i][stPowerOn]=0;
            }
            LastSet.SystemAccSecond[i][stPowerOn]+=P;                           //Acc Power On
        }
    }

    //機器有在跑------
    if(SystemStart==true)
    {
        for(int i=0; i<4; i++)
        {
            LastSet.SystemAccSecond[i][stStartTime]+=P;                         //機器在動的時間
        }

        if(fAllMotorHome==false)
        {
            for(int i=0; i<4; i++)
                LastSet.SystemAccSecond[i][stHomeTime]+=P;                      //歸零時間
        }
        else if(fContact->fShow==true)
        {
            for(int i=0; i<4; i++)
                LastSet.SystemAccSecond[i][stContactTest]+=P;                   //contact test or auto height Time
        }
        else
        {
            for(int i=0; i<4; i++)
                LastSet.SystemAccSecond[i][stProductTime]+=P;                   //Acc Wrok Time

            if(CosFunction.bAutoCleanTimeCT==true &&                            //jou 20250102 : auto clean triger time count
               TestIF_File.bEnabledAutoCleanTimeCT==true)
                lAutoClean_TimeCount+=P;
            else
                lAutoClean_TimeCount=0;
        }

        fMesSystem->SetOEEState(stStartTime);
    }

    //機器沒在跑------
    if(SystemStart==false && fNote->fShow==false && SystemNG==false)
    {
        if(HasICUnderMachine() || HasAnyICInMachine())                          //JerryYang 20180423 (Steven) 機台內有IC才算進PAUSE TIME
        {
            for(int i=0; i<4; i++)
                LastSet.SystemAccSecond[i][stPauseTime]+=P;                     //Pause Time
            iPauseTime+=P;                                                      //JerryYang 20250120 : add
        }

        fMesSystem->SetOEEState(stPauseTime);
    }

    if(fNote->fShow)
    {
        for(int i=0; i<4; i++)
            LastSet.SystemAccSecond[i][stJamTime]+=P;                           //Jam Time
        iPauseTime+=P;                                                          //JerryYang 20250120 : add
        if(fNote->edErrorCode->Text.Pos("JAM")>0)
            fMesSystem->SetOEEState(stJamTime);
        else
            fMesSystem->SetOEEState(stPauseTime);
    }

    if(SystemNG)
    {
        for(int i=0; i<4; i++)
            LastSet.SystemAccSecond[i][stSystemNGTime]+=P;                      //SystemNG Time
        iPauseTime+=P;                                                          //JerryYang 20250120 : add
    }

    if(SystemStart && fAllMotorHome==true &&                                    //Steven 20181224 : For ASE-CL
       fNote->fShow==false && fSetup->fShow==false &&
       fLotInfo->bEventLogAlarm==true)
    {
        fLotInfo->SaveBackEventLogInfo(aBackEventLogMessage);
        fLotInfo->bEventLogAlarm=false;
    }

    if(OldRecordMin==9999)
    {
        OldRecordMin=SystemMin;
    }

    if(abs(OldRecordMin-SystemMin)>0)
    {
        OldRecordMin=SystemMin;
        fLotInfo->SaveASECLTestLogInfo();
    }
}
