//------------------------------------------------------------------------------
void __fastcall TfMain::UpdateMotorScreen(bool bRefrash)
{
    static bool flag=true;
    static int  Pos[TOTAL_MOTOR], Target[TOTAL_MOTOR], Speed[TOTAL_MOTOR];
    static bool fCanMove[TOTAL_MOTOR], fCanMoveL[TOTAL_MOTOR], fCanMoveM[TOTAL_MOTOR], fCanMoveR[TOTAL_MOTOR];

    int iMot;
    int iCount=0;
    bool bVisible;
    int iPos, iEncoderPos;
    static bool bInit=true;
    if(SystemInitialOK==false)
        return;

    if(bRefrash==false)                                                         //Steven 20210902 : 修正抓State Record時,要先更新馬達狀態
    {
        if(pgMain->ActivePageIndex!=emp7TabSheet21 ||
           pgMotionView->ActivePageIndex==emp1TabSheet12 ||
           pgMotionView->ActivePageIndex==emp1TabSheet15)
            return;
    }

    if(flag)
    {
        iCount=1;
        for(unsigned int i=0; i<fMotorTest->MotorTestClass.size(); i++)         //Steven 20230715 : Main Form LED燈號改與MotorTest顯示同步
        {
            iMot=fMotorTest->MotorTestClass[i]->index;
            bVisible=fMotorTest->MotorTestClass[i]->Visible;
            if(bVisible)
            {
                StringGrid1->Cells[0][iCount]=MOT[iMot].Alias;
                iCount++;
            }
        }

        if(LastSet.iLanguageCountry==1)
        {
            StringGrid1->Cells[1][0]="目前位置";
            StringGrid1->Cells[2][0]="目標位置";
            StringGrid1->Cells[3][0]="速度";
        }
        else
        {
            StringGrid1->Cells[1][0]="Current";
            StringGrid1->Cells[2][0]="Target";
            StringGrid1->Cells[3][0]="Speed";
            //jou 2011-11-21 end
        }
        //jou 2011-11-21 start : 增加馬達CanMove顯示
        StringGrid1->Cells[3][0]="Speed";
        StringGrid1->Cells[4][0]="Can";
        StringGrid1->Cells[5][0]="L";
        StringGrid1->Cells[6][0]="M";
        StringGrid1->Cells[7][0]="R";
        //jou 2011-11-21 end

        StringGrid1->ColWidths[0]=85;
        StringGrid1->ColWidths[4]=23;
        StringGrid1->ColWidths[5]=23;
        StringGrid1->ColWidths[6]=23;
        StringGrid1->ColWidths[7]=23;
    }

    iCount=1;
    for(unsigned int i=0; i<fMotorTest->MotorTestClass.size(); i++)             //Steven 20230715 : Main Form LED燈號改與MotorTest顯示同步
    {
        iMot=fMotorTest->MotorTestClass[i]->index;
        bVisible=fMotorTest->MotorTestClass[i]->Visible;
        if(bVisible==false)
        {
            continue;
        }
        else
        {
            if(bInit)
            {
                StringGrid1->RowCount=iCount+1;
                StringGrid1->Height  =20*(iCount+1)+2;
            }
        }

        if(INDEX_MOTION_CARD==0 && (iMot==MTestY1 || iMot==MTestZ1 ||           //Steven 20210623 : Index使用Galil
                                    iMot==MTestZ2 || iMot==MTestY2))
        {
            iEncoderPos=MOT[iMot].Gali_ReadEncoderPos();
            if(flag || Pos[iMot]!=iEncoderPos)
            {
                Pos[iMot]=iEncoderPos;
                StringGrid1->Cells[1][iCount]=Pos[iMot];
            }
        }
        else
        {
            if(iMot==MInArmXScale  || iMot==MInArmYScale ||                     //Steven 20160426 : 磁性尺
               iMot==MOutArmXScale || iMot==MOutArmYScale)
                iPos=MOT[iMot].ReadEncoderPos();
            else
                iPos=MOT[iMot].ReadPos();
            if(flag || Pos[iMot]!=iPos)
            {
                Pos[iMot]=iPos;
                StringGrid1->Cells[1][iCount]=Pos[iMot];
            }
        }

        if(flag || Target[iMot]!=MOT[iMot].TargetPosition)
        {
            Target[iMot]=MOT[iMot].TargetPosition;
            StringGrid1->Cells[2][iCount]=Target[iMot];
        }

        if(flag)
        {
            if(INDEX_MOTION_CARD==0 && (iMot==MTestY1 || iMot==MTestZ1 ||       //Steven 20210623 : Index使用Galil
                                        iMot==MTestZ2 || iMot==MTestY2))
            {
                if(Speed[iMot]!=MOT[iMot].GailSpeed)                            //Steven 20170104 (Jou) : 修正Galil速度顯示
                    Speed[iMot]=MOT[iMot].GailSpeed;
                StringGrid1->Cells[3][iCount]=Speed[iMot];
            }
            else if(Speed[iMot]!=MOT[iMot].GetSpeed())
            {
                if(iMot==MInArmXScale  || iMot==MInArmYScale ||                 //Steven 20160426 : 磁性尺
                   iMot==MOutArmXScale || iMot==MOutArmYScale)
                    Speed[iMot]=0;
                else
                    Speed[iMot]=MOT[iMot].GetSpeed();
                StringGrid1->Cells[3][iCount]=Speed[iMot];
            }
        }

        if(fCanMove[iMot]!=MOT[iMot].fCanMove)
        {
            fCanMove[iMot]=MOT[iMot].fCanMove;
            StringGrid1->Cells[4][iCount]=(MOT[iMot].fCanMove)?1:0;             //jou 2011-11-21 start : 增加馬達CanMove顯示
        }

        if(fCanMoveL[iMot]!=MOT[iMot].fCanMoveL)
        {
            fCanMoveL[iMot]=MOT[iMot].fCanMoveL;
            StringGrid1->Cells[5][iCount]=(MOT[iMot].fCanMoveL)?1:0;
        }

        if(fCanMoveM[iMot]!=MOT[iMot].fCanMoveM)
        {
            fCanMoveM[iMot]=MOT[iMot].fCanMoveM;
            StringGrid1->Cells[6][iCount]=(MOT[iMot].fCanMoveM)?1:0;
        }

        if(fCanMoveR[iMot]!=MOT[iMot].fCanMoveR)
        {
            fCanMoveR[iMot]=MOT[iMot].fCanMoveR;
            StringGrid1->Cells[7][iCount]=(MOT[iMot].fCanMoveR)?1:0;
        }

        if(bVisible)
            iCount++;
    }
    bInit=false;

    flag=false;
    static int ct=0;
    if(ct++<10)
        return;
    ct=0;

    for(unsigned int i=0; i<fMotorTest->MotorTestClass.size(); i++)             //Steven 20230715 : Main Form LED燈號改與MotorTest顯示同步
    {
        iMot=fMotorTest->MotorTestClass[i]->index;
        bVisible=fMotorTest->MotorTestClass[i]->Visible;                        //Steven 20240822 : 沒用到的馬達不new
        if(bVisible==false)
            continue;

        MOT[iMot].ScanMotorStatus();                                            //kevin 20110330

        for(int j=0; j<10; j++)
        {
            if(fMotorTest->MotorTestClass[i]->MotorLed[j]!=NULL)
                fMotorTest->MotorTestClass[i]->MotorLed[j]->Value=MOT[iMot].Led[j];
        }
    }
}
