void __fastcall TfMain::ChangeArmSiteView(bool bIintial)                        //Arm1 copy to Arm2
{
    if(IsNNMode()==NN_1Row)
    {
    }
    else
    {
        if(IniConfig.bA09_ByArmCloseSite==false)                                //Steven 20170203 (wei) : Fixed ChangeArmSiteView
        {
            if(TestIF_File.iShuttleMode==0)
            {
                for(int i=0; i<4; i++)
                {
                    for(int j=0; j<8; j++)
                    {
                        LastSet.bUseTestSocketEE[1][i][j]   =LastSet.bUseTestSocketEE[0][i][j];                         //Alick 20160923 add for 第三組工程師用開關SITE
                        bTestSiteUseEE[1][i][j]             =bTestSiteUseEE[0][i][j];
                        LastSet.bUseTestSocket[1][i][j]     =LastSet.bUseTestSocket[0][i][j];
                        bTestSiteUse[1][i][j]               =bTestSiteUse[0][i][j];
                    }
                }
            }
            else
            {
                int iArm=1-TestIF_File.iShuttle_Sel;                            //Steven 20250822 : A09沒開搭配關arm的時候會亂叫
                for(int i=0; i<4; i++)
                {
                    for(int j=0; j<8; j++)
                    {
                        LastSet.bUseTestSocketEE[iArm][i][j]=false;
                        bTestSiteUseEE[iArm][i][j]          =false;
                        LastSet.bUseTestSocket[iArm][i][j]  =false;
                        bTestSiteUse[iArm][i][j]            =false;
                    }
                }
            }
        }
    }
}
