                                bUse[4]             =LastSet.bUseTestSocket[0][0][2];
                                bUse[5]             =LastSet.bUseTestSocket[0][1][2];
                                bUse[6]             =LastSet.bUseTestSocket[0][0][3];
                                bUse[7]             =LastSet.bUseTestSocket[0][1][3];

                                bUse[8]             =LastSet.bUseTestSocket[0][0][4];
