//------------------------------------------------------------------------------
void __fastcall TfMain::ProcessSensorScan()
{                                                                               //ChungHung 20141002 add for KYEC AutoRetest
    signed long iFailYield=0, iFail=0, sum=0, iPass=0, Sum_ART=0, iFail_ART=0, iPassYield=0;
    double fTest=0.0, fTest1=0.0, fTest2=0.0, fPassYield=0.0, fOpenShortYield=0.0, fRecoverPassYield=0.0;               //kevin 20150709
    AnsiString str="0.00", Str1="", Str2="", Str3="";                           //kevin 20150709
    AnsiString FTStr="", RTStr="" ;
    #ifndef SOFT_SIMULTE
    static int iloadHasTray=0;                                                  //kevin 20210623
    #endif

    if(LastSet.iRunStartMode==rsmInitial_ART       ||                           //ChungHung 20141002 add for KYEC AutoRetest
       LastSet.iRunStartMode==rsmContinuStart_ART  ||
       LastSet.iRunStartMode==rsmContinuRetest_ART/* ||
        LastSet.iRunStartMode==rsmAutoRetest    )   &&
        LastSet.bLoaderTrayCount_ART            */    )                         //Steven 20251216 : mark for ART
    {
        for(int i=0; i<eTrayCount; i++)
        {
            if(Prod.iTrayType[i]==tNotUse)
                continue;

            sum     +=LastSet.BinCT    [0][iTo3Unload[i]];
            Sum_ART +=LastSet.BinCT_ART[0][iTo3Unload[i]];                      //kevin 20150709
            if(Prod.iIsFailT6[i]==1)                                            //Steven 20240105 : Prod.bIsPass --> Prod.iIsFailT6
            {
                iFail       +=LastSet.BinCT    [0][iTo3Unload[i]];
                iFail_ART   +=LastSet.BinCT_ART[0][iTo3Unload[i]];              //wei 20150923 add ART計數
            }
            else
            {
                iPass+=LastSet.BinCT[0][iTo3Unload[i]];                         //kevin 20150613
            }
        }

        if(CUSTOMER_CODE==CC_ASE_KaohSiung)                                     //kevin 20150706 ART  bin 設定
        {
            Str1="ART Pass % limit : ";
            Str2="ART O/S % limit  : ";
            Str3="ART Recover Pass % limit: ";
            for(int i=0; i<iTestBinCount; i++)
            {
                if(TestIF_File.bEnablePassYieldART && (TestIF_File.bPass[i] ||  //autoRetest 設定pass bin 和原本 PASS TRAY BIN
                                                       Prod.iIsPassT6[i]==1))   //Steven 20240105 : Prod.bIsPass --> Prod.iIsPassT6
                {
                    fTest+=LastSet.iBinData32[0][i];
                    if(TestIF_File.bPass[i])
                        Str1+=IntToStr(i)+",";
                }

                if(TestIF_File.bEnableOpenShortART && TestIF_File.bOpenShort[i])                                        //kevin 20150706
                {
                    fTest1+=LastSet.iBinData32[0][i];
                    Str2+=IntToStr(i)+",";
                }

                if(TestIF_File.bEnableRecoverART && (TestIF_File.bPass[i] ||    //kevin 20150709
                                                     Prod.iIsPassT6[i]==1))     //Steven 20240105 : Prod.bIsPass --> Prod.iIsPassT6
                {
                    fTest2+=LastSet.iBinData32_ART[0][i];
                    if(TestIF_File.bPass[i])
                        Str3+=IntToStr(i)+",";
                }
            }
        }

        if(sum>0)
        {
            iFailYield=iFail*100/sum;
            iPassYield=100-iFailYield;
            fPassYield=ChangeToFloat((double)fTest, (double)sum);               //kevin 20150706 add yield

            if(TestIF_File.bEnableOpenShortART)                                 //kevin 20150723
                fOpenShortYield=ChangeToFloat(fTest1, (double)sum);             //kevin 20150706 add yield
            else
                fOpenShortYield=0;
        }

        if(Sum_ART>0)
        {
            iFailYield=ChangeToFloat((double)iFail_ART, (double)Sum_ART);       //wei 20150923 add ART計數
            iPassYield=100-iFailYield;
            if(TestIF_File.bEnableRecoverART)
                fRecoverPassYield=ChangeToFloat((double)fTest2, (double)Sum_ART);
            else
                fRecoverPassYield=0;                                            //kevin 20150723
        }

        if(CosFunction.bUseSCKART)                                              //Steven 20161201 (wei) : For SCK 93K ART
        {
            fSCKART->UpdateCount();
        }
        else
        {
            fLotInfo->edInputAmount->Text   =LastSet.iLoaderTotalTray;
            fLotInfo->edLoadingCnt->Text    =LastSet.iLoaderTrayCount_ART;
            if(Prod.bART6Tray[eAuto1])
            {
                fLotInfo->edAuto1Cnt->Text      =LastSet.iUnloaderTrayCount_ART[eAuto1];
                fLotInfo->edAuto1Cnt_KS->Text   =LastSet.iUnloaderTrayCount_ART[eAuto1];
            }
            else
            {
                fLotInfo->edAuto1Cnt->Text      ="---";
                fLotInfo->edAuto1Cnt_KS->Text   ="---";
            }

            if(Prod.bART6Tray[eAuto2])
            {
                fLotInfo->edAuto2Cnt->Text      =LastSet.iUnloaderTrayCount_ART[eAuto2];
                fLotInfo->edAuto2Cnt_KS->Text   =LastSet.iUnloaderTrayCount_ART[eAuto2];
            }
            else
            {
                fLotInfo->edAuto2Cnt->Text      ="---";
                fLotInfo->edAuto2Cnt_KS->Text   ="---";
            }

            if(Prod.bART6Tray[eAuto3])
            {
                fLotInfo->edAuto3Cnt->Text      =LastSet.iUnloaderTrayCount_ART[eAuto3];
                fLotInfo->edAuto3Cnt_KS->Text   =LastSet.iUnloaderTrayCount_ART[eAuto3];
            }
            else
            {
                fLotInfo->edAuto3Cnt->Text      ="---";
                fLotInfo->edAuto3Cnt_KS->Text   ="---";
            }
        }

        if(CUSTOMER_CODE==CC_ASE_KaohSiung)                                     //kevin 20150601 autotest Data
        {
            fLotInfo->LART_Passlimit->Caption=Str1;
            fLotInfo->LART_Openlimit->Caption=Str2;
            fLotInfo->LART_RecoverPasslimit->Caption=Str3;                      //kevin 20150709
            fLotInfo->eART_Limit->Text = iAutoRetestLimit;
            fLotInfo->eART_Count->Text = LastSet.iAutoRetestCount_ART;
            if(TestIF_File.bEnablePassYieldART)                                 //kevin 20150723
            {
                fLotInfo->eART_Passlimit->Text = str.sprintf("%0.2f", fFirstYieldSet_ART);                              //kevin 20150701 ART
                fLotInfo->eART_PasslimitL->Caption = str.sprintf("%0.2f", fFirstYieldSet_ART);                          //kevin 20170825 (Steven) add ART
            }
            else
            {
                fLotInfo->eART_Passlimit->Text ="0.0";
                fLotInfo->eART_PasslimitL->Caption = "0.0";                     //kevin 20170825 add ART
            }

            fLotInfo->eART_PassYield->Text = str.sprintf("%0.2f", fPassYield);  //kevin 20150701 ART
            if(TestIF_File.bEnableOpenShortART)                                 //kevin 20150723
            {
                fLotInfo->eART_Openlimit->Text = str.sprintf("%0.2f", fOpenShortYieldSet_ART);                          //kevin 20150706 ART
                fLotInfo->eART_OpenlimitL->Caption = str.sprintf("%0.2f", fOpenShortYieldSet_ART);                      //kevin 20170825 (Steven) add ART
            }
            else
            {
                fLotInfo->eART_Openlimit->Text = "0.0";
                fLotInfo->eART_OpenlimitL->Caption = "0.0";                     //kevin 20170825 (Steven) add ART
            }

            fLotInfo->eART_OpenYield->Text = str.sprintf("%0.2f", fOpenShortYield);                                     //kevin 20150706 ART
            if(TestIF_File.bEnableRecoverART)                                   //kevin 20150723
            {
                fLotInfo->eART_RecoverPasslimit->Text = str.sprintf("%0.2f", fRecoverRateYieldRT1Set_ART);              //kevin 20150709 ART
                fLotInfo->eART_RecoverPasslimitL->Caption = str.sprintf("%0.2f", fRecoverRateYieldRT1Set_ART);          //kevin 20170825 (Steven) add ART
            }
            else
            {
                fLotInfo->eART_RecoverPasslimit->Text ="0.0";
                fLotInfo->eART_RecoverPasslimitL->Caption = "0.0";              //kevin 20170825 (Steven) add ART
            }
            fLotInfo->eART_RecoverPassYield->Text = str.sprintf("%0.2f", fRecoverPassYield);                            //kevin 20150709 ART
        }
        else
        {
            if(CUSTOMER_CODE==CC_KYEC_LEE)                                      //wei 20150825 KYEC 修改成By File
            {
                fLotInfo->edARTMaxLimit->Text = iAutoRetestLimitFile;
                fLotInfo->edCurrARTRate->Text = iFailYieldRate_ARTFile;
                fLotInfo->edARTPassLimit->Text = iPassYield;
                fLotInfo->edCurrARTCnt->Text = LastSet.iAutoRetestCount_ART;

                if(iUseFTFailYield==0)
                {
                    fLotInfo->Edit11->Text = dFailYieldRate_ARTFTFile[1];
                    FTStr.sprintf("FT  Pass  Yield  %s  limit: ", fYieldMonitoring->cbUseFTFailYieldModel->Text.c_str());
                    fLotInfo->Label29->Caption=FTStr;
                }
                else
                {
                    fLotInfo->Edit10->Text = dFailYieldRate_ARTFTFile[0];       //wei 20160203
                    fLotInfo->Edit12->Text = dFailYieldRate_ARTFTFile[2];
                    fLotInfo->Label29->Caption="FT  Pass  Yield  limit: ";
                }

                if(iUseRTFailYield==0)
                {
                    fLotInfo->Edit14->Text = dFailYieldRate_ARTRTFile[1];
                    RTStr.sprintf("RT  Pass  Yield  %s  limit: ", fYieldMonitoring->cbUseRTFailYieldModel->Text.c_str());
                    fLotInfo->Label45->Caption=RTStr;
                }
                else
                {
                    fLotInfo->Edit13->Text = dFailYieldRate_ARTRTFile[0];
                    fLotInfo->Edit15->Text = dFailYieldRate_ARTRTFile[2];
                    fLotInfo->Label45->Caption="RT  Pass  Yield  limit: ";
                }

                fLotInfo->Edit16->Text = iAutoLeastRetestLimitFile;
                fLotInfo->Edit10->Visible=iUseFTFailYield==1;
                fLotInfo->Edit11->Visible=iUseFTFailYield==0;
                fLotInfo->Edit12->Visible=iUseFTFailYield==1;
                fLotInfo->Edit13->Visible=iUseRTFailYield==1;
                fLotInfo->Edit14->Visible=iUseRTFailYield==0;
                fLotInfo->Edit15->Visible=iUseRTFailYield==1;
            }
            else if(CosFunction.bUseSCKART)                                     //Steven 20161201 : For SCK 93K ART
            {
                //Steven 20161126
            }
            else
            {
                fLotInfo->edARTMaxLimit->Text  = IniConfig.iAutoRetestLimit;
                fLotInfo->edCurrARTRate->Text  = IniConfig.iFailYieldRate_ART;
                fLotInfo->edARTPassLimit->Text = iFailYield;
                fLotInfo->edCurrARTCnt->Text   = LastSet.iAutoRetestCount_ART;
            }
        }
    }

    //==> Eastsun 20260512 F011 整合 (F4-T6 AMR Reflash Tray)
    #ifdef SOFT_SIMULTE
    static bool bReflashTrayCountFirst = true;
    if(TrayForm.bEnableAMR)
    {
        if(bReflashTrayCountFirst)
        {
            bReflashTrayCountFirst = false;
            LastSet.iLoaderTotalTray = 1;
            TestIF_File.iAMRLDSECSTrayCount = 1+iAMRCoverTray;
            bReflashTrayCount = true;
            SetRunStartMode(rsmContinuStart_ART);
        }
    }
    #endif

    if(TrayForm.bEnableAMR)
    {
        if((atoi(fLotInfo->labLotTrayCount_KYEC->Caption.c_str())==0 && LastSet.iLoaderTotalTray!=0) && bReflashTrayCount)
        {
            fLotInfo->labLotTrayCount_KYEC->Caption=LastSet.iLoaderTotalTray;
            fLotInfo->edInputAmount->Text   =LastSet.iLoaderTotalTray;
            fLotInfo->edLoadingCnt->Text    =LastSet.iLoaderTrayCount_ART;

            if(bReflashTrayCount)
            {
                //TestIF_File.iAMRLDSECSTrayCount=TestIF_File.iAMRLDSECSTrayCount+iAMRCoverTray; Eastsun 20260409

                fLotInfo->labNowTrayCount->Caption=TestIF_File.iAMRLDSECSTrayCount;
                fLotInfo->LabDiffTrayCount->Caption=LastSet.iLoaderTotalTray-TestIF_File.iAMRLDSECSTrayCount+iAMRCoverTray;

                if(TestIF_File.iAMRLDNowTrayCount==0)
                    TestIF_File.iAMRLDNowTrayCount=TestIF_File.iAMRLDSECSTrayCount;

                if(TrayForm.bEnableAMRLoader==false)
                {
                    for(int i=0; i<iTestBinCount; i++)      //Steven 20121112 : RS232支援32Bin 15 --> iTestBinCount
                    {
                        if(Prod.CatData[i]>=0 && Prod.CatData[i]<=2)
                        {
                            bNeedCoverTray[Prod.CatData[i]]=true;
                        }
                    }
                }
                RecordProcess("AMR ReflashTrayCount");
                bReflashTrayCount=false;
            }
        }

        if(RunInfo.bLotStart==true &&
           //bAMRReceiveLoaderTotalTray &&                                      //Eastsun 20260415 : 有收到Tray盤數資訊
           //bAMRReceiveAGVStart //&&                                           //Eastsun 20260415 : 有收到AGV Start訊號 此訊號會把 bReflashTrayCount=true 所以此段必須寫在這 讓上面更新資訊
           bAMRReceiveStart                                                     //Eastsun 20260415 : 收到機台啟動訊號
           )
        {
            if(LastSet.iLoaderTotalTray>0)
            {
                bAMRReceiveLoaderTotalTray=true;
                RecordProcess("AMR Machine iLoaderTotalTray");
            }
            else
            {
                ShowMyMessage("LoaderTotalTray(37007) is zero\n Please restart system");
            }

            if(TestIF_File.iAMRLDSECSTrayCount>0)
            {
                RecordProcess("AMR Machine iSECSSetTrayCount");
            }
            else
            {
                ShowMyMessage("AGV_START TrayCount is zero\n Please restart system");
            }
            fMain->Start("AMR");
            RecordProcess("AMR Machine Start");
            bAMRReceiveStart=false;
            fLotInfo->CheckActionFlag();
        }
    }
    //<== Eastsun 20260512 F011 整合 (F4-T6 AMR Reflash Tray)
    #ifdef SOFT_SIMULTE                                                         //ChungHung 20141002 add for KYEC AutoRetest
    if((LastSet.iRunStartMode==rsmInitial_ART       ||                          //ChungHung 20141002 add for KYEC AutoRetest
        LastSet.iRunStartMode==rsmContinuStart_ART  ||
        LastSet.iRunStartMode==rsmContinuRetest_ART ||
        LastSet.iRunStartMode==rsmAutoRetest    )   &&
        atoi(edLoadCnt->Text.c_str())<=atoi(lblLoadTrayCnt->Caption.c_str()))
    {
        ALed1->Value=false;
    }
    else if(CheckBox1->Checked==false)
    {
        ALed1->Value=false;
    }
    else if(LastSet.iRealDummy==DUMMY || CheckBox1->Checked)
    {
        ALed1->Value=true;
    }
    else
    {
        ALed1->Value=Sen[SnLoaderTrayHasTray].Status();
    }
    #else
    if(LastSet.iRealDummy==DUMMY || CheckBox1->Checked)
    {
        ALed1->Value=true;
    }
    else
    {
        if(bForKyecBu3RunART)                                                   //wei 20161118 bRunART-->bForKyecBu3RunART
            ALed1->Value=Sen[SnLoaderTrayHasTray_ART].Status();
        else
            ALed1->Value=Sen[SnLoaderTrayHasTray].Status();

        if(CUSTOMER_CODE==CC_ASE_KaohSiung && SystemStart==false && IniConfig.bG11ASEReport)                            //kevin 20210810 read tray id tput new tray
        {
            if(iloadHasTray==0 && ALed1->Value==true)                           //kevin 20210623
            {
                iloadHasTray=1;                                                 //put load
                RecordProcess("<AutoMove>LoadTray put on loader location.");
            }
            else if(iloadHasTray==1 && ALed1->Value==false)
            {
                iloadHasTray=0;                                                 //no load tray
            }
        }
    }
    #endif
}
//---------------------------------------------------------------------------
void __fastcall TfMain::UpdateMotorHomeLed()
{
    int iMot;
    bool bVisible;
    static bool flag=false;
    static int  v[TOTAL_MOTOR];

    for(unsigned int i=0; i<fMotorTest->MotorTestClass.size(); i++)             //Steven 20230715 : Main Form LED燈號改與MotorTest顯示同步
    {
        iMot=fMotorTest->MotorTestClass[i]->index;
        bVisible=fMotorTest->MotorTestClass[i]->Visible;                        //Steven 20240822 : 沒用到的馬達不new
        if(bVisible)
        {
            if(flag || v[iMot]!=MOT[iMot].HomeFlag)
            {
                v[iMot]=MOT[iMot].HomeFlag;
                if(v[iMot]==1)
                    fMotorTest->MotorTestClass[i]->MotorHomeLed->Value=true;
                else
                    fMotorTest->MotorTestClass[i]->MotorHomeLed->Value=false;
            }
        }
    }
    flag=false;
}
//---------------------------------------------------------------------------
void __fastcall TfMain::UpdateSystemMessage()
{
    static bool oldbMotorPowerState;
    static int  oldMotorPowerOnDelay=-1;
    if(oldbMotorPowerState!=bMotorPowerState ||
       oldMotorPowerOnDelay!=MotorPowerOnDelay)
    {
        oldbMotorPowerState =bMotorPowerState;
        oldMotorPowerOnDelay=MotorPowerOnDelay;
    }
}
