//--------------------------------------------------------------------------
bool __fastcall TfMain::CanChangeSite(bool bNoIncludeHotplate)
{
    if(bCanAutoCloseSite)                                                       //Steven 20200420 : 整合Auto Site Off
    {
        if(IniConfig.bI28_OnOffSiteOnTheFly==false)                             //kevin 20211103 add I28
        {
            if(InArmSuck.HasIC()     ||
               InputShuttleHasIC()   ||
               IndexHasIC())
                return false;
        }
    }
    else
    {
        if(IniConfig.bI28_OnOffSiteOnTheFly==false)                             //kevin 20211103 add I28
        {
            if(bNoIncludeHotplate)                                              //ChungHung 20120713 add OneCycle Can Enable Site
            {
                if(InArmSuck.HasIC()     ||
                   InputShuttleHasIC()   ||
                   IndexHasIC())
                    return false;
            }
            else
            {
                if(MOT[MMPlate1].HasIC() ||
                   MOT[MMPlate2].HasIC() ||
                   InArmSuck.HasIC()     ||
                   InputShuttleHasIC()   ||
                   IndexHasIC())
                    return false;
            }
        }
        else
        {
            if(bPickFromLoader==true ||
               iPickFromLoadStageTask!=1)
            {
                return false;
            }
        }
    }
    return true;
}
//------------------------------------------------------------------------------
void __fastcall TfMain::cbUserSelectChange(TObject *Sender)
{
    AnsiString S, asPassword, S2, S3, S1;
    static bool bEnter=false;
    TfPassword *PassworfForm;
    bool bCheckOK=false;                                                        //Sam 20221101 : 使用 BarCoder 自動登錄
    AnsiString sBarcodeID="";                                                   //Sam 20221101 : 使用 BarCoder 自動登錄
    int l=0;

    if(fPassword->bShow && fPassword2->bShow)
    {
        return;
    }
    else if(fPassword->bShow || fNote->fShow==true)                             //jou 20220930 : 修正note alarm password顯示錯誤
    {
        PassworfForm=fPassword2;
    }
    else
    {
        PassworfForm=fPassword;
    }

    char dest[20];
    char str[512];
    bool bError=false;
    bool bChange=false;

    bEnter=true;

    if(Barcode_Reader(bcUserName)==0)                                           // 20140103 wei KYEC Barcode Reader
    {
        AccessLevel=0;
        fMain->ChangeLevelAttr();
        bEnter=false;
        UpdateMainOperateMode();
        return;
    }

    if(IniConfig.bN15UserLevelByTxt==true &&
       CUSTOMER_CODE==CC_Greatek)                                               //Sam 20170828 (Steven) 移植超豐 ESD Control 功能 form HT-7045
    {
        S1=ESDForm->FTP_PasswordFile_Download(IniConfig.asN15UserLevelByTxtReadFilePath);                               //JimmyChiu 20220219 : FTP_ESDFile_Download==>FTP_PasswordFile_Download
        if(FileExists(S1))                                                      //Sam 20180411 (wei) : 下載檔案增加保護。
        {
            pwPath=S1;
            pwName="S1";                                                        //Steven 20221216 : 吳如春要改成從網路抓密碼本
        }
        else
        {
            pwPath="C:\\winnt\\system32\\tech.com";                             //JimmyChiu 20220901 密碼下載失敗後讀取tech.com
            pwName="tech.com";                                                  //Steven 20221216 : 吳如春要改成從網路抓密碼本
        }
    }

    //Steven 20101109 Start
    if(FileExists(pwPath))                                                      //2012-01-03    Dell modify
    {
        PassList[0]->Clear();                                                   // switch to handler directory
        PassList[1]->Clear();
        PassList[2]->Clear();
        PassList[3]->Clear();
        PassList[4]->Clear();                                                   //JerryYang 20250120 : add

        if(IniConfig.bPasswordSecret)                                           //jou 2013-01-04 Password Txt 加密
        {
            bChange=CheckAndReadIniDataGeneral("Password", "Change", false);
        }

        if(CosFunction.bUseLoginDatToSetLevel)                                  //Steven 20170301 (wei) : 使用Login.dat當密碼本
        {
            FILE *Fp = fopen(pwPath.c_str(), "rb");
            PassworfForm->cbUserName->Clear();
            if(FileExists(pwPath)==true && Fp!=NULL)                            //Steven 20200507 : 修正密碼本讀檔
            {
                fread((char *)&USER.RecordCT, sizeof(PASS_WORD), 1, Fp);
                fclose(Fp);
            }
            else
            {
                if(Fp!=NULL)
                {
                    fclose(Fp);
                }
                memset(&USER.RecordCT, 0, sizeof(PASS_WORD));
                ShowErrorMessage("WAR1681", 0, MMSystem, 0, "login.dat");
                return;
            }

            for(int i=0; i<1000; i++)                                           //Steven 20200507 : 修正密碼本讀檔 1000 --> USER.RecordCT
            {
                try
                {
                    S2=AnsiString(USER.ID[i]);                                  //jou 2016-08-31 修正USER.ID NULL時會造成異常
                    S3=DecodeStr(S2);
                    if(S3!="")                                                  //Alick 20160728 排除空白ID
                    {
                        PassList[0]->Add(S3);
                        PassworfForm->cbUserName->Items->Add(S3);
                        S2.sprintf("%d", USER.Level[i]);
                        PassList[1]->Add(AnsiString(S2));
                        S2=AnsiString(USER.PassWord[i]);                        //Steven 20200508 : 修正USER.PassWord NULL時會造成異常
                        S3=DecodeStr(S2);
                        PassList[2]->Add(S3);
                    }
                }
                catch(...)
                {
                    memset(&USER.RecordCT, 0, sizeof(PASS_WORD));
                    ShowErrorMessage("WAR1681", 0, MMSystem, 0, "login.dat");
                    return;
                }
            }
        }
        else if(IniConfig.bN15UserLevelByTxt==true && CUSTOMER_CODE==CC_Greatek)
        {
            try                                                                 //20160425 Mylin Modify Load File On Net Add Try Catch
            {
                try
                {
                    PassList[3]->LoadFromFile(pwPath.c_str());                  //20160505 Mylin Use FTP To do User Level By txt And ESD Control Machine
                }
                catch(...)
                {
                    MyDBIProcess("Exception", "TfMain::cbUserSelectChange");
                }

                PassList[0]->Clear();                                           //20160826 Mylin Debug Code Integrate Problem PassList[3]->LoadFromFile(IniConfig.aUserLevelByTxtReadFilePath.c_str());          //pig 2016.04.13
                PassList[1]->Clear();
                PassList[2]->Clear();
                for(int i=0; i<PassList[3]->Count; i++)
                {
                    strncpy(str, PassList[3]->Strings[i].c_str(), sizeof(str));                                         //Jimmychiu 20231101 : avoid password too long to overflow,建議使用strncpy取代strcpy

                    SplitStrByDotSpaceOnly(str, dest, 20);                      //ID
                    PassList[0]->Add(dest);

                    SplitStrByDotSpaceOnly(str, dest, 20);                      //Password
                    PassList[1]->Add(dest);

                    SplitStrByDotSpaceOnly(str, dest, 20);                      //level
                    PassList[2]->Add(dest);
                }

                if(PassList[0]->Count!=0)
                {
                    fPassword->edUserName->Text="";                             // name
                    fPassword->edPassword->Text="";                             // password
                    fPassword->ShowModal();
                    for(int i=0; i<PassList[0]->Count; i++)
                    {
                        if(fPassword->edUserName->Text.UpperCase()==PassList[0]->Strings[i].UpperCase() &&
                           fPassword->edPassword->Text.UpperCase()==PassList[1]->Strings[i].UpperCase())
                        {
                            int l=atoi(PassList[2]->Strings[i].c_str());
                            if(l>=0 && l<=3)
                            {
                                AccessLevel=l;
                                cbUserSelect->ItemIndex=l;
                                UseName=PassList[0]->Strings[i];
                                fMain->ChangeLevelAttr();
                                bEnter=false;
                                if(l==3)
                                {
                                    cbUserSelect->Text="HonPrec";
                                    spbUserName->Caption="HonPrec";
                                }
                                else if(l==2)
                                {
                                    cbUserSelect->Text="Supervisor";
                                    spbUserName->Caption="Supervisor";
                                }
                                else if(l==1)
                                {
                                    cbUserSelect->Text="Engineer";
                                    spbUserName->Caption="Engineer";
                                }
                                S=AnsiString("======== ")+UseName+AnsiString(" login ========");
                                RecordProcess(S.c_str());
                                return;
                            }
                        }
                    }
                    cbUserSelect->ItemIndex=0;
                    AccessLevel=0;
                    fMain->ChangeLevelAttr();
                    bEnter=false;
                    RecordProcess("Operator login");
                    return;
                }
            }
            catch(...)                                                          //20160425 Mylin Modify Load File On Net Add Try Catch {
            {
                MyDBIProcess("Exception", "TfMain::cbUserSelectChange");
                PassList[3]->Clear();
                AccessLevel=0;
                fMain->ChangeLevelAttr();
                bEnter=false;
                return;
            }
        }
        else if(CosFunction.bLoginASECL)                                        //JerryYang 20250120 : add
        {
            PassList[4]->LoadFromFile(pwPath);                                  //2012-01-03    Dell modify

            for(int i=0; i<PassList[4]->Count; i++)
            {
                strncpy(str, PassList[4]->Strings[i].c_str(), sizeof(str));

                SplitStrByDotSpaceOnly(str, dest, 20);
                PassList[0]->Add(dest);

                SplitStrByDotSpaceOnly(str, dest, 20);
                PassList[1]->Add(dest);

                SplitStrByDotSpaceOnly(str, dest, 20);
                PassList[2]->Add(dest);

                SplitStrByDotSpaceOnly(str, dest, 20);
                PassList[3]->Add(dest);
            }
        }
        else
        {
            PassList[3]->LoadFromFile(pwPath);                                  //2012-01-03    Dell modify
            PassworfForm->cbUserName->Clear();                                  //Steven 20140530 : 使用密碼本時,用下拉選單選使用者
            for(int i=0; i<PassList[3]->Count; i++)
            {
                strncpy(str, PassList[3]->Strings[i].c_str(), sizeof(str));

                SplitStrByDotSpaceOnly(str, dest, 20);
                PassList[0]->Add(dest);
                PassworfForm->cbUserName->Items->Add(dest);                     //Steven 20140530 : 使用密碼本時,用下拉選單選使用者

                SplitStrByDotSpaceOnly(str, dest, 20);
                PassList[1]->Add(dest);

                SplitStrByDotSpaceOnly(str, dest, 20);
                asPassword=dest;
                if(IniConfig.bPasswordSecret && bChange==true)                  //jou 2013-01-04 Password Txt 加密
                {
                    asPassword=DecodeStr(asPassword);
                }
                PassList[2]->Add(asPassword);

                if(IniConfig.bEnable_SECS_GEM==true &&
                   PassList[0]->Strings[i].UpperCase()=="HONPREC")              //wei 20150817 SECSGEM 斷線 Onecycle
                    asSECSGEMPassWord=PassList[2]->Strings[i].UpperCase();
            }
        }

        if(PassList[0]->Count!=0)
        {
            PassworfForm->edUserName->Text="";                                  // name
            if(USE_BARCODE_AS_KEYBOARD!=0)
            {
                PassworfForm->edUserName->Text=fLotInfo->edtSysOperatorID->Text;
            }

            if(CosFunction.bUseBarCoderAutoLogin)                               //Sam 20221101 : 使用 BarCoder 自動登錄
            {
                bBarCoderAutoLogin=true;
                sBarcodeID=InputBarcodeNumber("Input User Name:", "UserName");
                bBarCoderAutoLogin=false;
            }
            else
            {
                PassworfForm->edPassword->Text="";                              // password
                PassworfForm->ShowModal();
            }

            for(int i=0; i<PassList[0]->Count; i++)
            {
                if(CosFunction.bLoginASECL)                                     //JerryYang 20250120 : add
                {                                                               //RogerYang 20260625 : 芯云也只使用密碼登入
                    int iPwCol  =0;                                             //ASE-CL格式=Password/Level/Name,密碼在第1欄
                    int iNameCol=2;                                             //username在第3欄
                    if(CUSTOMER_CODE==CC_XINYUN)
                    {                                                           //芯云用原本格式=Name/Level/Password
                        iPwCol  =2;                                             //密碼在第3欄
                        iNameCol=0;                                             //username在第1欄
                    }

                    if(PassworfForm->edPassword->Text.UpperCase()==PassList[iPwCol]->Strings[i].UpperCase() &&      //RogerYang 20260625 : iPwCol/iNameCol map cols (XINYUN=2/0,ASE-CL=0/2)
                        PassList[iNameCol]->Strings[i]!="")
                    {
                        l=atoi(PassList[1]->Strings[i].c_str());
                        if(l>=0 && l<=3)
                        {
                            AccessLevel=l;
                            cbUserSelect->ItemIndex=l;
                            //UseName=PassList[2]->Strings[i];
                            UseName=PassList[iNameCol]->Strings[i];             //RogerYang 20260625 : reverse-looked-up username
                            fMain->ChangeLevelAttr();
                            bEnter=false;
                            if(l==3)
                            {
                                cbUserSelect->Text="HonTech";
                                spbUserName->Caption="Hontech";
                            }
                            else
                            {
                                spbUserName->Caption=cbUserSelect->Items->Strings[l];
                            }
                            asUser=UseName;
                            S=UseName+AnsiString("===")+spbUserName->Caption;
                            NewRecordProcess("MES2144", "======== USER login ========", S);
                            if(IniConfig.bShowLotInfo)                          //Steven 20110113
                            {
                                if(AccessLevel<iDefHonPrecLevel)                //jou 2014-06-19 Security Have 5 Level 3->iDefHontechLevel
                                {
                                    fMain->EnabledSetupFile(false);
                                }
                                else
                                {
                                    if(CUSTOMER_CODE==CC_SCC ||
                                       (CosFunction.bHiSiliconFunction==true &&
                                        CUSTOMER_CODE==CC_JCET))                //jou 20170921 (Steven) : center要求海思版hontech權限也不能選擇工作檔
                                        fMain->EnabledSetupFile(false);
                                    else
                                        fMain->EnabledSetupFile(true);
                                }
                            }
                            else if(CUSTOMER_CODE==CC_KYEC_LEE ||
                                    CUSTOMER_CODE==CC_KYEC_XILINX)              //landam 20110324
                            {
                                if(AccessLevel>=5)
                                    fMain->EnabledSetupFile(true);
                                else
                                    fMain->EnabledSetupFile(false);
                            }
                            else
                            {
                                fMain->EnabledSetupFile(true);
                            }
                            return;
                        }
                    }
                }
                else
                {
                    if(CosFunction.bUseBarCoderAutoLogin)                       //Sam 20221101 : 使用 BarCoder 自動登錄
                    {
                        bCheckOK=(sBarcodeID.UpperCase()==PassList[0]->Strings[i].UpperCase());
                    }
                    else
                    {
                        bCheckOK=((PassworfForm->edUserName->Text.UpperCase()==PassList[0]->Strings[i].UpperCase() ||
                                    JCET_FOR_EVAN==1) &&                        //Steven 20221215
                                   PassworfForm->edPassword->Text.UpperCase()==PassList[2]->Strings[i].UpperCase());
                    }

                    if(bCheckOK)
                    {
                        int l=atoi(PassList[1]->Strings[i].c_str());
                        if(l>=0 && l<=3)
                        {
                            AccessLevel=l;
                            cbUserSelect->ItemIndex=l;
                            UseName=PassList[0]->Strings[i];
                            fMain->ChangeLevelAttr();
                            bEnter=false;
                            if(l==3)
                            {
                                cbUserSelect->Text="HonPrec";
                                spbUserName->Caption="HonPrec";
                            }
                            else
                            {
                                spbUserName->Caption=cbUserSelect->Items->Strings[l];
                            }

                            if(CosFunction.bLoginShowUserName)                  //Steven 20230317 : 登入時顯示帳號名稱
                            {
                                spbUserName->Caption=UseName;
                            }

                            asUser=UseName;
                            S=UseName+AnsiString("===")+spbUserName->Caption;
                            NewRecordProcess("MES2144", "======== USER login ========", S);
                            if(IniConfig.bShowLotInfo)                          //Steven 20110113
                            {
                                if(AccessLevel<iDefHonPrecLevel)                //jou 2014-06-19 Security Have 5 Level 3->iDefHonPrecLevel
                                {
                                    fMain->EnabledSetupFile(false);
                                }
                                else
                                {
                                    if(CUSTOMER_CODE==CC_SCC ||
                                       (CosFunction.bHiSiliconFunction==true &&
                                        CUSTOMER_CODE==CC_JCET))                //jou 20170921 (Steven) : center要求海思版hontech權限也不能選擇工作檔
                                        fMain->EnabledSetupFile(false);
                                    else
                                        fMain->EnabledSetupFile(true);
                                }
                            }
                            else if(CUSTOMER_CODE==CC_KYEC_LEE ||
                                    CUSTOMER_CODE==CC_KYEC_XILINX)              //landam 20110324
                            {
                                if(AccessLevel>=5)
                                    fMain->EnabledSetupFile(true);
                                else
                                    fMain->EnabledSetupFile(false);
                            }
                            else
                            {
                                fMain->EnabledSetupFile(true);
                            }
                            return;
                        }
                    }
                }
            }
            bError=true;
        }

        if(bError==true)
        {
            cbUserSelect->ItemIndex=0;
            AccessLevel=0;
            fMain->EnabledSetupFile(false);
            fMain->ChangeLevelAttr();
            bEnter=false;
            btLogin->Caption="Login";
            cbUserSelect->Text="Operator";
            spbUserName->Caption="Operator";
            ShowErrorMessage("WAR1677", 0, MMSystem, false, "Main--UserSelectChange");                                  //UserName or PassWord Error
            return;
        }
    }
    else if(spbUserName->Visible==true)                                         //假如檔案不見了，而且不是使用Combox選的
    {
        if(CosFunction.bUseLoginDatToSetLevel)                                  //Steven 20191202 : 修正Alarm內容
            ShowErrorMessage("WAR1681", 0, MMSystem, 0, "login.dat");
        else
            ShowErrorMessage("WAR1681", 0, MMSystem, 0, "Tech.com");
        return;
    }
    //Steven 20101109 End

    PassworfForm->edPassword->Text="";

    if(chk_Honprec_Use->Checked==true)                                          //Ztex 2024.04.03 Add chk_Honprec_Use
    {
        cbUserSelect->ItemIndex=3;
        AccessLevel=3;
    }

    if(CosFunction.bSecurityHave5Level==true)                                   //jou 2014-06-19 Security Have 5 Level
    {
        for(int i=0; i<4; i++)
        {
            if(cbUserSelect->ItemIndex==i && AccessLevel>=i)
            {
                AccessLevel=i;
                fMain->ChangeLevelAttr();
                bEnter=false;
                UpdateMainOperateMode();
                return;
            }
        }
    }
    else
    {
        if(cbUserSelect->ItemIndex==0)
        {
            AccessLevel=0;
            fMain->ChangeLevelAttr();
            bEnter=false;
            UpdateMainOperateMode();
            return;
        }

        if(cbUserSelect->ItemIndex==1 && AccessLevel>=1)
        {
            AccessLevel=1;
            fMain->ChangeLevelAttr();
            bEnter=false;
            UpdateMainOperateMode();
            return;
        }

        if(cbUserSelect->ItemIndex==2 && AccessLevel>=2)
        {
            AccessLevel=2;
            fMain->ChangeLevelAttr();
            bEnter=false;
            UpdateMainOperateMode();
            return;
        }
    }

    fPassword->edUserName->Text=cbUserSelect->Text;
    stOperatorClick(this);
    LevelChange=true;
    if(AccessLevel<=0)
        cbUserSelect->ItemIndex=0;
    fMain->ChangeLevelAttr();
    bEnter=false;

    if(chk_Honprec_Use->Checked==true)                                          //Ztex 2024.04.03 Add chk_Honprec_Use
    {
        cbUserSelect->ItemIndex=3;
        AccessLevel=3;
    }

    UpdateMainOperateMode();

    if(FileExists(pwPath)==false)                                               //Steven 20140815
    {
        if(AccessLevel==0)
        {
            asUser="Operator";
            NewRecordProcess("MES2140", "======== Operator login ========");
        }
        else if(AccessLevel==1)
        {
            asUser="Engineer";
            NewRecordProcess("MES2141", "======== Engineer login ========");
        }
        else if(AccessLevel==2)
        {
            asUser="Supervisor";
            NewRecordProcess("MES2142", "======== Supervisor login ========");
        }
        else if(AccessLevel==3)
        {
            asUser="HonPrec";
            NewRecordProcess("MES2143", "======== HonPrec login ========");
        }
    }

    if(IniConfig.bEnable_SECS_GEM==true)                                        //Steven 20140528 : Secs Gem
        EventReport(SECS_EVENT.SwitchUser);
}
