//---------------------------------------------------------------------------
//Steven 20190325 : 重新整合Clarn_Data功能
//---------------------------------------------------------------------------
void __fastcall TfMain::Clarn_Data(int Tag, AnsiString Msg)
{
    int iMode;

    static AnsiString LotID="";
    static AnsiString FileName="";
    AnsiString asPath, Buffer1, str;
    asPath.sprintf("%s%04d%02d\\", asQtyDataPath, SystemYear, SystemMonth);
    MyForceDirectories(asPath);

    if(IniConfig.bA61DisableCleanMUBA==true)                                    //Jeff 20240930 add continustart for not enough IC Jame rate test
        return;

    if(FileName!="")
    {
        for(int i=0; i<eTrayCount; i++)
        {
            if(Buffer1=="")
                str.sprintf("%d",   LastSet.BinCT[0][iTo3Unload[i]]);
            else
                str.sprintf(", %d", LastSet.BinCT[0][iTo3Unload[i]]);
            Buffer1=Buffer1+str;
        }

        str.sprintf("%s, %d, %d, %s",
                    Msg,
                    LastSet.SendCT[0],
                    RunInfo.iUnloadCount,
                    Buffer1);
        slQtyLog->AddTextWithDateTime(str);
        slQtyLog->MySaveFileByFileName(asPath, FileName);
    }

    if(Tag==0)
    {
        iMode=(LastSet.iRunStartMode<=rsmContinuRetest)?0:1;

        if(LastSet.bCTClear[iMode][ctLoadingCounts])                            //Loading Counts
            fCounterClear->ClearCount(ctLoadingCounts);

        if(LastSet.bCTClear[iMode][ctTesterCategory])                           //Tester Category
            fCounterClear->ClearCount(ctTesterCategory);

        if(LastSet.bCTClear[iMode][ctContactCounts])                            //Contact Counts
            fCounterClear->ClearCount(ctContactCounts);

        if(LastSet.bCTClear[iMode][ctTraySortCount])                            //Tray Sort Count
            fCounterClear->ClearCount(ctTraySortCount);

        if(LastSet.bCTClear[iMode][ctScannerCategory])                          //Scanner Category
            fCounterClear->ClearCount(ctScannerCategory);

        if(LastSet.bCTClear[iMode][ctAlarmData])                                //Alarm Data
            fCounterClear->ClearCount(ctAlarmData);

        if(LastSet.bCTClear[iMode][ctTimeData])                                 //Time Data
            fCounterClear->ClearCount(ctTimeData);

        fContactCT->sgYield->Refresh();                                         //Steven 20100402 Start: for initial start
        for(int i=0; i<32; i++)
            fYieldMonitoring->bShowSiteYield[i]=false;

        fYieldMonitoring->ClearYieldCount();                                    //Steven 20140830 : Yield相關的Alarm, 要清掉全部的Ignore的Count重算
    }
    else if(Tag==1)
    {
        fCounterClear->ClearCount(ctLoadingCounts);
        fCounterClear->ClearCount(ctTraySortCount);
        fCounterClear->ClearCount(ctTesterCategory);
        fCounterClear->ClearCount(ctIndexCount);
    }
    else if(Tag==2)
    {
        fCounterClear->ClearCount(ctLoadingCounts);
//        fCounterClear->ClearCount(ctTraySortCount);
        fCounterClear->ClearCount(ctTesterCategory);
        fCounterClear->ClearCount(ctIndexCount);
    }
    else if(Tag==3)
    {
        fCounterClear->ClearCount(ctLoadingCounts);
        fCounterClear->ClearCount(ctIndexCount);                                //kevin 20130125 記錄 index吸取ic數量 index放置shuttle 數量
        fCounterClear->ClearCount(ctContactCounts);
        fCounterClear->ClearCount(ctContactCountsHis);
        fCounterClear->ClearCount(ctTraySortCount);
    }
    else if(Tag==4)
    {
        fCounterClear->ClearCount(ctLoadingCounts);
        fCounterClear->ClearCount(ctTraySortCount);
        fCounterClear->ClearCount(ctTesterCategory);                            //jou 2011-07-26 cObserver會出現 over 100% value
        fCounterClear->ClearCount(ctIndexCount);                                //kevin 20130125 記錄 index吸取ic數量 index放置shuttle 數量

        fCounterClear->ClearCount(ctContactCounts);                             //Rogeryang 20170704 (Steven) 中科說要清掉
        fCounterClear->ClearCount(ctContactCountsHis);                          //Rogeryang 20170704 (Steven) 中科說要清掉
    }
    else if(Tag==5)
    {
        fCounterClear->ClearCount(ctAutoRetestCount);                           //wei 20150923 add ART計數
        fCounterClear->ClearCount(ctLoadingCounts);
        fCounterClear->ClearCount(ctIndexCount);
        fCounterClear->ClearCount(ctTesterCategory);
    }
    else if(Tag==6)
    {
        fCounterClear->ClearCount(ctLoadingCounts);
        fCounterClear->ClearCount(ctIndexCount);
        fCounterClear->ClearCount(ctTesterCategory);
    }
    else if(Tag==7)
    {
//        fCounterClear->ClearCount(ctLoadingCounts);
//        fCounterClear->ClearCount(ctTraySortCount);
        fCounterClear->ClearCount(ctTesterCategory);
        fCounterClear->ClearCount(ctIndexCount);
    }
    else if(Tag==8)
    {
        if(!(CUSTOMER_CODE==CC_SCS ||                                           //jou 2012-05-04 新增CC_AMKOR_Korea也不要清除Loader Count
             CUSTOMER_CODE==CC_ASE_Korea ||                                     //jou 2013-07-08 新增CC_SCS也不要清除Loader Count
             CUSTOMER_CODE==CC_AMKOR_Korea))                                    //Steven 20110725 : 韓國ASE不要清總數
        {
            fCounterClear->ClearCount(ctLoadingCounts);
        }
        fCounterClear->ClearCount(ctTraySortCount);

        if(IniConfig.bVTESTFunction==false)
        {
            fCounterClear->ClearCount(ctTesterCategory);                        //jou 2011-07-26 cObserver會出現 over 100% value
        }

        fCounterClear->ClearCount(ctIndexCount);                                //kevin 20130125 記錄 index吸取ic數量 index放置shuttle 數量
        if(CUSTOMER_CODE==CC_KYEC_LEE)                                          //wei 20151116 KYEC 連Yeild一起清除
        {
            bHasCleanCount=true;                                                //Ifor 20191016 : add KYEC清除Yield過程中不需再次登入權限
            fContactCT->btClearCountClick(this);
            bHasCleanCount=false;                                               //Ifor 20191016 : add KYEC清除Yield過程中不需再次登入權限
        }
    }
    else if(Tag==9)
    {
        fCounterClear->AutoClear();
    }
    else if(Tag==10)
    {
    }
    else if(Tag==11)                                                            //Sam 20230728 : 發生 LowYield 後重新 Start 清除 Sort Count 和 contact counterKinds)
    {
        fCounterClear->ClearCount(ctTraySortCount);
        fContactCT->btClearCountClick(this);                                    //kevin 20170814 add
    }

    for(int j=0; j<3; j++)                                                      //kevin 20210623  0:loader 1:Empty  2:olor  Tray 入軌道數量
    {
        iTrayTotal[j]=0;                                                        //kevin 20210623  0:loader 1:Empty  2:olor  Tray 入軌道數量
        for(int i=0; i<6; i++)
            TrayID[i][j]="";                                                    //kevin 20210623  [6]: load empty  [2]: 0:read  1: send pick pos
    }

    for(int i=0; i<ePosTrayCount; i++)                                          //JerryYang 20220909 : 9->eTrayCount
    {
        iAutoTrayPlaceCount[i]=0;                                               //kevin 20210623  Auto123 Fix 123 放ic數量
        iOneTrayPickCount[i]=0;
    }

    WriteLastDataFile(false);                                                   //kevin 20141030
    fSortCT->ShowLoadingIC();
    fSortCT->ShowSortIC();
    MyDBIProcess("Process", Msg);

    if(TestIF_File.bSCKART_EnableART)
    {
        if(LotID=="" || LotID!=fSCKART->palLotNumber->Caption)
        {
            LotID=fSCKART->palLotNumber->Caption;
        }
        FileName.sprintf("%s_%s.csv", PC_NAME, LotID);
    }
    else
    {
        if(LotID!="")
            FileName.sprintf("%s_%s_%04d%02d%02d.csv", PC_NAME, LotID, SystemYear, SystemMonth, SystemDate);
        else
            FileName.sprintf("%s_%04d%02d%02d.csv", PC_NAME, SystemYear, SystemMonth, SystemDate);
    }
}
//---------------------------------------------------------------------------
bool __fastcall TfMain::Check_AllMOT_Home()
{
    for(int i=0; i<TOTAL_MOTOR; i++)
    {
        MOT[i].ScanMotorStatus();
        if(MOT[i].Led[iHomeLed]==false)                                         //不在home
        {
            if(i==MTrayX || i==MInArmY || i==MOutArmY)
                continue;
            return false;
        }
    }
    return true;
}
//---------------------------------------------------------------------------
void __fastcall TfMain::DoChangeLevel()
{
    AnsiString str[4]    ={"Operator", "Engineer", "Supervisor", "HonPrec"};
    AnsiString cLevel[5] ={"Open", "Operator", "Engineer", "Supervisor", "HonPrec"};                                    //jou 2014-06-19 Security Have 5 Level
    AnsiString cLevel2[5]={"Operator", "Engineer", "PEngineer", "Supervisor", "HonPrec"};                               //wei 20160505 增加PE權限

    if(AccessLevel<=0)
        AccessLevel=0;
    if(AccessLevel>=iDefHonPrecLevel)                                           //jou 2014-06-19 Security Have 5 Level 3->iDefHonPrecLevel
        AccessLevel=iDefHonPrecLevel;                                           //jou 2014-06-19 Security Have 5 Level 3->iDefHonPrecLevel

    if(CosFunction.bSecurityHave5Level==true)                                   //jou 2014-06-19 Security Have 5 Level
    {
        if(CUSTOMER_CODE==CC_KYEC_LEE)                                          //wei 20160505 增加PE權限
            cbUserSelect->Text=cLevel2[AccessLevel];
        else
            cbUserSelect->Text=cLevel[AccessLevel];
    }
    else
    {
        cbUserSelect->Text=str[AccessLevel];
    }
}
