//******************************************************************************
//
//  注意!! SendMessageToGpibProg為Handler與GPIB軟體溝通, 修改時要小心!!
//
//******************************************************************************
void __fastcall TfMain::SendMessageToGpibProg()
{
    if(TestIF_File.iTestType==TCP_IP_MODE &&                                    //wei 20211027 open short TCP/IP
       LastSet.iTester==ON_LINE)                                                //Steven 20231113 : 修正TCP/IP Test跑Off Line
    {
    }
    else
    {
        if(bFind==false)
            return;
    }
    bEcho=false;
    bExist=false;
    COPYDATASTRUCT *pcp=new COPYDATASTRUCT ;
    pcp->dwData=0;

    HHandler2Gpib.iSendCommand=MSG_CMD_ChangeGpib;                              //wei 20150409 Add Close GPIB Command   MSG_CMD_NONE-->MSG_CMD_ChangeGpib
    HHandler2Gpib.bCloseGpib=false;                                             //kevin 20150819 off-line 一直關GPIB
    if(CUSTOMER_CODE==CC_MTI || CUSTOMER_CODE==CC_PTI)                          //Sam 20190429 : Add CC_PTI_NEWWORK
        HHandler2Gpib.iLotStatus=0;                                             //ChungHung OLP 聚成專用

    HHandler2Gpib.bTimeOutProcess=false;
    if(TestIF_File.iTestType==GPIB_MODE  ||
       (TestIF_File.iTestType==RS232_MODE &&
        TestIF_File.iRs232Mode==eRs23232Bin))
    {
        HHandler2Gpib.bSupport32Bin=true;                                       //Steven 20121112 : RS232支援32Bin b8080 --> bSupport32Bin
    }
    else
    {
        HHandler2Gpib.bSupport32Bin=false;
    }

    if(TestIF_File.iTestType==RS232_MODE &&
       TestIF_File.iRs232Mode==eRs23232Bin)                                     //Steven 20121116 : RS232回傳的最大Bin數
    {
        HHandler2Gpib.GpibAddress=TestIF_File.iRs232MaxBinCount+1;
    }
    else
    {
        HHandler2Gpib.GpibAddress=TestIF_File.iGpibAddress;
    }

    if(LastSet.iTester==ON_LINE && TestIF_File.iTestType==GPIB_MODE)            //Steven 20150713 : 整理LastSet.iTester
        bGpibMode=true;
    else
        bGpibMode=false;

    HHandler2Gpib.bSimulate=(LastSet.iTester==OFF_LINE);                        //JerryYang 20230322 : 新增2DID模式, != online改為 ==OFF_LINE         //Steven 20170530 (wei) : for GPIB Off Line

    HHandler2Gpib.bGpibMode=bGpibMode;
    for(int i=0; i<32; i++)
        HHandler2Gpib.Site[i]=0;

    HHandler2Gpib.IsTest=false;
    HHandler2Gpib.GPIBBin=iTestBinCount;                                        //kevin 20140317 add 256Bin

    HHandler2Gpib.HandlerHwnd=this->Handle;
    HHandler2Gpib.GpibHwnd=HVisionWnd;

    pcp->cbData=sizeof(HHandler2Gpib);
    pcp->lpData=(unsigned char *)&HHandler2Gpib.iSendCommand;
    bExist=false;
    SendMessage(HVisionWnd,WM_COPYDATA,(WPARAM) NULL, (LPARAM)pcp);
    delete pcp;
    oldGpibAddress=TestIF_File.iGpibAddress;
    oldLastSetiTester=LastSet.iTester;
    oldLastiTestBinCount=iTestBinCount;                                         //kevin 20140305 256bin 16->256 通知gpib
}
//---------------------------------------------------------------------------
// 紀錄每個Site的良率，並繪製成圖表於fObserver內
// 程式啟動後，前25分鐘，每分鐘紀錄一次；之後每5分鐘紀錄一次
//---------------------------------------------------------------------------
void __fastcall TfMain::UpdateRunInfo()                                         //Steven 20090714
{
    static int iOldMin=-1;
    long lPass=0, lTotal=0;

    if(iOldMin==SystemMin)
        return;
    iOldMin=SystemMin;
    if(LastSet.SystemAccSecond[0][stPowerOn]/60>25 && iOldMin%5)
        return;

    for(int i=0; i<MAX_SOCKET_ROW; i++)                                         //Steven 20140402 : MAX_Index_Row -->  MAX_SOCKET_ROW
        for(int j=0; j<MAX_SOCKET_COL; j++)                                     //Steven 20140402 : MAX_Index_Row -->  MAX_SOCKET_ROW
            for(int k=24; k>0; k--)
                RunInfo.iYieldChart[i][j][k]=RunInfo.iYieldChart[i][j][k-1];

    for(int j=24; j>0; j--)
    {
        RunInfo.iYieldHour[j]=RunInfo.iYieldHour[j-1];
        RunInfo.iYieldMin[j] =RunInfo.iYieldMin[j-1];
    }

    for(int i=0; i<TestSocket.iShtRow; i++)
    {
        for(int j=0; j<TestSocket.iShtCol; j++)
        {
            lPass=0;
            lTotal=0;
            if(bUseTwoArm32Site==true)
            {
                lPass=ArmData[2]->ArmSKET[i][j]->GetPassCT();
                lTotal=ArmData[2]->ArmSKET[i][j]->GetTotal() ;
            }
            else
            {
                if(TestIF_File.iShuttleMode==0 || (TestIF_File.iShuttleMode==1 && TestIF_File.iShuttle_Sel==0))
                {
                    lPass+=ArmData[0]->ArmSKET[i][j]->GetPassCT();
                    lTotal+=ArmData[0]->ArmSKET[i][j]->GetTotal() ;
                }

                if(TestIF_File.iShuttleMode==0 || (TestIF_File.iShuttleMode==1 && TestIF_File.iShuttle_Sel==1))
                {
                    lPass+=ArmData[1]->ArmSKET[i][j]->GetPassCT();
                    lTotal+=ArmData[1]->ArmSKET[i][j]->GetTotal() ;
                }
            }

            if(lTotal!=0)
                RunInfo.iYieldChart[i][j][0]=lPass*100/lTotal;
        }
    }

    RunInfo.iYieldHour[0]=SystemHour;
    RunInfo.iYieldMin[0] =SystemMin;

    RunInfo.SystemTime=StatusBar1->Panels->Items[6]->Text;

    if(fObserver->bShow)
        fObserver->UpdateYieldChart();

    fObserver->ProcessRunInfo();
    if(LastSet.iJamCount[1]!=0)                                                 //Steven 20141111 : 秒轉為時分秒
    {
        RunInfo.MTBA=ConvertMSecToSPC(ChangeToFloatNonPcnt((double)((LastSet.SystemAccSecond[0][stPauseTime]+LastSet.SystemAccSecond[0][stProductTime]+LastSet.SystemAccSecond[0][stJamTime])), (double)(LastSet.iJamCount[1])));  //Isaac 20180417 (Steven) 修正MTBF公式(pause+production+jam)/jamcount
    }
    else
    {
        RunInfo.MTBA=ConvertMSecToSPC(LastSet.SystemAccSecond[0][stPauseTime]+LastSet.SystemAccSecond[0][stProductTime]+LastSet.SystemAccSecond[0][stJamTime]);
    }

    RunInfo.MUBA=fObserver->labMUBA->Caption;
}
