void __fastcall TfMain::AutoOnecycleHomeStartTimeCount()                        //Isaac 20210821 : 全智要求定時onecycle回home,start
{
    static int isecondcount=0;

    if(SystemStart==false)
        return;
    isecondcount++;

    //時間到了
    if(isecondcount>=TestIF_File.iAutoOnecycleHomStartTime*60)
    {
        isecondcount=0;
        bIsAvoidIndexShiftOneCycle=true;
        fMain->BtnOneCycleClick(fMain);
    }
}
