void __fastcall TfMain::ShowNowStatus(TColor cFontColor, AnsiString Capstr)
{
    AnsiString static sData="";
    if(Capstr=="Running")
    {
        if(bLoadCellTest)                                                       //kevin 20190306 add load cell check
        {
            Capstr="LoadCell Check";
        }
        else if(lbArm1Torque->Caption=="2:Writing" || lbArm1Torque->Caption=="2:Reading" ||
                lbArm0Torque->Caption=="1:Writing" || lbArm0Torque->Caption=="1:Reading" ||
                lbArm0Torque->Caption=="---"       || lbArm1Torque->Caption=="---")
        {
            Capstr="Index Check";
        }
    }
    else
    {
        if(Capstr=="LOCK" && palMainStatus->Caption!="LOCK")
        {
            NewRecordProcess("MES2126", "LOCK pressed", "ShowNowStatus");
        }
    }

    if(Capstr=="Onecycle Cleaning")
    {
       palMainStatus->Font->Size=30;                                            //kevin 20140411  33->30
    }
    else if(Capstr=="Auto Alignment Mode")                                      //JimmyChiu 20211020 : Auto alignment mode
    {
        palMainStatus->Font->Size=26;
    }
    else if(Capstr=="ATC Self Test")                                            //Ifor 20160823 add ATC Self Test 顯示大小  //Ifor 20161103 換位置避免字型大小未改變
    {
        palMainStatus->Font->Size=32;
    }
//    else if(LastSet.iTester==ON_LINE)                                         //kevin 20140411
//    {
//        palMainStatus->Font->Size=48;                                         //kevin 20120710 Autoclean
//    }
    else if(Capstr=="Save Fail Image processing...")
    {
        palMainStatus->Font->Size=20;
    }
    else if(IniConfig.bD44CheckIndexICDestroy &&
            iIndexTakeDeviceChk2 !=0 && bIndexplaceCheck)                       //kevin 20190201 add
    {
            palMainStatus->Font->Size=20;
    }
    else if(IniConfig.bI40_bStartProductOnLine &&                               //kevin 20180517 change config setup//Ifor 20161109 Fix #define ASE_KaohSiung  Tester==OFF_LINE 字行會會一直閃爍問題
            LastSet.iTester==OFF_LINE)
    {
        palMainStatus->Font->Size=30;
    }
    else
    {
        palMainStatus->Font->Size=48;                                           //Ifor 20161103 add 避免ATC 機台 與 非ATC 機台 字型顯示大小有差異
    }

    if(IniConfig.bEnable_SECS_GEM==true)
    {
        if(sMachineState!=palMainStatus->Caption)
        {
            sMachinePreState=sMachineState;                                     // 2013.09.30 , Joye , KYEC SECS/GEM
            for(int i=0; i<30; i++)
            {
                if(sMachinePreState==sMacStatus[i])
                {
                    iSECSGEMMachinePreState=i+1;                                //Ifor 20221019 add: Machine PreS tate改成int  //1019
                    break;
                }
            }
//            EventReport(SECS_EVENT.RunStatus);                                //JerryYang 20260611 : 修正加熱秒數倒數會一直報狀態改變的Event
            sMachineState=palMainStatus->Caption;

            int val;//, val2;
            AnsiString s2="";

            s2=fMain->palMainStatus->Caption;                                   //JerryYang 20260611 : 修正加熱秒數倒數會一直報狀態改變的Event
            val=StrToIntDef(Capstr, -1);         //new
            //val2=StrToIntDef(s2, -1);            //old
            if(val==-1)  // 注意 -1 也可能是合法值，需視情況
            {
                EventReport(SECS_EVENT.RunStatus);
            }
        }

        if(Capstr!=palMainStatus->Caption)                                      //JerryYang 20220215 : MachinePreState改成int
        {
            for(int i=0; i<30; i++)
            {
                if(Capstr==sMacStatus[i])
                {
                    iSECSGEMMachineState=i+1;                                   //1020
                    break;
                }
            }
        }
    }

    if(Capstr.Length()>=14)                                                     //JerryYang 20250219 : add
    {
        palMainStatus->Font->Size=28;
    }
    else
    {
        palMainStatus->Font->Size=48;
    }

    palMainStatus->Font->Color=cFontColor;
    palMainStatus->Caption=Capstr;
    ASE_ReturnState=Capstr;                                                     //kevin 20150925
    fMain->labDelayStatus->Font->Color=cFontColor;                              //wei 20171020 延遲狀態顯示

    if(Capstr=="Auto Alignment Mode")                                           //JimmyChiu 20211020 : Auto alignment mode
        palMainStatus->Color=clYellow;
    else
        palMainStatus->Color=(TColor)0x00EAEAEA;                                //back color

    if(CUSTOMER_CODE==CC_ASE_KaohSiung)                                         //kevin 20220602 Handle 狀態回復 Run Alarm Pause Halt
    {
        if(sData!=Capstr)
        {
           sData=Capstr;
           ASESendMessage->SendFormData(Capstr);
        }
    }
}
//------------------------------------------------------------------------------
void __fastcall TfMain::DrawTestSitePanel()
{
    int iRow=TestSocket.iShtRow;
    int iCol=TestSocket.iShtCol;
    bool bStandardSiteMap=CheckSiteMapIsStander();

    if(CUSTOMER_CODE==CC_ASE_KaohSiung &&                                       //kevin 20150605 add ASE_KaohSiung
       TestIF_File.iTestMode==_8Site2X4 &&
       CosFunction.bEnableOctal_12Kit==true &&
       TestIF_File.bOctal_12Kit==true)                                          //wei 20150519 8 Site 顯示 12 Site
    {
        iCol=6;
    }

    if(IniConfig.bA09_ByArmCloseSite &&
       bUseTwoArm32Site==false)
    {
        iRow*=2;
    }

    mtDutOnOff->XItem=iCol;
    mtDutOnOff->YItem=iRow;
    mtDutCol->XItem=iCol;
    mtDutRow->YItem=iRow;

    for(int i=0; i<iCol; i++)
    {
        mtDutCol->SetCellNumber(i, 0, AnsiString(char('a'+i)).c_str());
        mtDutCol->SetCellColorIndex(i, 0, 0);
    }

    palArmSeperater->Visible=(IniConfig.bA09_ByArmCloseSite         ||
                              bUseTwoArm32Site==true);

    if(IsNNMode()==NN_1Row)
    {
        mtDutRow->SetCellNumber(0, 0, AnsiString("A"));
        mtDutRow->SetCellNumber(0, 1, AnsiString("B"));
        mtDutRow->SetCellColorIndex(0, 0, 3);
        mtDutRow->SetCellColorIndex(0, 1, 3);
    }
    else if(IniConfig.bA09_ByArmCloseSite &&
            (IsNNMode()!=NN_2Row))
    {
        if(iRow>2)
        {
            mtDutRow->SetCellNumber(0, 0, AnsiString("Arm2 A"));
            mtDutRow->SetCellNumber(0, 1, AnsiString("Arm2 B"));
            mtDutRow->SetCellNumber(0, 2, AnsiString("Arm1 A"));
            mtDutRow->SetCellNumber(0, 3, AnsiString("Arm1 B"));

            if(TestIF_File.iShuttleMode==1)
            {
                if(TestIF_File.iShuttle_Sel==0)
                {
                    mtDutRow->SetCellColorIndex(0, 0, 2);
                    mtDutRow->SetCellColorIndex(0, 1, 2);
                    if(bStandardSiteMap)
                    {
                        mtDutRow->SetCellColorIndex(0, 2, 0);
                        mtDutRow->SetCellColorIndex(0, 3, 0);
                    }
                    else
                    {
                        mtDutRow->SetCellColorIndex(0, 2, 1);
                        mtDutRow->SetCellColorIndex(0, 3, 1);
                    }
                }
                else if(TestIF_File.iShuttle_Sel==1)
                {
                    mtDutRow->SetCellColorIndex(0, 2, 2);
                    mtDutRow->SetCellColorIndex(0, 3, 2);
                    if(bStandardSiteMap)
                    {
                        mtDutRow->SetCellColorIndex(0, 0, 0);
                        mtDutRow->SetCellColorIndex(0, 1, 0);
                    }
                    else
                    {
                        mtDutRow->SetCellColorIndex(0, 0, 1);
                        mtDutRow->SetCellColorIndex(0, 1, 1);
                    }
                }
            }
            else
            {
                for(int j=0; j<iRow; j++)
                {
                    if(bStandardSiteMap)
                        mtDutRow->SetCellColorIndex(0, j, 0);
                    else
                        mtDutRow->SetCellColorIndex(0, j, 1);
                }
            }
        }
        else
        {
            mtDutRow->SetCellNumber(0, 0, AnsiString("Arm2 A"));
            mtDutRow->SetCellNumber(0, 1, AnsiString("Arm1 A"));

            if(TestIF_File.iShuttleMode==1)
            {
                if(TestIF_File.iShuttle_Sel==0)
                {
                    mtDutRow->SetCellColorIndex(0, 0, 2);
                    if(bStandardSiteMap)
                    {
                        mtDutRow->SetCellColorIndex(0, 1, 0);
                    }
                    else
                    {
                        mtDutRow->SetCellColorIndex(0, 1, 1);
                    }
                }
                else if(TestIF_File.iShuttle_Sel==1)
                {
                    mtDutRow->SetCellColorIndex(0, 1, 2);
                    if(bStandardSiteMap)
                    {
                        mtDutRow->SetCellColorIndex(0, 0, 0);
                    }
                    else
                    {
                        mtDutRow->SetCellColorIndex(0, 0, 1);
                    }
                }
            }
            else
            {
                for(int j=0; j<iRow; j++)
                {
                    if(bStandardSiteMap)
                        mtDutRow->SetCellColorIndex(0, j, 0);
                    else
                        mtDutRow->SetCellColorIndex(0, j, 1);
                }
            }
        }
    }
    else
    {
        for(int j=0; j<iRow; j++)
        {
            mtDutRow->SetCellNumber(0, j, AnsiString(char('A'+j)).c_str());
            mtDutRow->SetCellColorIndex(0, j, 3);
        }
    }
}
