//------------------------------------------------------------------------------
void __fastcall TfMain::ShowFormByInitPos()                                     //ChungHung 20110822
{
    int TempTop =fTemperFrom->Top+fTemperFrom->Height;
    int TempLeft=fTemperFrom->Left+fTemperFrom->Width;
    int MainLeft=fMain->Left+fMain->Width;

    fMain->Left=0;
    fMain->Top =0;

    if(fTemperFrom->bShow==false)
    {
        TempTop=fTestCategory->Top+fTestCategory->Height+20;
    }

    if((iSocketBaseTempCount!=eDut1ea) && (IniConfig.bSPILFunction==true))      //Ifor 20160115 修正矽品 LotInfo 顯示異常  //JerryYang 20170328 (Jou) 矽品客戶碼統一用SPILFunction
    {
        if(USE_16_HEATER<=eht16HeaterEJ1N)                                      //Ifor 20160420 修正超過16組加熱會有蓋屏的問題
            TempTop=TempTop-70;                                                 //Ifor 20160412 調整修正
    }

    if(MainLeft>TempLeft)
    {
        TempLeft=MainLeft;
    }

    fSortCT->Left       =TempLeft;
    fSortCT->Top        =0;

    if(fLotInfo->bShow==true)
    {
        fLotInfo->Left      =201;
        fLotInfo->Top       =TempTop;
        fContactCT->Left    =fLotInfo->Left+fLotInfo->Width;
    }
    else
    {
        fContactCT->Left    =201;
    }

    fContactCT->Top     =TempTop;

    fTestCategory->Left =TempLeft;
    fTestCategory->Top  =fSortCT->Top+fSortCT->Height;
    fShowBinSelect->Left=fContactCT->Left+fContactCT->Width;
    fShowBinSelect->Top =TempTop;
}
//------------------------------------------------------------------------------
void __fastcall TfMain::LoadImage()
{
    bool bHonPrec=false;
    if(FileExists(BmpPath+"\\HonPrec.bmp"))                                     //Steven 20200703 : 變更Logo為鴻勁精密
    {
        bHonPrec=true;
        imgLogo->Picture->LoadFromFile(BmpPath+"\\HonPrec.bmp");
    }
    else
    {
        if(FileExists(BmpPath+"\\logo.bmp"))
            imgLogo->Picture->LoadFromFile(BmpPath+"\\logo.bmp");
    }

    imgLogo->Picture->Bitmap->Transparent =true;
    imgLogo->Picture->Bitmap->TransparentColor = imgLogo->Canvas->Pixels[0][0];

    imgLogo->Canvas->Font->Color=TColor(0x001D26C3);                            //Steven 20190924 : Add for SVN version
    imgLogo->Canvas->Font->Size=8;

    #ifdef FOR_EVAN                                                             //Steven 20230110 : 吳如春要的版本
        imgLogo->Canvas->TextOutA(5, 5, "For JCET濱江");
    #endif
    #ifdef FOR_QLE                                                              //Steven 20230110 : For渠梁
        imgLogo->Canvas->TextOutA(5, 5, "For QLE");
    #endif

    if(bHonPrec)                                                                //Ifor 避免版本長度太長無法顯示
    {
        imgLogo->Canvas->TextOutA(130, 60, SVNRevision);
    }
    else
    {
        if(imgLogo->Picture->Bitmap->Height>110)
            imgLogo->Canvas->TextOutA(115, 90, SVNRevision);
        else
            imgLogo->Canvas->TextOutA(100, 68, SVNRevision);
    }
}
//------------------------------------------------------------------------------
void __fastcall TfMain::InitDIOStstus(bool bNeedOn)
{
#ifndef SOFT_SIMULTE
    memcpy(&Prod.DIOCfg.cModeName[0], &TTLCfg.cModeName[0], sizeof(TTLCfg));
    for(int i=0; i<8; i++)                                                      //Alick 20161011 (Steven) : TTL支援8Site
    {
        SW[TTL_StartData[i]].Type=Prod.DIOCfg.iSTLogicMode;
        SW[TTL_StartData[i]].Off();

        if(Prod.DIOCfg.iDutType==DUTPosPluse)
            SW[TTL_Dut[i]].On();                                                //0v
        else
            SW[TTL_Dut[i]].Off();                                               //5V
    }
    SW[SwClear2].OnOff(bNeedOn);
    SW[SwClear6].OnOff(bNeedOn);                                                //Alick 20161011 (Steven) : TTL支援8Site
    TTLLog("InitDIOStstus");                                                    //Steven 20151123 : Log for TTL
#endif
}
