//------------------------------------------------------------------------------
void __fastcall TfMain::edSoakTimeMouseDown(TObject *Sender,
      TMouseButton Button, TShiftState Shift, int X, int Y)
{
    if(CosFunction.bHiSiliconFunction==true)                                    //Ifor 20170905 (wei) :海思專版可使用獨立密碼修改溫度
    {
        if(CUSTOMER_CODE==CC_KYEC_LEE)                                          //Ifor 20170905 (wei) :京元海思專版使用PE模式修改溫度
        {
            if(bEnablePEModel==false)
            {
                return;
            }
        }
        else
        {
            if(FormHS->CheckIndependentPassWord())
            {
                return;
            }
        }
    }

    if(IniConfig.bTemp25degControl==true)                                       //jou 2014-06-07 Temperature 25 deg. control
    {
        if((TestIF_File.iTestMode==_8Site2X4 ||
            TestIF_File.iTestMode==_16Site2X8 ||
            TestIF_File.iTestMode==_16Site4X4) &&                               //Sam 20190226 : 16Site4X4
           (LastSet.iTemperature==Tempture_Hot ||
            LastSet.iTemperature==Tempture_AmbientHot) &&                       //kevin 20180811 (Steven) : add 恆溫控制
            Temperature.iIndexHeatMode==HeadOnly)
        {
            if(IndexHasIC() || ShuttleHasIC() || InArmSuck.HasIC() ||
               MOT[MMPlate1].HasIC() || MOT[MMPlate2].HasIC())
            {
                ShowErrorMessage("MES1646", 0, MMSystem, false, "SoakTimeMouseDown1");                                  //Must finish [Clean out]!!
                return;
            }
        }
    }
    else if(IniConfig.bI03AmbientTempControl &&
            LastSet.iTemperature==Tempture_AmbientHot)                          //kevin 20140918 恆溫控制
    {
        if(IndexHasIC() || ShuttleHasIC() || InArmSuck.HasIC())
        {
            ShowErrorMessage("MES1646", 0, MMSystem, false, "SoakTimeMouseDown2");                                      //Must finish [Clean out]!!
            return;
        }
    }

    if(fSecurity->Insufficient(7)==false)                                       //jou 981207 權限控制
        return;

    if(CUSTOMER_CODE==CC_KYEC_LEE || CUSTOMER_CODE==CC_KYEC_XILINX)             //20140320 wei  KYEC不卡權限
    {
        if(AccessLevel<LevelSet.AccessLevel[32])
        {
            edSoakTime->Enabled=false;
            return;
        }
        else
        {
            edSoakTime->Enabled=true;
        }
    }

    if(Barcode_Reader(bcTemperature)==0)                                        // 20140103 wei KYEC Barcode Reader
    {
        return;
    }

    TemperatureSoakTimeBackup=edSoakTime->Text;                                 //kevin 20160908 soak time
    fQwertyKey->ShowQwertyKey((TEdit *)Sender, N_INTEGER, 0, true, 5, 10000);
    TEdit *TempEdit=(TEdit *)Sender;

    if(TemperatureBackup!=TempEdit->Text)                                       //Steven 20120910 : 溫度的Edit暫存
    {
        if(IniConfig.bChangeTempAutoSetDown)                                    //Steven 20110708
        {
            bChangeTemp=false;
            spbSetClick(this);
        }
        else
        {
            bChangeTemp=true;
        }
    }
}
//******************************************************************************
//
//  注意!! edWorkTemperBaseMouseDown為Handler 溫度設定相關, 修改時要小心!!
//
//******************************************************************************
void __fastcall TfMain::edWorkTemperBaseMouseDown(TObject *Sender,
      TMouseButton Button, TShiftState Shift, int X, int Y)
{
    if(CosFunction.bHiSiliconFunction==true)                                    //Ifor 20170905 :海思專版可使用獨立密碼修改溫度
    {
        if(CUSTOMER_CODE==CC_KYEC_LEE)                                          //Ifor 20170905 :京元海思專版使用PE模式修改溫度
        {
            if(bEnablePEModel==false)
            {
                return;
            }
        }
        else
        {
            if(FormHS->CheckIndependentPassWord())
            {
                return;
            }
        }
    }

    if(CUSTOMER_CODE==CC_SCK && IniConfig.bEnableRms)                           //Steven 20210616 : JSCK RMS enabled, can not changed "Site map, temperature & Bin map"
    {
        return;
    }

    if(IniConfig.bTemp25degControl==true)                                       //jou 2014-06-07 Temperature 25 deg. control
    {
        if((TestIF_File.iTestMode==_8Site2X4 ||
            TestIF_File.iTestMode==_16Site2X8 ||
            TestIF_File.iTestMode==_16Site4X4) &&                               //Sam 20190226 : 16Site4X4
           LastSet.iTemperature==Tempture_Hot &&
           Temperature.iIndexHeatMode==HeadOnly)
        {
            if(IndexHasIC() || ShuttleHasIC() || InArmSuck.HasIC() ||
               MOT[MMPlate1].HasIC() || MOT[MMPlate2].HasIC())
            {
                ShowErrorMessage("MES1646", 0, MMSystem, false, "WorkTemperBaseMouseDown1");                            //Must finish [Clean out]!!
                return;
            }
        }
    }
    else                                                                        //if(IniConfig.bI03AmbientTempControl && LastSet.iTemperature==Tempture_AmbientHot)//kevin 20140918 恆溫控制
    {
        if(IndexHasIC() || ShuttleHasIC() || InArmSuck.HasIC() ||
           HasICUnderMachine() || HasAnyICInMachine())                          //kevin 20160607
        {
            ShowErrorMessage("MES1646", 0, MMSystem, false, "WorkTemperBaseMouseDown2");                                //Must finish [Clean out]!!
            return;
        }
    }

    if(CUSTOMER_CODE!=CC_KYEC_LEE &&
       CUSTOMER_CODE!=CC_KYEC_XILINX)                                           //20140320 wei  KYEC不卡權限
    {
        if(fSecurity->Insufficient(7)==false)                                   //jou 981207 權限控制
            return;
    }

    if(CUSTOMER_CODE==CC_KYEC_LEE || CUSTOMER_CODE==CC_KYEC_XILINX)             //20140320 wei  KYEC不卡權限
    {
        if(AccessLevel<LevelSet.AccessLevel[32])
        {
            edWorkTemperBase->Enabled=false;
            return;
        }
        else
        {
            edWorkTemperBase->Enabled=true;
        }
    }

    if(Barcode_Reader(bcTemperature)==0)                                        // 20140103 wei KYEC Barcode Reader
    {
        return;
    }

    if(LastSet.iTemperature==Tempture_Ambient && Temperature.bATCActiveCooling)                                         //wei 20151013  by Setup File ATC Ambient Temp set
        TemperatureBackup=edATCAmbientTemper->Text;                             //Steven 20120910 : 溫度的Edit暫存
    else
        TemperatureBackup=edWorkTemperBase->Text;                               //Steven 20120910 : 溫度的Edit暫存

    dTempMax=fTemp_Set->MaxTempSetting();
    dTempMin=fTemp_Set->MinTempSetting();
    fQwertyKey->ShowQwertyKey((TEdit *)Sender, N_DOUBLE, 2, true, dTempMax, dTempMin);

    if(TemperatureBackup!=edWorkTemperBase->Text ||
       TemperatureBackup!=edATCAmbientTemper->Text)                             //Steven 20120910 : 溫度的Edit暫存
    {
        if(IniConfig.bChangeTempAutoSetDown)                                    //Steven 20110708
        {
            bChangeTemp=false;
            spbSetClick(this);
        }
        else
        {
            bChangeTemp=true;
        }
    }
}
//------------------------------------------------------------------------------
void __fastcall TfMain::SetToDefineValue1Click(TObject *Sender)
{
    int iTime=0;
    int ret=MessageDlg("Sure Set To Define Value? (確定設定為預設值？)", mtConfirmation, TMsgDlgButtons()<<mbYes<<mbNo, 0);
    if(ret==mrNo)
        return;

    GetDummyVacuum();
    for(int i=0; i<2; i++)
    {
        iTime=DummyVacuum.iArmVacuumOn;
        InArmSuck.Suck[0+i][0].VacuumOnTime=iTime;
        InArmSuck.Suck[0+i][1].VacuumOnTime=iTime;
        InArmSuck.Suck[0+i][2].VacuumOnTime=iTime;
        InArmSuck.Suck[0+i][3].VacuumOnTime=iTime;

        OutArmSuck.Suck[0+i][0].VacuumOnTime=iTime;
        OutArmSuck.Suck[0+i][1].VacuumOnTime=iTime;
        OutArmSuck.Suck[0+i][2].VacuumOnTime=iTime;
        OutArmSuck.Suck[0+i][3].VacuumOnTime=iTime;

        iTime=DummyVacuum.iArmVacuumOff;
        InArmSuck.Suck[0+i][0].VacuumOffTime=iTime;
        InArmSuck.Suck[0+i][1].VacuumOffTime=iTime;
        InArmSuck.Suck[0+i][2].VacuumOffTime=iTime;
        InArmSuck.Suck[0+i][3].VacuumOffTime=iTime;

        OutArmSuck.Suck[0+i][0].VacuumOffTime=iTime;
        OutArmSuck.Suck[0+i][1].VacuumOffTime=iTime;
        OutArmSuck.Suck[0+i][2].VacuumOffTime=iTime;
        OutArmSuck.Suck[0+i][3].VacuumOffTime=iTime;

        iTime=DummyVacuum.iIndexVacuumOn;
        FTestSuck.Suck[0+i][0].VacuumOnTime=iTime;
        FTestSuck.Suck[0+i][1].VacuumOnTime=iTime;
        FTestSuck.Suck[0+i][2].VacuumOnTime=iTime;
        FTestSuck.Suck[0+i][3].VacuumOnTime=iTime;
        BTestSuck.Suck[0+i][0].VacuumOnTime=iTime;
        BTestSuck.Suck[0+i][1].VacuumOnTime=iTime;
        BTestSuck.Suck[0+i][2].VacuumOnTime=iTime;
        BTestSuck.Suck[0+i][3].VacuumOnTime=iTime;

        iTime=DummyVacuum.iIndexVacuumOff;
        FTestSuck.Suck[0+i][0].VacuumOffTime=iTime;
        FTestSuck.Suck[0+i][1].VacuumOffTime=iTime;
        FTestSuck.Suck[0+i][2].VacuumOffTime=iTime;
        FTestSuck.Suck[0+i][3].VacuumOffTime=iTime;
        BTestSuck.Suck[0+i][0].VacuumOffTime=iTime;
        BTestSuck.Suck[0+i][1].VacuumOffTime=iTime;
        BTestSuck.Suck[0+i][2].VacuumOffTime=iTime;
        BTestSuck.Suck[0+i][3].VacuumOffTime=iTime;
    }
    CatchTraySuck.Suck[0][0].VacuumOnTime=650;
    CatchTraySuck.Suck[0][0].VacuumOffTime=31;

    for(int i=0; i<InArmSuck.iMaxRow; i++)
    {
        for(int j=0; j<InArmSuck.iMaxCol; j++)
        {
            LastSet.iInArmVacuumDummyOnTime[i][j]=InArmSuck.Suck[i][j].VacuumOnTime;
            LastSet.iOutArmVacuumDummyOnTime[i][j]=OutArmSuck.Suck[i][j].VacuumOnTime;
            LastSet.iInArmVacuumDummyOffTime[i][j]=InArmSuck.Suck[i][j].VacuumOffTime;
            LastSet.iOutArmVacuumDummyOffTime[i][j]=OutArmSuck.Suck[i][j].VacuumOffTime;
        }
    }
    for(int i=0; i<MAX_Index_Row; i++)
    {
        for(int j=0; j<NEW_MAX_Index_Col; j++)
        {
            LastSet.iFTestArmVacuumDummyOnTime[i][j]=FTestSuck.Suck[i][j].VacuumOnTime;
            LastSet.iBTestArmVacuumDummyOnTime[i][j]=BTestSuck.Suck[i][j].VacuumOnTime;
            LastSet.iFTestArmVacuumDummyOffTime[i][j]=FTestSuck.Suck[i][j].VacuumOffTime;
            LastSet.iBTestArmVacuumDummyOffTime[i][j]=BTestSuck.Suck[i][j].VacuumOffTime;
        }
    }

    LastSet.iCatchArmVacuumDummyOnTime  =CatchTraySuck.Suck[0][0].VacuumOnTime;
    LastSet.iCatchArmVacuumDummyOffTime =CatchTraySuck.Suck[0][0].VacuumOffTime;
}
