void __fastcall TfMain::FormCreate(TObject *Sender)
{
//    CheckWindowsIsXP();                                                       //Steven 20171214 (Wei) : 判斷作業系統是不是XP
    if(MachineTypeChoice==Type_HT9045)                                          //9045
        Application->Title="HT-9045W";
    else if(MachineTypeChoice==Type_HT9045_12Site)                              //ChungHung 20130507 add HT9045 updata for 12site 517
        Application->Title="HT-9045W_12Site";
    else
        Application->Title="HT-9046";

    AnsiString dir="D:\\Movie";
    if(!DirectoryExists(dir))
    {
        MoveFile("D:\\HT9045\\Error\\Movie", dir.c_str());
    }

    bBoostFirstBoost=true;
    Application->OnException = AppException;                                    //ChungHung 20141226 add catch exception
    BV=new TStringList;                                                         //Click Event,Auto Save log
    BL=new TList;
    //AI(ht9045-v899) 20260423: BootLog checkpoint - FormCreate finished without exception
    WriteBootLog("TfMain::FormCreate Done");
}
//------------------------------------------------------------------------------
void __fastcall TfMain::ShowRTCState(int iState)
{
    switch(iState)
    {
        case 0:
            labRTCCD->Caption="RTC Off Line";
            labRTCCD->Font->Color=clTeal;
            break;
        case 1:
            labRTCCD->Caption="RTC On Line";
            labRTCCD->Font->Color=clBlue;
            break;
    }
    return;
}
//------------------------------------------------------------------------------
void __fastcall TfMain::ShowATCState(int iState)                                //Steven 20120410 : Hontech ATC
{
    switch(iState)
    {
        case 0:
            labATC->Caption="ATC Off Line";
            labATC->Font->Color=clTeal;
            break;
        case 1:
            if(Temperature.bEnableTJFunction ||                                 //Steven 20231214 : #R231127-ATK-ATC60-02 , Display TJ mode on the main screen for ATC6.0
               Temperature.bUseTjFunction)
                labATC->Caption="ATC On Line with TJ mode";
            else
                labATC->Caption="ATC On Line";
            labATC->Font->Color=clBlue;
            break;
        case 2:                                                                 //Hmy 20240207 Add Send Pf Par to Atc
            labPFStatus->Visible=true;
            if(Temperature.bPowerFollower_Enable==true)
            {
                if(fMain->labPFStatus->Caption!="Power follower :On")
                    fMain->labPFStatus->Caption="Power follower :On";
            }
            else
            {
                if(fMain->labPFStatus->Caption!="Power follower :Off")
                    fMain->labPFStatus->Caption="Power follower :Off";
            }
            break;
        case 3:                                                                 //Hmy 20240207 Add Send Pf Par to Atc
            labPFStatus->Visible=false;
            break;
    }
    return;
}
//------------------------------------------------------------------------------
void __fastcall TfMain::ShowOCRState(int iState)                                //ChungHung 20120830 add OCR Function add
{
    if(BAR_CODE_INSTALL!=ebctUninstall)                                         //Steven 20160123 : For 2D function
    {
        if(TestIF_File.bEnableBarCode)
        {
            if(TestIF_File.i2DIDFormat==eAMD)                                   //JerryYang 20200422 2DID format選項改用下拉選單
            {
                labOCR->Caption="2D Camera ON";
                labOCR->Font->Color=clBlue;
//                labOCR->Font->Size=18;                                        //Ifor 20191025 : 不改變字體太小避免與RTC文字重疊
            }
            else
            {
                if(TestIF_File.bEnableBottom2D)
                {
                    labOCR->Caption="Bottom 2D Function On Line";
                }
                else
                {
                    labOCR->Caption="Top 2D Function On Line";
                }
                labOCR->Font->Color=clBlue;
            }

            if(USE_TRAY_MAPPING==1 && USE_KEYENCE_EMPTY==3)                     //JerryYang 20250113 : Color上方TrayID
            {
                labOCR->Font->Size=10;
                if(TestIF_File.bEnableTrayID2)
                {
                    labOCR->Caption=labOCR->Caption+"/Tray ID Function Enabled";
                    labOCR->Visible=true;
                }
                else
                {
                    labOCR->Caption=labOCR->Caption+"/Tray ID Function Disabled";
                    labOCR->Font->Color=clRed;
                    labOCR->Visible=true;
                }
            }
            else
            {
                labOCR->Font->Size=14;
            }
        }
        else
        {
            if(TestIF_File.i2DIDFormat==eAMD)                                   //JerryYang 20200422 2DID format選項改用下拉選單
            {
                labOCR->Caption="2D Camera OFF";
                labOCR->Font->Color=clRed;
//                labOCR->Font->Size=18;                                        //Ifor 20191025 : 不改變字體太小避免與RTC文字重疊
            }
            else
            {
                labOCR->Caption="2D Function Off Line";
                labOCR->Font->Color=clTeal;
            }

            if(USE_TRAY_MAPPING==1 && USE_KEYENCE_EMPTY==3)                     //JerryYang 20250113 : Color上方TrayID
            {
                labOCR->Font->Size=10;
                if(TestIF_File.bEnableTrayID2)
                {
                    labOCR->Caption=labOCR->Caption+"/Tray ID Function Enabled";
                    labOCR->Visible=true;
                }
                else
                {
                    labOCR->Caption=labOCR->Caption+"/Tray ID Function Disabled";
                    labOCR->Font->Color=clRed;
                    labOCR->Visible=true;
                }
            }
            else
            {
                labOCR->Font->Size=14;
            }
        }
    }
    else if(USE_TRAY_MAPPING==etmInstall)                                       //wei 20161219 Tray Mapping
    {
        if(USE_KEYENCE_EMPTY==3)                                                //JerryYang 20250113 : Color上方TrayID
        {
            if(TestIF_File.bEnableTrayID2)
            {
                labOCR->Caption="Tray ID Function Enabled";
                labOCR->Font->Color=clBlue;
                labOCR->Visible=true;
            }
            else
            {
                labOCR->Caption="Tray ID Function Disabled";
                labOCR->Font->Color=clRed;
                labOCR->Visible=true;
            }
        }
        else
        {
            if(TestIF_File.bEnableTrayMap)
            {
                labOCR->Caption="Tray Mapping Function On Line";
                labOCR->Font->Color=clBlue;
                labOCR->Visible=true;
            }
            else if(TestIF_File.bEnableTrayID)
            {
                labOCR->Caption="Tray ID Function On Line";
                labOCR->Font->Color=clBlue;
                labOCR->Visible=true;
            }
            else if(TestIF_File.bEnableDeviceRemain)                            //wei 20170317 (steven) Device Remain 殘料檢測
            {
                labOCR->Caption="IC Remain Function On Line";
                labOCR->Font->Color=clBlue;
                labOCR->Visible=true;
            }
            else
            {
                labOCR->Caption="Tray Function Off Line";
                labOCR->Font->Color=clTeal;
                labOCR->Visible=false;
            }
        }
    }
    else
    {
        switch(iState)
        {
            case 0:
                if(CosFunction.bTrayOCR)
                {
                    if(INSTALL_OCR!=eocrUninstal && TestIF_File.bOcrFunction)
                    {
                        labOCR->Caption="OCR Open and Off Line";
                        labOCR->Font->Color=clTeal;
                    }
                    else
                    {
                        labOCR->Caption="OCR Close and Off Line";
                        labOCR->Font->Color=clTeal;
                    }
                }
                else
                {
                    labOCR->Caption="OCR Off Line";
                    labOCR->Font->Color=clTeal;
                }
                break;
            case 1:
                if(CosFunction.bTrayOCR)
                {
                    if(bOCRConnect)
                    {
                        labOCR->Caption="OCR Open and On Line";
                        labOCR->Font->Color=clBlue;
                    }
                    else
                    {
                        labOCR->Caption="OCR Close and Off Line";
                        labOCR->Font->Color=clTeal;
                    }
                }
                else
                {
                    labOCR->Caption="OCR On Line";
                    labOCR->Font->Color=clBlue;
                }
                break;
        }
    }
    return;
}
