//------------------------------------------------------------------------------
void __fastcall TfMain::OnHotKey(Messages::TMessage& Msg)                       //jou 2010-09-02 start : UPH顯示/隱藏 改跟NS一樣,使用Hot key開關訊息
{
    if(InitialOK==false)
        return;

    if(Msg.WParam==0)                                                           //Ctrl+A
    {
        if(IniConfig.bShowUPH==true)
        {
            IniConfig.bShowUPH=false;
            IniConfig.bShowIndexTime=false;
            IniConfig.bShowTimeInfo=false;
            IniConfig.bG01Show_TestRate=false;
            fShowBinSelect->Tab_UPH->TabVisible=false;
            fShowBinSelect->PageControl1Change(fShowBinSelect);
            StatusBar1->Panels->Items[0]->Text="";
            StatusBar1->Panels->Items[2]->Text="";
            fShowMessage->lblIndexCycleTime->Visible=false;
            fShowMessage->lblTestTime->Visible=false;
        }
        else
        {
            IniConfig.bShowUPH=true;
            IniConfig.bShowIndexTime=true;
            IniConfig.bShowTimeInfo=true;
            IniConfig.bG01Show_TestRate=true;
            fShowBinSelect->Tab_UPH->TabVisible=true;
            fShowBinSelect->PageControl1Change(fShowBinSelect);
            fShowMessage->lblIndexCycleTime->Visible=true;
            fShowMessage->lblTestTime->Visible=true;
        }
    }

    if(Msg.WParam==1000 || Msg.WParam==1001 || Msg.WParam==1002)
    {
        RecordProcess("Can not use Ctrl+V");
    }
}
