void __fastcall TfMain::btLoginClick(TObject *Sender)
{
    if(SystemStart)
        return;
    if(btLogin->Caption=="Login" || btLogin->Caption=="登入")                     //jou 20220830 : 修正中文介面登入需點擊兩次。
    {
        if(CUSTOMER_CODE==CC_ASE_CL)                                            //JerryYang 20250120 : modify
        {
        }
        else
        {
            btLogin->Caption="Logout";
            cbUserSelectChange(this);
            TemperatureEditDisable();
        }
    }
    else
    {
        btLogin->Caption="Login";
        cbUserSelect->ItemIndex=0;
        AccessLevel=0;
        fMain->EnabledSetupFile(false);
        fMain->ChangeLevelAttr();
        spbUserName->Caption="Operator";
        NewRecordProcess("MES2140", "======== Operator login ========");
        TemperatureEditDisable();

        if(IniConfig.bVTESTFunction==true)                                      //jou 20211125 : 上海偉測 張冬冬 要求 logout需關閉offset，避免登出時被拉到下面無法顯示。
        {
            if(fOffSet->fShow==true)
                fOffSet->Close();
        }

        //jou 2014-03-28 SPIL Handler On-line & Offline Switch Flow
#ifndef DEBUG_SPIL
        if(OFFLINE_ALARM)                                                       //Steven 20140805
        {
            if((IniConfig.bSPILFunction==true) && LastSet.iTester==OFF_LINE)    //JerryYang 20170328 (Jou) 矽品客戶碼統一用SPILFunction
            {
                if(SystemStart==true)
                    return;
                if(CheckCanChangeRealDummy()==false || HasICUnderMachine())     //Steven 20240719 : && --> ||
                    return;

                ChangeTesterConnect(ON_LINE, false);
            }
        }
#endif
    }
}
//------------------------------------------------------------------------------
void __fastcall TfMain::spbSetClick(TObject *Sender)
{
    spbSet->Down=false;

    if(SystemStart)
        return;

    double dbSetTemp=0.0;
    bool bHasErrorSet=false;
    AnsiString asErrorAddr="";

    if(Tri_Temp_Machine==1 && bDefrostKeepATCTemp==true)                        //Ztex 2023.04.19 Add HT-1032 TriTemp Function
        return;

    if(Tri_Temp_Machine==1 && bManualDefrost_Start == true && fTemp_Set->fShow==true)                                   //Ztex 2023.04.19 Add HT-1032 TriTemp Function
        return;

//    if(CosFunction.bHiSiliconFunction==true || CUSTOMER_CODE==CC_KYEC_LEE)    //Ifor 20220216 add:開放 Check the temperature Offset limit
    {
        if(LastSet.iTemperature==Tempture_Ambient && Temperature.bATCActiveCooling)
        {
            dbSetTemp=atof(fMain->edATCAmbientTemper->Text.c_str());
        }
        else
        {
            dbSetTemp=atof(fMain->edWorkTemperBase->Text.c_str());
        }

        for(int i=0; i<tcTotalCount; i++)
        {
            if(bUT150Install[i]==true)
            {
                if(FormHS->CheckTempOffset(i, Temperature.fTempOffSet[LowBase][i]+Temperature.fTempOffSet[UserOffSet][i]+dbSetTemp))
                {
                    bHasErrorSet=true;
                }
                else if(FormHS->CheckTempOffset(i, Temperature.fTempOffSet[MidBase][i]+Temperature.fTempOffSet[UserOffSet][i]+dbSetTemp))
                {
                    bHasErrorSet=true;
                }
                else if(FormHS->CheckTempOffset(i, Temperature.fTempOffSet[HigBase][i]+Temperature.fTempOffSet[UserOffSet][i]+dbSetTemp))
                {
                    bHasErrorSet=true;
                }
            }
        }

        if(bHasErrorSet==true)
        {
            if(LastSet.iTemperature==Tempture_Ambient && Temperature.bATCActiveCooling)
            {
                edWorkTemperBase->Text=IniConfig.dATCAmbientTemperature;
            }
            else
            {
                edWorkTemperBase->Text=Temperature.fWorkTemperBase;
            }
            FormHS->CheckTempOffset(0, 0, true);
            return;
        }
    }
    //<==
    //Ifor 20180809 (Steven) : add Check the temperature Offset limit Hisi_V02.20

    if(IniConfig.bTemp25degControl==true)                                       //jou 2014-06-07 Temperature 25 deg. control
    {
        if((TestIF_File.iTestMode==_8Site2X4 ||
            TestIF_File.iTestMode==_16Site2X8 ||
            TestIF_File.iTestMode==_16Site4X4) &&                               //Sam 20190226 : 16Site4X4
           LastSet.iTemperature==Tempture_Hot &&
           Temperature.iIndexHeatMode==HeadOnly)
        {
            if(IndexHasIC() || ShuttleHasIC() || InArmSuck.HasIC() ||
               MOT[MMPlate1].HasIC() || MOT[MMPlate2].HasIC())
            {
                ShowErrorMessage("MES1646", 0, MMSystem, false, "TempSetClick1");                                       //Must finish [Clean out]!!
                return;
            }
        }
    }
    else if(IniConfig.bI03AmbientTempControl &&
            LastSet.iTemperature==Tempture_AmbientHot)                          //kevin 20140918 恆溫控制
    {
        if(IndexHasIC() || ShuttleHasIC() || InArmSuck.HasIC())
        {
            ShowErrorMessage("MES1646", 0, MMSystem, false, "TempSetClick2");   //Must finish [Clean out]!!
            return;
        }
    }

    if(CUSTOMER_CODE!=CC_KYEC_LEE &&
       CUSTOMER_CODE!=CC_KYEC_XILINX &&                                         //20140320 wei  KYEC不卡權限
       CUSTOMER_CODE!=CC_Greatek)                                               //20220112 JimmyChiu Greatek不卡權限
    {
        if(fSecurity->Insufficient(32)==false)                                  //jou 981207 權限控制
            return;
    }

    if(Barcode_Reader(bcTemperature)==0)                                        // 20140103 wei KYEC Barcode Reader
    {
        return;
    }

    dTempMax=fTemp_Set->MaxTempSetting();
    dTempMin=fTemp_Set->MinTempSetting();
    edWorkTemperBase->Text=CheckRange(atof(edWorkTemperBase->Text.c_str()), dTempMax, dTempMin);

#ifdef SOFT_SIMULTE
    if(IniConfig.bTemp25degControl==true)                                       //jou 2014-06-07 Temperature 25 deg. control
        edSoakTime->Text=CheckRange(atoi(edSoakTime->Text.c_str()), 2500, 0);   //jou 2012-02-04 軟體模擬最小值不可以設定0,這樣會找不出來問題
    else
        edSoakTime->Text=CheckRange(atoi(edSoakTime->Text.c_str()), 2500, 5);   //jou 2012-02-04 軟體模擬最小值不可以設定0,這樣會找不出來問題
#else
    edSoakTime->Text=CheckRange(atoi(edSoakTime->Text.c_str()), 2500, 0);       //jou 2011-12-22
#endif

    //Ifor 20160413 矽品反應溫控器無法升溫時必須按下Set重新設定溫度才可加溫     //Ifor 20170807 (wei) Hisi_V02.01 版本開放更改 PE模式下
    if(LastSet.iTemperature==Tempture_Ambient && Temperature.bATCActiveCooling)                                         //wei 20151013  by Setup File ATC Ambient Temp set
        SetTemp(true, atof(edATCAmbientTemper->Text.c_str()), atof(edSoakTime->Text.c_str()));
    else
        SetTemp(true, atof(edWorkTemperBase->Text.c_str()), atof(edSoakTime->Text.c_str()));

    spbSet->Caption="";
    fAutomation->AmkorSendMessage(1);                                           //Steven 20120330 : ATK Site Map Monitorning

    if(ATC_SYSTEM==eATC60 || ATC_SYSTEM==eATC30)                                //20141217 ChungHung add for ATC3.0   //20141204 ChungHung add for ATC3.0
    {
        ATCInterfaceForm->ATC_60_SYS.SetTargetTemperature(atof(edWorkTemperBase->Text.c_str()));                        //Send TEMP to ATC
        ATCInterfaceForm->ATC_60_SYS.ReSendCommand(ATCInterfaceForm->ATC_60_SYS.SETTEMP);
    }
    else if(ATC_SYSTEM==eNewATCSystem)                                          //Ifor 20151230 :add New ATC Interface
    {
        ATC_InterfaceForm->SetAllTemp(atof(edWorkTemperBase->Text.c_str()));    //Ifor 20151230 :add New ATC Interface 設定工作溫度
    }
    else if(ATC_SYSTEM==eWinWay && Temperature.bATCActiveCooling==true)         //Jimmychiu 20210901
    {
        fWinway->SetTempratureAll(atof(edWorkTemperBase->Text.c_str()));
    }

    if(Temperature.bATC70Active==true)
    {
        if(LastSet.iTemperature==Tempture_Hot)                                  //Steven 20151111 : For ATC7.0 修改判斷式
        {
            ATCInterfaceForm->SendCommToATC7(ATC_SET_TEMP, Temperature.fWorkTemperBase, "");
            ATCInterfaceForm->SendCommToATC7(ATC_RUN, "", "");
        }
        else
        {
            ATCInterfaceForm->SendCommToATC7(ATC_STOP, "", "");
        }
    }

    if(Tri_Temp_Machine==1 && LastSet.iTemperature!=Tempture_Ambient && Temperature.fWorkTemperBase<=25)                //Ztex 2023.04.19 Add HT-1032 TriTemp Function
    {
        fTemp_Set->Tri_Temp_Low_Temperature_Use_Heater();                       //低溫必須開啟Heater
    }

    if(Tri_Temp_Machine==1 && LastSet.iTemperature!=Tempture_Ambient && Temperature.fWorkTemperBase>25)                 //Ztex 2023.04.19 Add HT-1032 TriTemp Function
    {
        fTemp_Set->Tri_Temp_High_Temperature_UseNo_Heater();
    }
    bALLTempFirstReady=false;                                                   //Ztex 2023.04.19 Add HT-1032 TriTemp Function
    SET_ESD_Tri_Temp(LastSet.iTemperature);                                     //Ztex 2023.04.19 Add HT-1032 TriTemp Function
}
