void __fastcall TfMain::sbConfigurationClick(TObject *Sender)
{
    sbConfiguration->Down=false;

    if(CUSTOMER_CODE==CC_SCS)                                                   //jou 2016-05-11 SCS 要求 權限不夠congif不能進入,需alarm
    {
        if(fSecurity->Insufficient(30)==false)                                  //jou 981207 權限控制
            return;
    }

    static bool bRefreshStartMode0=false;
    static bool bRefreshStartMode1=false;
    static bool bRefreshStartMode2=false;
    static bool bRefreshStartMode3=false;                                       //Steven 20220919 : 針對Auto Site Map開關整理Start Mode
    bool bBackupState=IniConfig.bE43AutoCleanUseHotplate;
    NewRecordProcess("MES2185", "Enter Configuration");

    bRefreshStartMode0=IniConfig.bA10_AutoReTest;
    bRefreshStartMode1=IniConfig.bI37_EnableFIFOMode;
    bRefreshStartMode2=IniConfig.bA51EnableEQCMode;                             //JerryYang 20200312 EQC mode新增function on/off，功能關閉時無法切EQC mode
    bRefreshStartMode3=IniConfig.bI21EnableASM;                                 //Steven 20220919 : 針對Auto Site Map開關整理Start Mode

    fConfiguration->ShowModal();
    SetWorkParameter();
    UpdateMainOperateMode();

    fYieldMonitoring->ReadFile();
    fSCKART->AccessFile(true);                                                  //Steven 20161025 (wei) : SCK ART function

    //ChungHung 20130910 alter for SCK can close site by Index
    ShowTestHeadComp(false);                                                    //ChungHung 20130910 alter for SCK can close site by Index
    if(IniConfig.bA09_ByArmCloseSite)
    {
        fTestCategory->ShowTestCategory(0);
        fTestCategory->ShowTestCategory(1);
    }

    if(bBackupState!=IniConfig.bE43AutoCleanUseHotplate)
    {
        fCleaning->LoadAutoCleanData();
    }

    if((USE_AUTO_RETEST==eartInstall  && bRefreshStartMode0!=IniConfig.bA10_AutoReTest)     ||
       (CosFunction.bHaveFIFOMode     && bRefreshStartMode1!=IniConfig.bI37_EnableFIFOMode) ||                          //JerryYang 20200312 EQC mode新增function on/off，功能關閉時無法切EQC mode
       (CosFunction.bCanDisableQAMode && bRefreshStartMode2!=IniConfig.bA51EnableEQCMode)   ||                          //Steven 20170209 : 修正開關ART時候,要重新整理Start Mode
       (IniConfig.bUseAutoSiteMapping && bRefreshStartMode3!=IniConfig.bI21EnableASM))                                  //Steven 20220919 : 針對Auto Site Map開關整理Start Mode
        SetStartModeData();
}
