//------------------------------------------------------------------------------
// 開啟檔案      kevin 20110317
//------------------------------------------------------------------------------
bool TfMain::ChoiceJobName(AnsiString Data)                                     //kevin 20130907
{
    bool bFindData=false;
    for(int i=0; i<=fMain->cbSetupFileName->Items->Count; i++)
    {
        if(fMain->cbSetupFileName->Items->Strings[i].UpperCase()==Data.UpperCase())                                     //kevin 20140918檔名強制轉大寫
        {
            fMain->cbSetupFileName->Text = fMain->cbSetupFileName->Items->Strings[i];
            fObserver->SetSiteYieldDiagram();
            fMain->cbSetupFileNameChange(fMain);
            if(IniConfig.bUseAutoSiteMapping && IniConfig.bI21EnableASM)        //kevin 20150521
            {
                if(fMain->CheckSiteMapState(true)==false &&                     //kevin 20150120 強致做autositemap
                   IniConfig.bI50_EnableAutoSiteMappingTrigger==false)          //Jimmychiu 20230707 : Auto Site Mapping Trigger Function
                {
                    RecordProcess("Trigger Auto Site Map after Change Setup File");
                    SetRunStartMode(rsmAutoSiteMap);
                    bSiteMappingCHKOK=false;
                }
                else
                {
                    SetRunStartMode(rsmInitialStart);
                }
            }
            else
            {
                bSiteMappingCHKOK=false;
                SetRunStartMode(rsmInitialStart);
            }                                                                   //kevin 20150521 end
            LastSet.iTester=ON_LINE;                                            //Steven 20150713 : 整理LastSet.iTester
            NewRecordProcess("MES2157", "Change to On_Line", "by ChoiceJobName");                                       //ChungHung 20140722 add add record
            fMain->LoadTestModePicture();
            LastSet.iRealDummy=REALLY;
            fMain->LoadRunModePicture();
            fMain->ChangeTempMode(10,false,bRefreshFunction);
            bFindData=true;                                                     //kevin 20130730 refresh
        }
    }

    if(bFindData)
        RefeshSend.bError=0;
    else
        RefeshSend.bError=1;
    return bFindData;
}
//------------------------------------------------------------------------------
//回傳先判斷程式是否存在  kevin 20110317
//------------------------------------------------------------------------------
bool ProcessReceveFuleWndConnect()                                              //kevin 20130907
{
    HReceveFuleWnd=NULL;
    HReceveFuleWnd=FindWindow("TRefeshF", "RefeshF");
    if(HReceveFuleWnd==NULL)
    {
        ShowMyMessage("選檔案執行檔不存在請重新刷BAR CODE. ");
        return false;
    }
    return true;
}
//------------------------------------------------------------------------------
//回傳開檔成功 關閉Refresh
//------------------------------------------------------------------------------
bool Respone(AnsiString Data)                                                   //kevin 20130907
{
    RefeshSend.iType=0;                                                         //表示程式存在 回傳給HANDLE
    sprintf(RefeshSend.cSendData, "%s", Data.c_str());                          //kevin 20111014 送給ccd需清空資料

    COPYDATASTRUCT *pcp=new COPYDATASTRUCT ;
    pcp->dwData=0;

    pcp->cbData=sizeof(HHandler2Gpib);
    pcp->lpData=(unsigned char *)&RefeshSend.iType;

    SendMessage(HReceveFuleWnd,WM_COPYDATA,(WPARAM) NULL, (LPARAM)pcp);
    delete pcp;
    return true;
}
//------------------------------------------------------------------------------
//傳資料給CCD  kevin 20110811
//------------------------------------------------------------------------------
bool TfMain::SendCCD(int Command, AnsiString Data)
{
    HCCDVisionWnd=FindWindow("TIdentificationForm", "Identification");
    CCDSend.iType=0;                                                            //表示程式存在 回傳給HANDLE
    sprintf(CCDSend.cSendData, "%s", Data.c_str());                             //kevin 20111014 送給ccd需清空資料

    CCDSend.iCCDDoState = Command;
    CCDSend.iCustomer = CUSTOMER_CODE;

    COPYDATASTRUCT *pcp=new COPYDATASTRUCT ;
    pcp->dwData=0;

    pcp->cbData=sizeof(CCDSend);
    pcp->lpData=(unsigned char *)&CCDSend.iType;

    SendMessage(HCCDVisionWnd,WM_COPYDATA,(WPARAM) NULL, (LPARAM)pcp);
    delete pcp;
    return true;
}
