//------------------------------------------------------------------------------
void __fastcall TfMain::sbCalculatorClick(TObject *Sender)
{
    sbCalculator->Down=false;

    if(CUSTOMER_CODE==CC_HANA_MICRON)                                           //Steven 20251007 : maintance mode for Hana
    {
        lblMaintMode->Visible=false;
        if(bMaintanceMode==false)                                               //Steven 20251007 : maintance mode for Hana
        {
            if(Application->MessageBox("Change to maintance mode?", "EP", MB_YESNO | MB_TOPMOST)==IDYES)
            {
                bMaintanceMode=true;
                lblMaintMode->Visible=true;
            }
        }
        else
        {
            bMaintanceMode=false;
        }
        return;
    }

    char uSystemRoot[64];
    AnsiString asSystemRoot;

    HWND Calc;
    Calc=::FindWindow(NULL, "小算盤");
    if(::IsWindow(Calc))
    {
        BringWindowToTop(Calc);
    }
    else
    {
        Calc=::FindWindow(NULL, "Calculator");
        if(::IsWindow(Calc))
        {
            BringWindowToTop(Calc);
        }
        else
        {
            GetSystemDirectory(uSystemRoot, 64);
            asSystemRoot=uSystemRoot;
            asSystemRoot+="\\calc.exe";
            SHELLEXECUTEINFO execinfo;
            memset(&execinfo,0,sizeof(execinfo));
            execinfo.cbSize=sizeof(execinfo);
            execinfo.lpVerb="open";
            execinfo.lpFile=asSystemRoot.c_str();
            execinfo.lpParameters="";
            execinfo.fMask=SEE_MASK_NOCLOSEPROCESS;
            execinfo.nShow=SW_SHOWDEFAULT;
            ShellExecuteEx(&execinfo);
        }
    }
}
