//------------------------------------------------------------------------------
TQPF_Timer tIOTimer;
void __fastcall TfMain::sbIOClick(TObject *Sender)
{
    sbIO->Down=false;
    if(SystemStart)
        return;

    if(fSecurity->Insufficient(4)==false)                                       //jou 981207 權限控制
        return;

    TTLLog("Enter IO form");                                                    //Steven 20151123 : Log for TTL
    ProceeToolBar();
    NewRecordProcess("MES2190", "Enter IO");
    SetWorkParameter();
    MyLaneIO.BackUpOutputData();
    fiosetview->ShowModal();
    int ret;

    if(Cylinder[C_TurnTrayArm].Enable)                                          //ChungHung 20140814 add
    {
        tIOTimer.LatchCycleTimeSec(true);
        do
        {
            Cylinder[C_TurnTrayArmLock].Off();
            if(Cylinder[C_TurnTrayArmLock].OffSensor())
                break;
        }while(tIOTimer.LatchCycleTimeSec()<Cylinder[C_TurnTrayArmLock].OffAlarmTime);

        tIOTimer.LatchCycleTimeSec(true);
        do
        {
            Cylinder[C_TurnTrayArm].Off();
            if(Cylinder[C_TurnTrayArm].OffSensor())
                break;
        }while(tIOTimer.LatchCycleTimeSec()<Cylinder[C_TurnTrayArm].OffAlarmTime);

        tIOTimer.LatchCycleTimeSec(true);
        do
        {
            Cylinder[C_TurnTrayArmLock].On();
            if(Cylinder[C_TurnTrayArmLock].OffSensor()==false)
                break;
        }while(tIOTimer.LatchCycleTimeSec()<Cylinder[C_TurnTrayArmLock].OffAlarmTime);
    }

    if(fiosetview->bOutDataChange)
    {
        ret=ShowMyMessageBox_YES_NO("IO already change,want to restore?", "(IO已經改變,是否回復測貨狀態?)");                        //Steven 20110326
        if(ret==1 && SystemStart==false)                                        //Steven 20110326
        {
            MyLaneIO.RestoreOutputData();
        }
    }

    if(Cylinder[C_Shuttle_Knocker_1].Enable)                                    //Steven 20130108 : 避免蝦頭敲敲汽缸打開撞斷
        Cylinder[C_Shuttle_Knocker_1].Off();
    if(Cylinder[C_Shuttle_Knocker_2].Enable)
        Cylinder[C_Shuttle_Knocker_2].Off();

    if(IniConfig.bEnable_SECS_GEM==true)                                        //Steven 20140528 : Secs Gem
        EventReport(SECS_EVENT.EnterIO);                                        //21     Enter I/O Page

    TTLLog("Exit IO form");                                                     //Steven 20151123 : Log for TTL
}
