void __fastcall TfMain::sbCloseProgramClick(TObject *Sender)
{
    int ret;
    if(SystemStart==true)
        return;

    if(Barcode_Reader(bcExit)==0)                                               // 20140103 wei KYEC Barcode Reader
    {
        return;
    }

    if(AccessLevel<LevelSet.AccessLevel[6])
    {
        if(Check_AllMOT_Home()==false)
        {
            ShowMyMessage("Must finish home process before terminal", "請在關閉程式前,執行歸零步驟", "Program Close");
            return;
        }
    }

//    if(InArmSuck.HasIC() && HotPlateForm.XDivision==6 && iForPlaceHPX6Step==1 && LastSet.iTemperature==Tempture_Hot)
//    {
//        ShowErrorMessage("MES1645", 0, MMSystem, false, "CloseProgramClick");   //Must finish [One Cycle]
//        return;
//    }

//    if(CUSTOMER_CODE==CC_KYEC_LEE ||                                            //Ifor 20190409 : add KYEC 關閉程式時確認是否已完成ONECYCLE
//       CUSTOMER_CODE==CC_AMKOR_Philippines)                                     //JerryYang 20200430 空跑不用完成one cycle
//    {
        if(LastSet.iRealDummy==REALLY)
        {
            if(InArmSuck.HasIC()   ||
               OutArmSuck.HasIC()  ||
               ShuttleHasIC()      ||
               IndexHasIC()        )
            {
//                ShowMyMessage("Must finish OneCycle process before terminal", "請在關閉程式前完成One Cycle", "Program Close");
                ShowErrorMessage("MES1645", 0, MMSystem, false, "CloseProgramClick");                                   //Must finish [One Cycle]
                return;
            }
        }
//    }

    if(CUSTOMER_CODE==CC_ASE_KaohSiung)
        ShowMyMessage("Please confirm if IC is still in the In/Out & index arm ", "請確認IC是否還留在 In/Out & index arm 上?");  //kevin 20210601 add close program 需確認吸嘴上是否有IC

    if(AirStream_Select==1 && ATC_InterfaceForm->IsConnect()==true)             //Ztex 2023.04.19 Add HT-1032 TriTemp Function       //關閉程式前詢問是否關閉AirStream
    {
        ret=ShowMyMessageBox_YES_NO("Sure close Air Stream??", "確定要關閉Air Stream??");
        if(ret==1)
        {
            ATC_InterfaceForm->bCloseAirMachine = true;
            ATC_InterfaceForm->SendAirMachineStatus(0, Temperature.fWorkTemperBase*10, Temperature.dSetIndexAirstreamTemp*10);
        }
    }

    ret=ShowMyMessageBox_YES_NO("Sure close??", "確定要關閉程式??");                   //jou 2011-08-24 改用 ShowMyMessageBox_YES_NO 避免畫面被蓋到下面去
    if(ret==1)
    {
        if(CUSTOMER_CODE==CC_AMKOR_Philippines && DoPassword()==false)          //JerryYang : 20200522
        {
            return;
        }

        if(IniConfig.bVTESTFunction==true)
        {
            fMesSystem->SaveStringlRecordReport();
        }

        if(CosFunction.bOEEFunction)                                            //Steven 20180417 (Jou) : OEE功能
        {                                                                       //Sam 20170810 (Steven) 移植超豐 OEE 功能 form HT-7045
            if(IniConfig.bN14_1_EnableOEEFunction==true &&
               IniConfig.iN14_1_OEERecordCycleTime>0)
            {
                fProductionInfo->EachCycleSecondDo_SaveAndUpdateOEEFiles(true);
            }
        }

        ReadWriteBinCountMode(false);                                           //kevin 20210825 寫 Bin 1  Bin 2...資料記錄
        Close();
    }
}
//------------------------------------------------------------------------------
void __fastcall TfMain::CloseGpibProgram(AnsiString Src)
{
//    if(TestIF.iTestType==RS232_MODE)                                          //wei 20150703 因為測試機不能關閉      //Isaac 20200903 :TTL RS232通訊，Mark
//        return ;

    if(bFind==false)
        return ;

    if(LastSet.iRunStartMode==rsmQAMode && bQAModeFinishCleanOut==true)         //Steven 20141023 : QA做完後的Bin
        return;

    COPYDATASTRUCT *pcp=new COPYDATASTRUCT ;
    pcp->dwData=0;
    HHandler2Gpib.bCloseGpib=true;
    if(CUSTOMER_CODE==CC_MTI || CUSTOMER_CODE==CC_PTI)                          //Sam 20190429 : Add CC_PTI_NEWWORK
        HHandler2Gpib.iLotStatus = 0;                                           //ChungHung OLP 聚成專用

    HHandler2Gpib.iSendCommand=MSG_CMD_CloseGpib;                               //wei 20150408 Add Close GPIB Command   MSG_CMD_NONE-->MSG_CMD_CloseGpib
    pcp->cbData=sizeof(HHandler2Gpib);
    pcp->lpData=(unsigned char *)&HHandler2Gpib.iSendCommand;
    SendMessage(HVisionWnd,WM_COPYDATA,(WPARAM) NULL, (LPARAM)pcp);
    delete pcp;
    HHandler2Gpib.bCloseGpib=false;                                             //kevin 20150819 off-line 一直關GPIB
    MyDBIProcess("Process", "GPIB Close - "+Src);
    WakeupGPIBdelay.SetSecAndOn(5);
    bFind=false;
}
