//------------------------------------------------------------------------------
void __fastcall TfMain::ReStartAutoSiteMapping(bool bStart)                     //jou 2011-03-24 start : Auto Site Mapping
{
    BackSiteFinish=false;
    iDoSiteMappingStep=0;
    iAutoSiteMapCount=-1;                                                       //Steven 20220811 : 紀錄目前是哪個Shuttle
    iAutoSiteCurrStep=-1;

    AdjustShuttlePlaceOrderForASM(true);                                        //Steven 20250206 : fixed ASM之中作one cycle會造成關arm 1時異常

    iAutoSiteMapHPToKit=0;
    iAutoSiteMapInArmRow=0;
    iAutoSiteMapInArmCol=0;
    iAutoSiteMapInArmCol_8=0;
    Prod.bInitialAutoSiteMap=true;
    bAutoSiteMapWaitTestResult=false;                                           //JerryYang 20170316 避免tester time out時Retry會重複進入DoJCETSiteMappingCHK(), 造成auto site mapping一次跳兩顆
    bAutoSiteMapAmbientResultCheck=false;                                       //Ifor 20190528 : add Site Mapping Ambient Check

    for(int i=0; i<2; i++)
    {
        for(int j=0; j<8; j++)
        {
            Prod.fAlreadyCheckASM[0][i][j]=false;
            Prod.fAlreadyCheckASM[1][i][j]=false;
        }
    }

    DoInArm_9045_SuckerMap();

    if(iCleanOut!=1 && MOT[MMTrayY].HasIC()==false)                             //Steven 20220825 : 修正Auto Site Map做到一半歸零後Hang up
    {
        for(int i=0; i<2; i++)
        {
            for(int j=0; j<HotPlateForm.XDivision; j++)
            {
                for(int k=0; k<HotPlateForm.YDivision; k++)
                {
                    MOT[MMPlate1+i].Tray.SiteMapData[j][k]=0;                   //Ifor 20210913 add: 清除Auto Site Mapping 補回Has Null IC資料
                }
            }
        }
    }

    if(bStart==false)
        bAutoSiteMapHotplateSave=false;

    RecordProcess("Reset step of auto site map", "ReStartAutoSiteMapping");
}
