//------------------------------------------------------------------------------
void __fastcall TfMain::SetMainRunStartMode(int iSetMode)
{
    if(TestIF_File.iTestMode==SingleSite)                                       //Steven 20120912 : Single Site不需要作Auto Site Mapping
    {
        bSiteMappingCHKOK=true;
        if(LastSet.iRunStartMode==rsmAutoSiteMap)
        {
            if(fLotInfo->cbRunMode->Visible==true &&                            //Steven 20240220 : Auto Site Map結束後, 增加檢查cbRunMode來切換模式
               fLotInfo->cbRunMode->Text.Pos("FT")>0)
            {
                SetRunStartMode(rsmContinuStart);
            }
            else if(iAutoSiteMapRunStartMode==1 ||                              //Steven 20240131 : Auto Site Map結束後, 增加檢查cbRunMode來切換模式
                    (fLotInfo->cbRunMode->Visible==true &&
                     fLotInfo->cbRunMode->Text.Pos("RT")>0))
            {
                SetRunStartMode(rsmContinuRetest);
            }
            else
            {
                SetRunStartMode(rsmContinuStart);
            }
        }

        if(CUSTOMER_CODE==CC_KYEC_LEE && iSetMode==rsmContinuStart)
            SetRunStartMode(rsmContinuStart);
    }
    else if(iSetMode==rsmContinuStart || iSetMode==rsmContinuRetest)            //Richard 20230424 : 修正RT mode下auto site mapping重複做
    {
        bSiteMappingCHKOK=true;

        if(fLotInfo->cbRunMode->Visible==true &&                                //Steven 20240220 : Auto Site Map結束後, 增加檢查cbRunMode來切換模式
           fLotInfo->cbRunMode->Text.Pos("FT")>0)
        {
            SetRunStartMode(rsmContinuStart);
        }
        else if(iAutoSiteMapRunStartMode==1 ||                                  //Steven 20240131 : Auto Site Map結束後, 增加檢查cbRunMode來切換模式
                (fLotInfo->cbRunMode->Visible==true &&
                 fLotInfo->cbRunMode->Text.Pos("RT")>0))
        {
            SetRunStartMode(rsmContinuRetest);
        }
        else
        {
            SetRunStartMode(rsmContinuStart);
        }
    }
    else if(iSetMode==rsmAutoSiteMap)
    {
        edSetOpenBin->Text="";
        if(CosFunction.bUSEJCETSiteMapMode==true)                               //jou 2016-10-28 JCET 要求Site Mapping 必須測試到pass bin才能通過
        {
            lbSetOpenBin->Visible=false;
            edSetOpenBin->Visible=false;
        }
        else
        {
            lbSetOpenBin->Visible=true;
            edSetOpenBin->Visible=true;
        }

        bSiteMappingCHKOK=false;
        SetRunStartMode(rsmAutoSiteMap);
        ReStartAutoSiteMapping(true);
        if(IniConfig.bI21EnableASM)                                             //Steven 20120207 : 只有Auto Site Mapping啟動時才要強制disable
        {
            cbRunStartMode->Enabled=false;
            cbbRunModeSel->Enabled=false;
            fBinSel->cbUseMRTMode->Enabled=false;                               //Ifor 20170414 (wei) add 鎖定 mrt 模式不可修改
        }
    }
    UpdateMainOperateMode();
}
//------------------------------------------------------------------------------
void  __fastcall TfMain::EnabledSetupFile(bool bEnabled)
{
    if(bEnabled==false ||                                                       //Steven 20250407 : 調整 cbSetupFileName 的 Enable判斷
       HasICUnderMachine()==true ||
       HasAnyICInMachine()==true)
    {
        cbSetupFileName->Enabled=false;
    }
    else if(CUSTOMER_CODE==CC_PTI && AccessLevel>=1)                            //RogerYang 20170509 (Steven) 力成只卡OP權限
    {
        cbSetupFileName->Enabled=bEnabled;
    }
    else if(IniConfig.bEnableRms)                                               //Steven 20110503
    {
        if(AccessLevel<=iDefEngineerLevel)                                      //jou 2014-06-19 Security Have 5 Level 1->iDefEngineerLevel
        {
            cbSetupFileName->Enabled=false;
        }
        else
        {
            if(CUSTOMER_CODE==CC_SCC ||
               CUSTOMER_CODE==CC_SCK)                                           //Steven 20180625 (wei) : Add SCK request
            {
                cbSetupFileName->Enabled=false;
            }
            else
            {
                if(CosFunction.bSetupFileNameControlByLevel==true)              //jou 20171011 (wei) : bSetupFileName Control By Level
                {
                    if(AccessLevel<LevelSet.AccessLevel[41])                    //ChungHung 20120423 add
                        cbSetupFileName->Enabled=false;
                    else
                        cbSetupFileName->Enabled=bEnabled;
                }
                else
                {
                    cbSetupFileName->Enabled=bEnabled;
                }
            }
        }
    }
    else if(CosFunction.bFTPFunction && IniConfig.bEnableFTP)                   // Landam 20110324 enable setup file selection
    {
        if(CUSTOMER_CODE==CC_SCC ||
           CUSTOMER_CODE==CC_SCK)                                               //Steven 20180625 (wei) : Add SCK request
        {
            cbSetupFileName->Enabled=false;
        }
        else if(AccessLevel>=5)
        {
            cbSetupFileName->Enabled=bEnabled;
        }
        else if((CUSTOMER_CODE==CC_JCET ||                                      //Ifor 20180131 (Steven) : add 長電FTP功能開啟且為海思版本不可切換工作檔
                 CUSTOMER_CODE==CC_SJ_Semiconductor ||                          //Steven 20220623 : Add SJSM
                 CUSTOMER_CODE==CC_SJ_Semiconductor_OS) &&
                CosFunction.bHiSiliconFunction==false && AccessLevel>=3)
        {
            cbSetupFileName->Enabled=bEnabled;
        }
        else if(CosFunction.bSetupFileNameControlByLevel==true &&               //Steven 20250407 : 調整 cbSetupFileName 的 Enable判斷
                AccessLevel>=LevelSet.AccessLevel[41])
        {
            cbSetupFileName->Enabled=bEnabled;
        }
        else
        {
            cbSetupFileName->Enabled=false;
        }
    }
    else if(IniConfig.bEnableErms)                                              //Steven 20160711 : 使用進階版RMS
    {
        cbSetupFileName->Enabled=false;
    }
    else
    {
        if(CosFunction.bSetupFileNameControlByLevel==true)                      //jou 20171011 (wei) : bSetupFileName Control By Level
        {
            if(AccessLevel<LevelSet.AccessLevel[41])                            //ChungHung 20120423 add
                cbSetupFileName->Enabled=false;
            else
                cbSetupFileName->Enabled=bEnabled;
        }
        else
        {
            if(CUSTOMER_CODE==CC_TFME_CHINA &&
               IniConfig.bEnable_SECS_GEM)                                      //JerryYang 20200527 工作檔鎖起來
            {
                cbSetupFileName->Enabled=false;
            }
            else
            {
                cbSetupFileName->Enabled=bEnabled;
            }
        }
    }

    if(IniConfig.bEnableRms)                                                    //Steven 20110503
    {
        if(IniConfig.bVTESTFunction==true)
        {
            fLotInfo->edDeviceName->Enabled =(AccessLevel>0) && bEnabled;
            fLotInfo->edTemp->Enabled       =(AccessLevel>0) && bEnabled;
            fLotInfo->btDownload->Enabled   =(AccessLevel>0) && bEnabled;
        }
        else
        {
            fLotInfo->edDeviceName->Enabled =bEnabled;
            fLotInfo->edTemp->Enabled       =bEnabled;
        }
        fLotInfo->cbbDeviceName->Enabled    =bEnabled;
        fLotInfo->edTemp->Enabled           =bEnabled;

        if(CosFunction.bDownloadRecipeLevelMode)                                //jou 2016-01-06 download recipe 增加權限模式選擇
            fLotInfo->coLevelMode->Enabled  =bEnabled;
    }
}
