void __fastcall TfMain::Timer4Timer(TObject *Sender)
{
    static int count=0;
    static bool bTimerRunning=false;
    if(InitialOK==false || bTimerRunning==true)
        return;

    bTimerRunning=true;

    if(REAL_TIME_CCD && COM2->bCCDDummyRum==false)                              //Steven 20110826 : Real Time CCD - 確認CCD程式有開
    {
        if(COM2->bRealTimeCom_ReceiveOK[COM2->rtVISIONON]==false)
        {
            count++;
            if(count>10)
            {
                ShowErrorMessage("WAR0330", 0, MMIndex, false, "Main--Timer4");                                         //"RTC Vision program off error!!"
                count=0;
                Timer4->Enabled=false;
            }
        }
        else
        {
            count=0;
            Timer4->Enabled=false;
        }
    }
    else
    {
        count=0;
        Timer4->Enabled=false;
    }
    bTimerRunning=false;
}
