//******************************************************************************
//
//  注意!! mtDutOnOffMouseUp為Handler Site開關, 修改時要小心!!
//
//******************************************************************************
void __fastcall TfMain::mtDutOnOffMouseUp(TObject *Sender,
      TMouseButton Button, TShiftState Shift, int X, int Y)
{
    if(SystemStart)
        return;

    bool flag=false;                                                            //ChungHung 20140429 補上
    int Z=0, ret=0;
    int iRow=0;

    if(SystemStart || fSecurity->Insufficient(10)==false)                       //jou 981207 權限控制
        return;

    if(CosFunction.bLotStartLockCriticalPara)                                   //JerryYang 20220311 : ATP鎖定Critical parameter
    {
        if(RunInfo.bLotStart)
        {
            if(bAuthCriticalPara[3])
            {
                return;
            }
        }
    }

    if(mtDutOnOff->ConvertIndexCells(X, Y)==-1)                                 //Chunghung 20140611 修正如果手殘點到邊界與邊界的中間會照成溢位
        return;

    if(LastSet.iRunStartMode==rsmFIFOMode && CUSTOMER_CODE==CC_KYEC_JCTHIU)     //Frank 20180810 (Steven) : add FIFO By Tester SiteMap
    {
        ShowMyMessage("開關Site 請至Set up內開起/關閉 Site別");
        return;
    }

    //Steven 20170125 (Wei) : 修正關Arm會導致開關Site異常
    //==>
    if(bUseTwoArm32Site==false)
    {
        if(IniConfig.bA09_ByArmCloseSite)
        {
            if(TestSocket.iShtRow==2)
            {
                if(Y>=2)
                    Y-=2;
                else
                    Z=1;
            }
            else
            {
                if(Y>=1)
                    Y-=1;
                else
                    Z=1;
            }
        }
        else
        {
            if(TestIF_File.iShuttleMode==1)
            {
                if(TestIF_File.iShuttle_Sel==1)
                {
                    Z=1;
                }
                else
                {
                    Z=0;
                }
            }
        }
    }
    //<==
    //Steven 20170125 : 修正關Arm會導致開關Site異常
    iRow=Y;
    if(IsNNMode()==NN_1Row)
    {
        iRow=0;
        if(Y==0)
        {
//            Y=0;                                                                //wei 20230317 修正NN Mode setup關site主頁面顯示問題
            Z=1;
        }
        else
        {
//            Y=0;
            Z=0;
        }
    }

    bHandlerChangeState=true;                                                   //Sam 20230511 : 機台資料變更後須上傳 FTP
    if(bSiteUseEE==false)                                                       //Alick 20160926 add for 第三組工程師用開關SITE,bSiteUseEE==false
    {
        if(bTestSiteUse[Z][Y][X]==false &&
           IniConfig.bDualSiteCloseAbCanFullHotplate==false)
        {
            //ChungHung 20140429 補上
            //ChungHung 20131014 onecycle 後關Site 有可能會HangUp One Row all close then trun On
            if(TestIF_File.iTestMode==_12Site2X6)                               //Steven 20150720 : Fixed for 12 Site Run 8 Site
            {
                flag=true;
            }
            else if(CloseSiteState()==0 ||
                    ((TestIF_File.iTestMode==_8Site2X4 ||
                      TestIF_File.iTestMode==_6Site2X3 ||                       //ChungHung 20140115 add for 2x3_6
                      TestIF_File.iTestMode==_16Site4X4) &&                     //Sam 20190226 : 16Site4X4
                      HotPlateForm.XDivision==6))
            {
                flag=false;
            }
            else
            {
                if(CloseSiteState()!=(X/8+1))
                {
                    flag=true;
                }
            }

            if(flag==false)
            {
                if(CanChangeSite(true)==false)
                {
                    if(LastSet.iTemperature==Tempture_Hot)                      //Steven 20110826
                        ShowErrorMessage("MES1646", 0, MMSystem, false, "DutOnOffMouseUp1");                            //Must finish [Clean out]!!
                    else
                        ShowErrorMessage("MES1645", 0, MMSystem, false, "DutOnOffMouseUp1");                            //Must finish [One Cycle]
                    return;
                }
            }
            else
            {
                if(CanChangeSite(false)==false)
                {
                    if(LastSet.iTemperature==Tempture_Hot)                      //Steven 20110826
                        ShowErrorMessage("MES1646", 0, MMSystem, false, "DutOnOffMouseUp2");                            //Must finish [Clean out]!!
                    else
                        ShowErrorMessage("MES1645", 0, MMSystem, false, "DutOnOffMouseUp2");                            //Must finish [One Cycle]
                    return;
                }
            }
        }
        else
        {
            if(CanChangeSite(false)==false)
            {
                if(LastSet.iTemperature==Tempture_Hot)                          //Steven 20110826
                    ShowErrorMessage("MES1646", 0, MMSystem, false, "DutOnOffMouseUp3");                                //Must finish [Clean out]!!
                else
                    ShowErrorMessage("MES1645", 0, MMSystem, false, "DutOnOffMouseUp3");                                //Must finish [One Cycle]
                return;
            }
        }
        //Steven 20110808 Start
        if((CUSTOMER_CODE==CC_ASE_KaohSiung) &&
           (TestIF_File.iTestMode==_8Site2X4 ||
            TestIF_File.iTestMode==_16Site4X4) &&                               //Sam 20190226 : 16Site4X4
           CosFunction.bEnableOctal_12Kit==true &&                              //wei 20150519 8 Site 顯示 12 Site
           TestIF_File.bOctal_12Kit==true)
        {
            if(TestIF_File.iSiteMap[Y][X]==0)
            {
                if(X==4 && (Y==0 || Y==1))
                {
                    if(TestIF_File.iSiteMap[Y][X-1]==0)
                    {
                        bTestSiteUse[Z][Y][X-1]=false;
                        LastSet.bUseTestSocket[Z][Y][X-1]=false;
                    }
                    else
                    {
                        bTestSiteUse[Z][Y][X-1]=!bTestSiteUse[Z][Y][X-1];
                        LastSet.bUseTestSocket[Z][Y][X-1]=!LastSet.bUseTestSocket[Z][Y][X-1];
                    }
                }
                else
                {
                    bTestSiteUse[Z][Y][X-1]=false;
                    LastSet.bUseTestSocket[Z][Y][X-1]=false;
                }
            }
            else if(TestIF_File.iSiteMap[Y][X]==0 && bTestSiteUseEE[Z][Y][X]==false)
            {
                if(X==4 && (Y==0 || Y==1))
                {
                    if(TestIF_File.iSiteMap[Y][X-1]==0)
                    {
                        bTestSiteUse[Z][Y][X-1]=false;
                        LastSet.bUseTestSocket[Z][Y][X-1]=false;
                    }
                    else
                    {
                        bTestSiteUse[Z][Y][X-1]=!bTestSiteUse[Z][Y][X-1];
                        LastSet.bUseTestSocket[Z][Y][X-1]=!LastSet.bUseTestSocket[Z][Y][X-1];
                    }
                }
                else
                {
                    bTestSiteUse[Z][Y][X-1]=false;
                    LastSet.bUseTestSocket[Z][Y][X-1]=false;
                }
            }
            else
            {
                if(X!=0 && (Y==0 || Y==1))
                {
                    if(TestIF_File.iSiteMap[Y][X-1]==0)
                    {
                        bTestSiteUse[Z][Y][X-1]=false;
                        LastSet.bUseTestSocket[Z][Y][X-1]=false;
                    }
                    else
                    {
                        bTestSiteUse[Z][Y][X-1]=!bTestSiteUse[Z][Y][X-1];
                        LastSet.bUseTestSocket[Z][Y][X-1]=!LastSet.bUseTestSocket[Z][Y][X-1];

                        if(bTestSiteUse[Z][Y][X-1])                             //Steven 20230313 : 自動關之後, 可以強制開site
                        {
                             bLowYieldCloseSite[Z][Y][X-1]=false;
                        }
                    }
                }
            }
        }
        else
        {
            if(IsNNMode()==NN_1Row)
            {
                if(IniConfig.bI35UseThirdSiteControlByEngineer)
                {
                    if(TestIF_File.iSiteMap[Y][X]==0)
                    {
                        bTestSiteUse[Z][0][X]=false;
                        LastSet.bUseTestSocket[Z][0][X]=false;
                    }
                    else if(TestIF_File.iSiteMap[Y][X]!=0 && bTestSiteUseEE[Z][0][X]==false)
                    {
                        bTestSiteUse[Z][0][X]=false;
                        LastSet.bUseTestSocket[Z][0][X]=false;
                    }
                    else
                    {
                        bTestSiteUse[Z][0][X]=!bTestSiteUse[Z][0][X];
                        LastSet.bUseTestSocket[Z][0][X]=!LastSet.bUseTestSocket[Z][0][X];
                        if(bTestSiteUse[Z][0][X])                               //Steven 20230313 : 自動關之後, 可以強制開site
                        {
                             bLowYieldCloseSite[Z][0][X]=false;
                        }
                    }
                }
                else
                {
                    if(TestIF_File.iSiteMap[Y][X]==0)
                    {
                        bTestSiteUse[Z][0][X]=false;
                        LastSet.bUseTestSocket[Z][0][X]=false;
                    }
                    else
                    {
                        bTestSiteUse[Z][0][X]=!bTestSiteUse[Z][0][X];
                        LastSet.bUseTestSocket[Z][0][X]=!LastSet.bUseTestSocket[Z][0][X];
                        if(bTestSiteUse[Z][0][X])                               //Steven 20230313 : 自動關之後, 可以強制開site
                        {
                             bLowYieldCloseSite[Z][0][X]=false;
                        }

                        if(IniConfig.bShowCloseSiteAlarmWhenStart==true)        //Jimmychiu 20230925 : Show Close Sites Alarm When Start
                        {
                            if(bTestSiteUse[Z][0][X]==0)
                            {
                                do
                                {
                                    ret=ShowMyMessagePWD("Please confirm the location of the L/B temperature sensing wire socket", "請確認L/B感溫線插座位置", "", false, false, true);
                                }
                                while(ret==1);
                            }
                        }
                    }
                }
            }
            else
            {
                if(IniConfig.bI35UseThirdSiteControlByEngineer)
                {
                    if(TestIF_File.iSiteMap[Y][X]==0)
                    {
                        bTestSiteUse[Z][Y][X]=false;
                        LastSet.bUseTestSocket[Z][Y][X]=false;
                    }
                    else if(TestIF_File.iSiteMap[Y][X]!=0 && bTestSiteUseEE[Z][Y][X]==false)
                    {
                        bTestSiteUse[Z][Y][X]=false;
                        LastSet.bUseTestSocket[Z][Y][X]=false;
                    }
                    else
                    {
                        bTestSiteUse[Z][Y][X]=!bTestSiteUse[Z][Y][X];
                        LastSet.bUseTestSocket[Z][Y][X]=!LastSet.bUseTestSocket[Z][Y][X];
                        if(bTestSiteUse[Z][Y][X])                               //Steven 20230313 : 自動關之後, 可以強制開site
                        {
                             bLowYieldCloseSite[Z][Y][X]=false;
                        }
                    }
                }
                else
                {
                    if(TestIF_File.iSiteMap[Y][X]==0)
                    {
                        bTestSiteUse[Z][Y][X]=false;
                        LastSet.bUseTestSocket[Z][Y][X]=false;
                    }
                    else
                    {
                        bTestSiteUse[Z][Y][X]=!bTestSiteUse[Z][Y][X];
                        LastSet.bUseTestSocket[Z][Y][X]=!LastSet.bUseTestSocket[Z][Y][X];
                        if(bTestSiteUse[Z][Y][X])                               //Steven 20230313 : 自動關之後, 可以強制開site
                        {
                             bLowYieldCloseSite[Z][Y][X]=false;
                        }

                        if(IniConfig.bShowCloseSiteAlarmWhenStart==true)        //Jimmychiu 20230925 : Show Close Sites Alarm When Start
                        {
                            if(bTestSiteUse[Z][Y][X]==0)
                            {
                                do
                                {
                                    ret=ShowMyMessagePWD("Please confirm the location of the L/B temperature sensing wire socket", "請確認L/B感溫線插座位置", "", false, false, true);
                                }
                                while(ret==1);
                            }
                        }
                    }
                }
            }
        }
        //Steven 20110808 End

        ChangeATCSiteUse();                                                     //Steven 20120523 : ATC
        FormHS->SaveCloseOpenSiteEven(Z, Y, X, bTestSiteUse[Z][Y][X]);          //Ifor 20161219 add 開關Site Even Log 資料格式 開Site:O 關Site:X

//        if(bChangeSiteMAP==false)                                             //kevin 20130506 可以改變sitemap
//        {
//           ShowMyMessage("Must finish [Clean out]", "必須先完成 [Clean out]", "", true);
//           return;
//        }

        ShowTestHeadComp(false);                                                //ChungHung 20130910 alter for SCK can close site by Index
        //AI(ht9045-v899) 20260519: save GTK RunSite after homepage site on/off states are synchronized.
        if(CUSTOMER_CODE==CC_Greatek && fProductionInfo!=NULL)
        {
            fProductionInfo->SaveInfoFileWhenStart();
        }

        if(IniConfig.bF30InShuttleSensorFollow16site)                           //JerryYang 20210426 : 2x4, 2x6 follow 2x8 shuttle sensor位置
        {
            InitShuttleThreadParameter();
        }

        if(IniConfig.bUseAutoSiteMapping)                                       //Steven 20250910 : fixed for Auto site map
        {
            if(IniConfig.bDutOnOffNeedASM)                                      //kevin 20150112 move Steven 20120628 : 開關Site, 強制啟動Auto Site Mapping
            {
            #ifndef ASE_KaohSiung                                               //kevin 20150114 高雄不使用
                if(IniConfig.bI21EnableASM && LastSet.iTester==ON_LINE &&
                   bTestSiteUse[Z][Y][X]==true)                                 //Steven 20120727 : 開Site才要作Auto Site Mapping
                {
                    if(IniConfig.bVTESTFunction==true)                          //jou 20200701 : VTEST for auto site mapping cable mount
                    {
                        if(TestIF_File.bAutoSiteMappingOpenSite)
                            fMain->SetMainRunStartMode(rsmAutoSiteMap);
                    }
                    else
                    {
                        fMain->SetMainRunStartMode(rsmAutoSiteMap);
                    }
                }

                fMain->ReStartAutoSiteMapping(true);
                QueueTaskList[266].CheckTaskChange();                           //Steven 20220708 : 針對Auto Site Map作紀錄
                RecordProcess("Trigger Auto Site Map after site on.");
                SetRunStartMode(rsmAutoSiteMap);
            #else
                for(int i=0; i<MAX_SOCKET_ROW; i++)
                {
                    for(int j=0; j<MAX_SOCKET_COL; j++)
                        iAutoSiteMap[i][j]=0;                                   //kevin 20150114
                }
            #endif
            }
            else
            {
                fMain->ReStartAutoSiteMapping(true);
                QueueTaskList[266].CheckTaskChange();                           //Steven 20220708 : 針對Auto Site Map作紀錄
            }
        }

        if(IniConfig.bA09_ByArmCloseSite)
        {
            fTestCategory->SetTestCateCellAS(Z, Y, X, "-1", clWhite);           //ChungHung 20140611 fix 顯示對應錯誤 與 bin256 衝突
            fTestCategory->ShowTestCategory(Z);
        }
        fAutomation->AmkorSendMessage(Z);                                       //Steven 20120330 : ATK Site Map Monitorning
        myLog.Save_SiteStatusLog();                                             //JerryYang 20160617 記錄開關Site的狀態
        AnsiString szDir=GetRecipeFileName("Temperature.Data");
        AnsiString asData1="", asData2="";

        if(Temperature.bATC70Active==true)
        {
            if(TestIF_File.iShuttleMode==0)                                     //Dual Shuttle
            {
                switch(TestIF_File.iTestMode)
                {
                    case DualSite:                                              //1x2    //Ifor 20160314 修正ATC 7.0 Dual Shuttle 關Site 異常
                        WriteIniData(szDir, "ATC", "ATC7CH1Enabled", bTestSiteUse[0][0][0]);
                        WriteIniData(szDir, "ATC", "ATC7CH2Enabled", bTestSiteUse[0][0][1]);
                        WriteIniData(szDir, "ATC", "ATC7CH3Enabled", bTestSiteUse[1][0][0]);
                        WriteIniData(szDir, "ATC", "ATC7CH4Enabled", bTestSiteUse[1][0][1]);
                    break;
                }
            }
            else if(TestIF_File.iShuttleMode==1)                                //Single Suttle
            {
                switch(TestIF_File.iTestMode)
                {
                    case DualSite:                                              //1x2
                        if(TestIF_File.iShuttle_Sel==0)
                        {
                            WriteIniData(szDir, "ATC", "ATC7CH1Enabled", bTestSiteUse[0][0][0]);
                            WriteIniData(szDir, "ATC", "ATC7CH2Enabled", bTestSiteUse[0][0][1]);
                            WriteIniData(szDir, "ATC", "ATC7CH3Enabled", false);
                            WriteIniData(szDir, "ATC", "ATC7CH4Enabled", false);
                        }
                        else if(TestIF_File.iShuttle_Sel==1)
                        {
                            WriteIniData(szDir, "ATC", "ATC7CH1Enabled", false);
                            WriteIniData(szDir, "ATC", "ATC7CH2Enabled", false);
                            WriteIniData(szDir, "ATC", "ATC7CH3Enabled", bTestSiteUse[1][0][0]);
                            WriteIniData(szDir, "ATC", "ATC7CH4Enabled", bTestSiteUse[1][0][1]);
                        }
                        break;
                }
            }
            Temperature.bATC7ChannelEnabled[0] = ReadIniData(szDir, "ATC", "ATC7CH1Enabled", false);
            Temperature.bATC7ChannelEnabled[1] = ReadIniData(szDir, "ATC", "ATC7CH2Enabled", false);
            Temperature.bATC7ChannelEnabled[2] = ReadIniData(szDir, "ATC", "ATC7CH3Enabled", false);
            Temperature.bATC7ChannelEnabled[3] = ReadIniData(szDir, "ATC", "ATC7CH4Enabled", false);

            asData1.sprintf("%d,%d", Temperature.bATC7ChannelEnabled[0], Temperature.bATC7ChannelEnabled[1]);
            asData2.sprintf("%d,%d", Temperature.bATC7ChannelEnabled[2], Temperature.bATC7ChannelEnabled[3]);
            ATCInterfaceForm->SendCommToATC7(ATC_CH_ENABLED, asData1, asData2);
        }
    }
    else                                                                        //Alick 20160926 add for 第三組工程師用開關SITE,bSiteUseEE==true
    {
        if(bTestSiteUseEE[Z][iRow][X]==false &&
           IniConfig.bDualSiteCloseAbCanFullHotplate==false)
        {
            //ChungHung 20140429 補上
            //ChungHung 20131014 onecycle 後關Site 有可能會HangUp One Row all close then trun On
            if(TestIF_File.iTestMode==_12Site2X6)                               //Steven 20150720 : Fixed for 12 Site Run 8 Site
            {
                flag=true;
            }
            else if(CloseSiteState()==0 ||
                    ((TestIF_File.iTestMode==_8Site2X4 ||
                      TestIF_File.iTestMode==_6Site2X3 ||                       //ChungHung 20140115 add for 2x3_6
                      TestIF_File.iTestMode==_16Site4X4) &&                     //Sam 20190226 : 16Site4X4
                     HotPlateForm.XDivision==6))
            {
                flag=false;
            }
            else
            {
                if(CloseSiteState()!=(X/8+1))
                {
                    flag=true;
                }
            }

            if(flag==false)
            {
                if(CanChangeSite(true)==false)
                {
                    if(LastSet.iTemperature==Tempture_Hot)                      //Steven 20110826
                        ShowErrorMessage("MES1646", 0, MMSystem, false, "DutOnOffMouseUp4");                            //Must finish [Clean out]!!
                    else
                        ShowErrorMessage("MES1645", 0, MMSystem, false, "DutOnOffMouseUp4");                            //Must finish [One Cycle]
                    return;
                }
            }
            else
            {
                if(CanChangeSite(false)==false)
                {
                    if(LastSet.iTemperature==Tempture_Hot)                      //Steven 20110826
                        ShowErrorMessage("MES1646", 0, MMSystem, false, "DutOnOffMouseUp5");                            //Must finish [Clean out]!!
                    else
                        ShowErrorMessage("MES1645", 0, MMSystem, false, "DutOnOffMouseUp5");                            //Must finish [One Cycle]
                    return;
                }
            }
        }
        else
        {
            if(CanChangeSite(false)==false)
            {
                if(LastSet.iTemperature==Tempture_Hot)                          //Steven 20110826
                    ShowErrorMessage("MES1646", 0, MMSystem, false, "DutOnOffMouseUp6");                                //Must finish [Clean out]!!
                else
                    ShowErrorMessage("MES1645", 0, MMSystem, false, "DutOnOffMouseUp6");                                //Must finish [One Cycle]
                return;
            }
        }
        //Steven 20110808 Start
        if((CUSTOMER_CODE==CC_ASE_KaohSiung) &&
           (TestIF_File.iTestMode==_8Site2X4 ||                                 //wei 20150519 8 Site 顯示 12 Site
            TestIF_File.iTestMode==_16Site4X4) &&                               //Sam 20190226 : 16Site4X4
           CosFunction.bEnableOctal_12Kit==true &&
           TestIF_File.bOctal_12Kit==true)
        {
            if(TestIF_File.iSiteMap[Y][X]==0)
            {
                if(X==4 && (Y==0 || Y==1))
                {
                    if(TestIF_File.iSiteMap[Y][X-1]==0)
                    {
                        bTestSiteUseEE[Z][iRow][X-1]=false;
                        LastSet.bUseTestSocketEE[Z][iRow][X-1]=false;
                    }
                    else
                    {
                        bTestSiteUseEE[Z][iRow][X-1]=!bTestSiteUseEE[Z][iRow][X-1];
                        LastSet.bUseTestSocketEE[Z][iRow][X-1]=!LastSet.bUseTestSocketEE[Z][iRow][X-1];

                        if(bTestSiteUse[Z][iRow][X-1])                          //Steven 20230313 : 自動關之後, 可以強制開site
                        {
                             bLowYieldCloseSite[Z][iRow][X-1]=false;
                        }

                        if(IniConfig.bA09_ByArmCloseSite)
                        {
                            if(Z==1)
                                bRefreshEng1=true;
                            else
                                bRefreshEng=true;
                        }
                        else
                        {
                            bRefreshEng=true;
                        }
                    }
                }
                else
                {
                    bTestSiteUseEE[Z][Y][X-1]=false;
                    LastSet.bUseTestSocketEE[Z][Y][X-1]=false;
                }
            }
            else
            {
                if(X!=0 && (Y==0 || Y==1))
                {
                    if(TestIF_File.iSiteMap[Y][X-1]==0)
                    {
                        bTestSiteUseEE[Z][iRow][X-1]=false;
                        LastSet.bUseTestSocketEE[Z][iRow][X-1]=false;
                    }
                    else
                    {
                        bTestSiteUseEE[Z][iRow][X-1]=!bTestSiteUseEE[Z][iRow][X-1];
                        LastSet.bUseTestSocketEE[Z][iRow][X-1]=!LastSet.bUseTestSocketEE[Z][iRow][X-1];

                        if(bTestSiteUse[Z][iRow][X-1])                          //Steven 20230313 : 自動關之後, 可以強制開site
                        {
                             bLowYieldCloseSite[Z][iRow][X-1]=false;
                        }

                        if(IniConfig.bA09_ByArmCloseSite)
                        {
                            if(Z==1)
                                bRefreshEng1=true;
                            else
                                bRefreshEng=true;
                        }
                        else
                        {
                            bRefreshEng=true;
                        }
                    }
                }
            }
        }
        else
        {
            if(TestIF_File.iSiteMap[Y][X]==0)
            {
                bTestSiteUseEE[Z][iRow][X]=false;
                LastSet.bUseTestSocketEE[Z][iRow][X]=false;
            }
            else
            {
                bTestSiteUseEE[Z][iRow][X]=!bTestSiteUseEE[Z][iRow][X];
                LastSet.bUseTestSocketEE[Z][Y][X]=!LastSet.bUseTestSocketEE[Z][iRow][X];

                if(bTestSiteUse[Z][iRow][X])                                    //Steven 20230313 : 自動關之後, 可以強制開site
                {
                     bLowYieldCloseSite[Z][iRow][X]=false;
                }

                if(IniConfig.bA09_ByArmCloseSite ||
                   IsNNMode()==NN_1Row)                                         //Steven 20241220 : fixed for I35
                {
                    if(Z==1)
                        bRefreshEng1=true;
                    else
                        bRefreshEng=true;
                }
                else
                {
                    bRefreshEng=true;
                }
            }
        }
        //Steven 20110808 End

        ShowTestHeadComp(false);                                                //ChungHung 20130910 alter for SCK can close site by Index

        if(IniConfig.bUseAutoSiteMapping)                                       //Steven 20250910 : fixed for Auto site map
        {
            if(IniConfig.bDutOnOffNeedASM)                                      //kevin 20150112 move Steven 20120628 : 開關Site, 強制啟動Auto Site Mapping
            {
            #ifndef ASE_KaohSiung                                               //kevin 20150114 高雄不使用
                if(IniConfig.bI21EnableASM && LastSet.iTester==ON_LINE &&
                   bTestSiteUseEE[Z][iRow][X]==true)                            //Steven 20120727 : 開Site才要作Auto Site Mapping
                {
                    if(IniConfig.bVTESTFunction==true)                          //jou 20200701 : VTEST for auto site mapping cable mount
                    {
                        if(TestIF_File.bAutoSiteMappingOpenSite)
                            fMain->SetMainRunStartMode(rsmAutoSiteMap);
                    }
                    else
                    {
                        fMain->SetMainRunStartMode(rsmAutoSiteMap);
                    }

                    if(LastSet.iTemperature==Tempture_Hot ||
                       LastSet.iTemperature==Tempture_AmbientHot)
                    {
                        if(bAutoSiteMapHasPickHP)
                            iResetSiteMappingStep=1;
                    }
                    fMain->ReStartAutoSiteMapping(true);
                    QueueTaskList[266].CheckTaskChange();                       //Steven 20220708 : 針對Auto Site Map作紀錄
                    RecordProcess("Trigger Auto Site Map after site on.");
                    SetRunStartMode(rsmAutoSiteMap);
                }
            #else
                for(int i=0; i<MAX_SOCKET_ROW; i++)
                {
                    for(int j=0; j<MAX_SOCKET_COL; j++)
                        iAutoSiteMap[i][j]=0;                                   //kevin 20150114
                }
            #endif
            }
            else
            {
                fMain->ReStartAutoSiteMapping(true);
                QueueTaskList[266].CheckTaskChange();                           //Steven 20220708 : 針對Auto Site Map作紀錄
            }
        }

        if(IniConfig.bA09_ByArmCloseSite)
        {
            fTestCategory->SetTestCateCellAS(Z, Y, X, "-1", clWhite);           //ChungHung 20140611 fix 顯示對應錯誤 與 bin256 衝突
            fTestCategory->ShowTestCategory(Z);
        }
        fAutomation->AmkorSendMessage(Z);                                       //Steven 20120330 : ATK Site Map Monitorning
        myLog.Save_SiteStatusLog();                                             //JerryYang 20160617 記錄開關Site的狀態
    }

    if(IniConfig.bVTESTFunction==true &&                                        //Jou 20220913 : 上海無錫張冬冬要求開關site不要截斷資料
       RunInfo.bLotStart)                                                       //marvin 20200424 (Kirin) Added always record report by time.
    {
        fMesSystem->DoRecordReportByTime();
    }

    bHandlerChangeState=true;                                                   //Sam 20230511 : 機台資料變更後須上傳 FTP
    ChangeStateUploadServer();
}
