//---------------------------------------------------------------------------
void __fastcall TfMain::AutoCleanStringGridDrawCell(TObject *Sender,
      int ACol, int ARow, TRect &Rect, TGridDrawState State)
{
    pCanvas->Handle=PtrDC;
    pCanvas->Font->Color=clBlack;
    pCanvas->Brush->Color=clBtnFace;

    if(ARow==0)
    {
        MyDrawText(pCanvas, Rect, "Clean Count", 0, AutoCleanStringGrid->DefaultColWidth*8+8,
                                                 0, AutoCleanStringGrid->DefaultRowHeight);
    }
    else if(ARow==TestIF_File.iAutoClean_YDivision+1)                           //ChungHung 20130402 alter
    {
        MyDrawText(pCanvas, Rect, "Pad Set", 0, AutoCleanStringGrid->DefaultColWidth*8+8,
                   AutoCleanStringGrid->DefaultRowHeight*ARow+ARow, AutoCleanStringGrid->DefaultRowHeight*ARow+ARow+AutoCleanStringGrid->DefaultRowHeight);
    }
}
//---------------------------------------------------------------------------
void __fastcall TfMain::AutoCleanStringGridDblClick(TObject *Sender)
{
    int i, j, ret;
    AnsiString asString;

    if(AutoCleanStringGrid->Row<TestIF_File.iAutoClean_YDivision+2)             //ChungHung 20130402 alter
        return;

    if(AutoCleanStringGrid->Cells[AutoCleanStringGrid->Col][AutoCleanStringGrid->Row]!="")
    {
        ret=ShowMyMessageBox_YES_NO("Reset Clean Pad Count?", "是否重新設定 Clean Pad 記數次數？");
        if(ret==2)
            return;

        asString=AutoCleanStringGrid->Cells[AutoCleanStringGrid->Col][AutoCleanStringGrid->Row];
        for(i=0; i<TestIF_File.iAutoClean_XDivision; i++)
        {
            for(j=0; j<TestIF_File.iAutoClean_YDivision; j++)
            {
                //Alick 20170215 (Steven) add for 2x3 autoclean by hotplate
                //==>
                if(TestIF_File.iTestMode==_6Site2X3 && IniConfig.bE43AutoCleanUseHotplate)
                {
                    if(AutoCleanStringGrid->Cells[i][j+TestIF_File.iAutoClean_YDivision+2]==asString && i!=0)           //ChungHung 20130402 alter
                    {
                        AutoCleanStringGrid->Cells[i][j+1]="R";
                    }
                }
                else
                //<==
                //Alick 20170215 (Steven) add for 2x3 autoclean by hotplate
                {
                    if(AutoCleanStringGrid->Cells[i][j+TestIF_File.iAutoClean_YDivision+2]==asString)                   //ChungHung 20130402 alter
                    {
                        AutoCleanStringGrid->Cells[i][j+1]="R";
                    }
                }
            }
        }
        ReadWriteAutoCleanCount(false, true);                                   //Steven 20180524 : Fixed for clean count
    }
}
