//---------------------------------------------------------------------------
double TfMain::EpChangeRecord(double oldData, double NewData)
{
    AnsiString sBuffer="", sFileName, str;
    GetTimeInfo();
    str.sprintf("%04d-%02d-%02d %02d:%02d:%02d.%d -->", SystemYear, SystemMonth, SystemDate, SystemHour, SystemMin, SystemSec, SystemMSec);
    sBuffer.sprintf( "%s      LastData: %f,Now Data %f",str,oldData,NewData);
    oldData =NewData;
    fMain->EPMemo->Lines->Add( sBuffer);

    sFileName.sprintf("%s\\%04d%02d%02d%02d%02d%02d_EP.logs", asEPLogPath, SystemYear, SystemMonth, SystemYear, SystemMonth, SystemDate, SystemHour, SystemMin, SystemSec);
    fMain->EPMemo->Lines->SaveToFile(sFileName);
    return (double)oldData;
}
