void __fastcall TfMain::SetSocketData()
{
    bool ret=true;
    char str[256];
    strncpy(str, HGpib2Handler->GpibData, sizeof(str));
    ret=CanChangeToSocket();
    if(ret==true)
    {
        ret=ChangeToSocket(str);
    }
    FILE *P;
    char filename[256];
    char t[256];
    sprintf(filename, "d:\\HT9045\\system\\set_socket.txt");
    P=fopen(filename, "w");
    if(P!=NULL)
    {
        if(ret)
            strncpy(t, "SETTINGOK", sizeof(t));
        else
            strncpy(t, "SETTINGNG", sizeof(t));
        fputs(t, P);
        fclose(P);
    }
}
//---------------------------------------------------------------------------
bool __fastcall TfMain::CanChangeToSocket()
{
    if(SystemStart)
        return false;
    if(CanChangeSite()==false)
        return false;
    return true;
}
//---------------------------------------------------------------------------
bool __fastcall TfMain::ChangeToSocket(char *str)
{
    char t[256]={"00000000"};

    if(TestIF_File.iTestMode==_8Site2X4)                                        // 8Site
    {
        if(str[0]=='0' && str[1]=='0' && str[2]=='0' && str[3]=='0' &&
           str[4]=='0' && str[5]=='0' && str[6]=='0' && str[7]=='0' )
            return false;
        //ChungHung 20130910 alter for SCK can close site by Index
        Prod.fInArmSuckUse[0][0][0]=str[0]-'0';
        Prod.fInArmSuckUse[0][0][1]=str[1]-'0';
        Prod.fInArmSuckUse[0][0][2]=str[2]-'0';
        Prod.fInArmSuckUse[0][0][3]=str[3]-'0';

        Prod.fInArmSuckUse[0][1][0]=str[4]-'0';
        Prod.fInArmSuckUse[0][1][1]=str[5]-'0';
        Prod.fInArmSuckUse[0][1][2]=str[6]-'0';
        Prod.fInArmSuckUse[0][1][3]=str[7]-'0';

        Prod.fInArmSuckUse[1][0][0]=str[0]-'0';
        Prod.fInArmSuckUse[1][0][1]=str[1]-'0';
        Prod.fInArmSuckUse[1][0][2]=str[2]-'0';
        Prod.fInArmSuckUse[1][0][3]=str[3]-'0';

        Prod.fInArmSuckUse[1][1][0]=str[4]-'0';
        Prod.fInArmSuckUse[1][1][1]=str[5]-'0';
        Prod.fInArmSuckUse[1][1][2]=str[6]-'0';
        Prod.fInArmSuckUse[1][1][3]=str[7]-'0';
    }
    else if(TestIF_File.iTestMode==_16Site2X8)
    {
        if(str[0 ]=='0' && str[1 ]=='0' && str[2 ]=='0' && str[3 ]=='0' &&
           str[4 ]=='0' && str[5 ]=='0' && str[6 ]=='0' && str[7 ]=='0' &&
           str[8 ]=='0' && str[9 ]=='0' && str[10]=='0' && str[11]=='0' &&
           str[12]=='0' && str[13]=='0' && str[14]=='0' && str[15]=='0' )
            return false;

        //ChungHung 20130910 alter for SCK can close site by Index
        t[0]='0'+Prod.fInArmSuckUse[0][0][0];
        t[1]='0'+Prod.fInArmSuckUse[0][0][1];
        t[2]='0'+Prod.fInArmSuckUse[0][0][2];
        t[3]='0'+Prod.fInArmSuckUse[0][0][3];
        t[4]='0'+Prod.fInArmSuckUse[0][1][0];
        t[5]='0'+Prod.fInArmSuckUse[0][1][1];
        t[6]='0'+Prod.fInArmSuckUse[0][1][2];
        t[7]='0'+Prod.fInArmSuckUse[0][1][3];

        t[8]='0'+Prod.fInArmSuckUse_9To16[0][0][0];
        t[9]='0'+Prod.fInArmSuckUse_9To16[0][0][1];
        t[10]='0'+Prod.fInArmSuckUse_9To16[0][0][2];
        t[11]='0'+Prod.fInArmSuckUse_9To16[0][0][3];
        t[12]='0'+Prod.fInArmSuckUse_9To16[0][1][0];
        t[13]='0'+Prod.fInArmSuckUse_9To16[0][1][1];
        t[14]='0'+Prod.fInArmSuckUse_9To16[0][1][2];
        t[15]='0'+Prod.fInArmSuckUse_9To16[0][1][3];
    }

    MainFormChange();
    SetTechDataToProd();
    return true;
}
