// 2013.12.03 , Joye , KYEC FTP ---------------------------------------------->>20140103 wei
bool TfMain::NETDownloadDataCheck()
{
    AnsiString Str="", Str2;
    bool bContactHasErr=false;
    if(CUSTOMER_CODE==CC_SCC ||
       (CosFunction.bHiSiliconFunction==true &&
        CUSTOMER_CODE==CC_AMD_M))                                               //Ifor 20200727 :add TF-AMD RMS Data Check
    {
        if(IniConfig.bEnableFTP==false && IniConfig.bEnableRms==false)
            return true;

        if(bFTPDownloadSetupFile==false && IniConfig.bEnableFTP==true)
        {
            ShowMyMessage("Need Download FTP Setup File!!");
            return false;
        }
    }
    else
    {
        if(CUSTOMER_CODE!=CC_ASE_M)
        {
            if(IniConfig.bEnableFTP==false)
                return true;

            if(IniConfig.bVTESTFunction==true &&
               fMesSystem->CheckVTENGmode(fLotInfo->edtSysLotID->Text)==true)
                return true;

            if(bFTPDownloadSetupFile==false)
            {
                ShowMyMessage("Need Download FTP Setup File!!");
                return false;
            }
        }
        else
        {
            if(IniConfig.bN13_EnableARMSFunction==false)    //Ifor 20250303 Fix ASEM ARM異常報警
                return true;
        }
    }

    if(SYS_SetupFile!=DownloadWorkFile_NET)
    {
        ShowMyMessage("Work File Check Error!!");
        return false;
    }

    if(LastSet.iTemperature!=LastSetTemperature_NET)
    {
        ShowMyMessage("Temperature Mode Check Error!!");
        return false;
    }

    if(Temperature.fWorkTemperBase!=Temperature_NET.fWorkTemperBase ||
        Temperature.fSoakTime!=Temperature_NET.fSoakTime)
    {
        ShowMyMessage("Temperature Default or Soak Time Check Error!!");
        return false;
    }

    for(int j=0; j<8; j++)                                                      //ChungHung 20141002 add for KYEC AutoRetest 3->5   //Ifor 20170417 (wei) add MRT Bin Check 5 =>8
    {
        for(int i=0; i<15; i++)                                                 //QQQ
        {
            if(BinSelect[j].iCatDataT3Pos[i]    !=BinSelect_NET[j].iCatDataT3Pos[i] ||
               BinSelect[j].iDBContact[i]       !=BinSelect_NET[j].iDBContact[i] ||
               BinSelect[j].iStackDefFailCate[i]!=BinSelect_NET[j].iStackDefFailCate[i] ||
               BinSelect[j].bFailure[i]         !=BinSelect_NET[j].bFailure[i])
            {
                ShowMyMessage( "Binning Data Check Error!!" );
                return false;
            }
        }
    }

    if(HotPlateForm_File.XPitch      !=HotPlateForm_NET.XPitch ||
       HotPlateForm_File.YPitch      !=HotPlateForm_NET.YPitch ||
       HotPlateForm_File.XStart      !=HotPlateForm_NET.XStart ||
       HotPlateForm_File.YStart      !=HotPlateForm_NET.YStart ||
       HotPlateForm_File.XDivision   !=HotPlateForm_NET.XDivision ||
       HotPlateForm_File.YDivision   !=HotPlateForm_NET.YDivision ||
       HotPlateForm_File.ZDepth      !=HotPlateForm_NET.ZDepth ||
       HotPlateForm_File.iPlateSelect!=HotPlateForm_NET.iPlateSelect)
    {
        ShowMyMessage("Hot Plate Form Data Check Error!!");
        return false;
    }

    if(TrayForm.LodareType!=TrayForm_NET.LodareType)
    {
        ShowMyMessage("Tray Form Data Check Error!!");
        return false;
    }

    TRAY_TYPE_PARA tmpTrayPara[eTrayCount];
    tmpTrayPara[eAuto1]=TrayForm.Auto[eAuto1];
    tmpTrayPara[eAuto2]=TrayForm.Auto[eAuto2];
    tmpTrayPara[eAuto3]=TrayForm.Auto[eAuto3];
    tmpTrayPara[eAuto4]=TrayForm.Auto[eAuto4];
    tmpTrayPara[eAuto5]=TrayForm.Auto[eAuto5];
    tmpTrayPara[eAuto6]=TrayForm.Auto[eAuto6];
    tmpTrayPara[eFix1 ]=TrayForm.Auto[eFix1 ];
    tmpTrayPara[eFix2 ]=TrayForm.Auto[eFix2 ];
    tmpTrayPara[eFix3 ]=TrayForm.Auto[eFix3 ];
    tmpTrayPara[eFix4 ]=TrayForm.Auto[eFix4 ];
    tmpTrayPara[eFix5 ]=TrayForm.Auto[eFix5 ];
    tmpTrayPara[eFix6 ]=TrayForm.Auto[eFix6 ];

    TRAY_TYPE_PARA TrayPara_NET[eTrayCount];
    TrayPara_NET[eAuto1]=TrayForm_NET.Auto[eAuto1];
    TrayPara_NET[eAuto2]=TrayForm_NET.Auto[eAuto2];
    TrayPara_NET[eAuto3]=TrayForm_NET.Auto[eAuto3];
    TrayPara_NET[eAuto4]=TrayForm_NET.Auto[eAuto4];
    TrayPara_NET[eAuto5]=TrayForm_NET.Auto[eAuto5];
    TrayPara_NET[eAuto6]=TrayForm_NET.Auto[eAuto6];
    TrayPara_NET[eFix1 ]=TrayForm_NET.Auto[eFix1 ];
    TrayPara_NET[eFix2 ]=TrayForm_NET.Auto[eFix2 ];
    TrayPara_NET[eFix3 ]=TrayForm_NET.Auto[eFix3 ];
    TrayPara_NET[eFix4 ]=TrayForm_NET.Auto[eFix4 ];
    TrayPara_NET[eFix5 ]=TrayForm_NET.Auto[eFix5 ];
    TrayPara_NET[eFix6 ]=TrayForm_NET.Auto[eFix6 ];

    for(int i=0; i<iFixRight; i++)
    {
        if(Prod.iTrayType[i]!=tNotUse &&
           Prod.iTrayType[i]!=tTrayBox)
        {
            if(tmpTrayPara[i].XPitch   !=TrayPara_NET[i].XPitch ||
               tmpTrayPara[i].YPitch   !=TrayPara_NET[i].YPitch ||
               tmpTrayPara[i].XStart   !=TrayPara_NET[i].XStart ||
               tmpTrayPara[i].YStart   !=TrayPara_NET[i].YStart ||
               tmpTrayPara[i].XDivision!=TrayPara_NET[i].XDivision ||
               tmpTrayPara[i].YDivision!=TrayPara_NET[i].YDivision )
            {
                ShowMyMessage("Tray Form Data Check Error!!");
                return false;
            }
        }
    }

    for(int i=0; i<4; i++)
    {
        for(int j=0; j<8; j++)
        {
            if(TestIF_File.iSiteMap[i][j]!=TestIF_NET.iSiteMap[i][j])
            {
                ShowMyMessage("Site Mapping Data Check Error!!");
                return false;
            }
        }
    }

    //Ifor 20170418 (wei) add MRT Mode Check
    if(TestIF_File.bEnableMRTMode!=TestIF_NET.bEnableMRTMode)
    {
        ShowMyMessage("MRT Mode Check Error!!");
        return false;
    }

    if(TestIF_File.iTestMode!=TestIF_NET.iTestMode)
    {
        ShowMyMessage("Test Site Mode Check Error!!");
        return false;
    }

    if(TestIF_File.iTestType!=TestIF_NET.iTestType)
    {
        ShowMyMessage("Test Interface Mode Check Error!!");
        return false;
    }

    if(TestIF_File.iGpibMode!=TestIF_NET.iGpibMode)
    {
        ShowMyMessage("GPIB Type Check Error!!");
        return false;
    }

    if(TestIF_File.iGpibAddress!=TestIF_NET.iGpibAddress)
    {
        ShowMyMessage("GPIB Address Check Error!!");
        return false;
    }

    if(TestIF_File.iRs232Mode!=TestIF_NET.iRs232Mode)
    {
        ShowMyMessage("RS-232 Type Check Error!!");
        return false;
    }

    //Ifor 20181023 add SCC要求FTP資料卡控加入Contact相關資料
    //==>
    if(CUSTOMER_CODE==CC_CYUEAN ||                                              //Steven 20231220 : Add CC_CYUEAN for check contact data
       CUSTOMER_CODE==CC_SCC    ||
       CUSTOMER_CODE==CC_JCET   ||
       CUSTOMER_CODE==CC_SJ_Semiconductor ||                                    //Steven 20220623 : Add SJSM
       CUSTOMER_CODE==CC_SJ_Semiconductor_OS ||
       CUSTOMER_CODE==CC_XINITECH            ||
       (CosFunction.bHiSiliconFunction==true && CUSTOMER_CODE==CC_AMD_M))       //Steven 20190111 : JCET add contact資料卡控
    {
        //Steven 20190904 : 將Alarm分開表示
        if(DeviceForm_File.VacuumMode!=DeviceForm_NET.VacuumMode)
        {
            bContactHasErr=true;
            Str2.sprintf("VacuumMode %d : %d", DeviceForm_File.VacuumMode, DeviceForm_NET.VacuumMode);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.ContactMode!=DeviceForm_NET.ContactMode)
        {
            bContactHasErr=true;
            Str2.sprintf("ContactMode %d : %d", DeviceForm_File.ContactMode, DeviceForm_NET.ContactMode);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.DummyMode!=DeviceForm_NET.DummyMode)
        {
            bContactHasErr=true;
            Str2.sprintf("ContactMode %d : %d", DeviceForm_File.DummyMode, DeviceForm_NET.DummyMode);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.DropWait!=DeviceForm_NET.DropWait)
        {
            bContactHasErr=true;
            Str2.sprintf("DropWait %d : %d", DeviceForm_File.DropWait, DeviceForm_NET.DropWait);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.DropSpeed!=DeviceForm_NET.DropSpeed)
        {
            bContactHasErr=true;
            Str2.sprintf("DropSpeed %d : %d", DeviceForm_File.DropSpeed, DeviceForm_NET.DropSpeed);
            Str=Str+", "+Str2;
        }
        //Ifor 20210112
        //==>
        if(IniConfig.bD58UseArm1PickPlaceArm2Test==true && TestIF_File.bArm1PickPlaceArm2Test==true)                    //Steven 20211124 : 功能沒開的時候不比對
        {
            if(DeviceForm_File.UpWait!=DeviceForm_NET.UpWait)
            {
                bContactHasErr=true;
                Str2.sprintf("UpWait %d : %d", DeviceForm_File.UpWait, DeviceForm_NET.UpWait);
                Str=Str+", "+Str2;
            }

            if(DeviceForm_File.UpSpeed!=DeviceForm_NET.UpSpeed)
            {
                bContactHasErr=true;
                Str2.sprintf("UpSpeed %d : %d", DeviceForm_File.UpSpeed, DeviceForm_NET.UpSpeed);
                Str=Str+", "+Str2;
            }
        }
        //<==
        //Ifor 20210112
        if(DeviceForm_File.bShuttleWaitingOutSiteChamber!=DeviceForm_NET.bShuttleWaitingOutSiteChamber)
        {
            bContactHasErr=true;
            Str2.sprintf("bShuttleWaitingOutSiteChamber %d : %d", DeviceForm_File.bShuttleWaitingOutSiteChamber, DeviceForm_NET.bShuttleWaitingOutSiteChamber);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.bSuckShuttleDeviceAfterTested!=DeviceForm_NET.bSuckShuttleDeviceAfterTested)
        {
            bContactHasErr=true;
            Str2.sprintf("bSuckShuttleDeviceAfterTested %d : %d", DeviceForm_File.bSuckShuttleDeviceAfterTested, DeviceForm_NET.bSuckShuttleDeviceAfterTested);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.bIndexUpSpeed!=DeviceForm_NET.bIndexUpSpeed)
        {
            bContactHasErr=true;
            Str2.sprintf("bIndexUpSpeed %d : %d", DeviceForm_File.bIndexUpSpeed, DeviceForm_NET.bIndexUpSpeed);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.bPurgeBeforePickShuttle!=DeviceForm_NET.bPurgeBeforePickShuttle)
        {
            bContactHasErr=true;
            Str2.sprintf("bPurgeBeforePickShuttle %d : %d", DeviceForm_File.bPurgeBeforePickShuttle, DeviceForm_NET.bPurgeBeforePickShuttle);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.iPurgeBeforePickShuttleTime!=DeviceForm_NET.iPurgeBeforePickShuttleTime)
        {
            bContactHasErr=true;
            Str2.sprintf("iPurgeBeforePickShuttleTime %d : %d", DeviceForm_File.iPurgeBeforePickShuttleTime, DeviceForm_NET.iPurgeBeforePickShuttleTime);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.iPurgeBeforePickShuttleInterval!=DeviceForm_NET.iPurgeBeforePickShuttleInterval)
        {
            bContactHasErr=true;
            Str2.sprintf("iPurgeBeforePickShuttleInterval %d : %d", DeviceForm_File.iPurgeBeforePickShuttleInterval, DeviceForm_NET.iPurgeBeforePickShuttleInterval);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.iPurgeBdforePickShuttleOffSet!=DeviceForm_NET.iPurgeBdforePickShuttleOffSet)
        {
            bContactHasErr=true;
            Str2.sprintf("iPurgeBdforePickShuttleOffSet %d : %d", DeviceForm_File.iPurgeBdforePickShuttleOffSet, DeviceForm_NET.iPurgeBdforePickShuttleOffSet);
            Str=Str+", "+Str2;
        }

        if(DeviceForm_File.bPickShuttleDeviceTogether!=DeviceForm_NET.bPickShuttleDeviceTogether)
        {
            bContactHasErr=true;
            Str2.sprintf("bPickShuttleDeviceTogether %d : %d", DeviceForm_File.bPickShuttleDeviceTogether, DeviceForm_NET.bPickShuttleDeviceTogether);
            Str=Str+", "+Str2;
        }

        if(bContactHasErr)
        {
            ShowMyMessage("Contact parameter Data Check Error!!", Str, Str);
            return false;
        }

        if(DeviceForm_File.iHeadDeviceCT                    !=DeviceForm_NET.iHeadDeviceCT                      ||
           DeviceForm_File.dKitDiameter                     !=DeviceForm_NET.dKitDiameter                       ||
           DeviceForm_File.iPinCT                           !=DeviceForm_NET.iPinCT                             ||
           DeviceForm_File.ForcePerPinN                     !=DeviceForm_NET.ForcePerPinN                       ||
           DeviceForm_File.ForcePerPinG                     !=DeviceForm_NET.ForcePerPinG                       ||
           DeviceForm_File.XDimension                       !=DeviceForm_NET.XDimension                         ||
           DeviceForm_File.YDimension                       !=DeviceForm_NET.YDimension                         )
        {
            ShowMyMessage("Contact Force Data Check Error!!");
            return false;
        }
    }
    //<==
    //Ifor 20181023 add SCC要求FTP資料卡控加入Contact相關資料

    if(CUSTOMER_CODE==CC_JCET ||                                                //Steven 20190111 : JCET add yield資料卡控
       CUSTOMER_CODE==CC_SJ_Semiconductor ||                                    //Steven 20220623 : Add SJSM
       CUSTOMER_CODE==CC_SJ_Semiconductor_OS ||
       CUSTOMER_CODE==CC_XINITECH)
    {
        if(TestIF_File.bLowYieldAlarmByBin              !=TestIF_NET.bLowYieldAlarmByBin                ||
           TestIF_File.dLowYieldLimit                   !=TestIF_NET.dLowYieldLimit                     ||
           TestIF_File.iLowYieldCount                   !=TestIF_NET.iLowYieldCount                     ||
           TestIF_File.dFailAlarmSiteYield              !=TestIF_NET.dFailAlarmSiteYield                ||
           TestIF_File.iFailAlarmSiteYieldDifferentCount!=TestIF_NET.iFailAlarmSiteYieldDifferentCount  ||
           TestIF_File.dFailAlarmSiteYieldCmp           !=TestIF_NET.dFailAlarmSiteYieldCmp             ||
           TestIF_File.iFailAlarmSiteYieldCmpCount      !=TestIF_NET.iFailAlarmSiteYieldCmpCount        ||
           TestIF_File.bFailAlarmLowYieldByTotal        !=TestIF_NET.bFailAlarmLowYieldByTotal          ||
           TestIF_File.dLowYieldLimitByTotal            !=TestIF_NET.dLowYieldLimitByTotal              ||
           TestIF_File.iLowYieldCountByTotal            !=TestIF_NET.iLowYieldCountByTotal              ||
           TestIF_File.bFailAlarmLowYield               !=TestIF_NET.bFailAlarmLowYield                 ||
           TestIF_File.bFailAlarmSiteYieldDifferent     !=TestIF_NET.bFailAlarmSiteYieldDifferent       ||
           TestIF_File.iFailAlarmSiteYield              !=TestIF_NET.iFailAlarmSiteYield                ||
           TestIF_File.bContinuousPass                  !=TestIF_NET.bContinuousPass                    ||
           TestIF_File.iContinuousPassBinCount          !=TestIF_NET.iContinuousPassBinCount            ||
           TestIF_File.bContinuousPassBySocket          !=TestIF_NET.bContinuousPassBySocket            ||
           TestIF_File.iContinuousPassBinCountBySocket  !=TestIF_NET.iContinuousPassBinCountBySocket    ||
           TestIF_File.bContinuousLoader                !=TestIF_NET.bContinuousLoader                  ||
           TestIF_File.iContinuousLoaderCount           !=TestIF_NET.iContinuousLoaderCount             ||
           TestIF_File.bContinuousContact               !=TestIF_NET.bContinuousContact                 ||
           TestIF_File.iContinuousContactCount          !=TestIF_NET.iContinuousContactCount            ||
           TestIF_File.bContsFailBySocket               !=TestIF_NET.bContsFailBySocket                 ||
           TestIF_File.iContsFailSocketAlarmCT          !=TestIF_NET.iContsFailSocketAlarmCT            ||
           TestIF_File.bContsFailByHead                 !=TestIF_NET.bContsFailByHead                   ||
           TestIF_File.iContsFailHeadAlarmCT            !=TestIF_NET.iContsFailHeadAlarmCT)
        {
            ShowMyMessage("Yield Data Check Error!!");
            return false;
        }
    }
    return true;
}
