//---------------------------------------------------------------------------
void __fastcall TfMain::TimerESDTimer(TObject *Sender)
{
    static bool bRun=false;
    static int iIntervalCount=0;                                                //Ifor 20151222 :Yield Record 計數暫存器
    static AnsiString asOldESDError="", asEventlogPath="";                      //Ifor 20180821 :Add 判斷ESD Alarm Code 是否相同
//    static double dESDAlarmTime=0;                                            //Ifor 20180821 :Add 判斷ESD Alarm間隔時間
//    double dTime=0;                                                           //Ifor 20180821 :Add 判斷ESD Alarm間隔時間
#ifndef SOFT_SIMULTE
    static int iEventLogSavePeriod=600;                                         //JerryYang 20181210 add
#endif
#ifdef SOFT_SIMULTE
    return;
#endif
    int iRet;
    AnsiString str1="", str2="";

    if(InitialOK==false || bRun)
    {
        return;
    }
    bRun=true;
    if(ASESendMessage->bASE_AutoClean)                                          //kevin 20160722 遠端啟動 autoclean
    {
        ASESendMessage->bASE_AutoClean=false;                                   //kevin 20160722 遠端啟動 autoclean
        AutoCleanButtonClick(this);
    }
    //Ifor 20180821 : Add 避免ESD Alarm 短時間內重複發生
    //==>
    if(tESDError->Count!=0 && fNote->fShow==false)                              //Steven 20220610 : Note畫面沒顯示才可以Alarm
    {
        if(asOldESDError==tESDError->Strings[0] && tESDAlarmTimer.LatchCycleTime()<1500)                                //相同Alarm需間隔1.5秒才警報(設定秒數須大於Scan Time 1秒)
        {
            RecordProcess("The same Alarm occurs : "+asOldESDError);            //紀錄發生相同Alarm
            asOldESDError="";
        }
        else
        {
            asOldESDError=tESDError->Strings[0];
            if(asOldESDError=="MES0731")                                        //Steven 20220517 : Add for GIGA
            {
                iRet=ShowErrorMessage(tESDError->Strings[0], K_SKIP|K_ONECYCLE, MMSystem, false, "TimerESD");
                if(iRet==K_SKIP)                                                //做Reset
                {
                    for(int i=0; i<MAX_Index_Row; i++)
                    {
                        for(int j=0; j<NEW_MAX_Index_Col; j++)
                        {
                            if(FTestSuck.Item[i][j]!=NULL_IC && FTestSuck.Item[i][j]!=HAS_NULL_IC && FTestSuck.Item[i][j]<TEST_PASS)
                            {
                                FTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                                FTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, FTestSuck.cSBin[i][j], "RESET");                                     //Frank 20160505 add
                            }

                            if(BTestSuck.Item[i][j]!=NULL_IC && BTestSuck.Item[i][j]!=HAS_NULL_IC && BTestSuck.Item[i][j]<TEST_PASS)
                            {
                                BTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                                BTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, BTestSuck.cSBin[i][j], "RESET");                                     //Frank 20160505 add
                            }

                            if(TestSocket.Item[i][j]!=NULL_IC && TestSocket.Item[i][j]!=HAS_NULL_IC && TestSocket.Item[i][j]<TEST_PASS)
                            {
                                TestSocket.SetItemData(i, j, TEST_PASS+iTestBinCount);
                                TestSocket.PordRec[i][j].AddTestResultRecord(iTestBinCount, TestSocket.cSBin[i][j], "RESET");                                   //Frank 20160505 add
                            }
                        }
                    }

                    InitOneCycle("After Tester Pause handler, user skip IC on index arm.");
                }
                else                                                            //if(iRet==K_ONECYCLE)
                {
                    InitOneCycle("After Tester Pause handler, user perform one cycle.");
                }
                BtnOneCycle->Down=true;
            }
            else if(asOldESDError=="WAR07326" ||                                //Steven 20231017 : GPIB flow error need alarm
                    asOldESDError=="WAR07327" ||
                    asOldESDError=="WAR07328" ||
                    asOldESDError=="WAR07317")                                  //Steven 20231205 : 判斷RS232流程是否異常
            {
                if(IniConfig.iI46_ActionWhenGpibFlowErr==1)
                    iRet=ShowErrorMessage(tESDError->Strings[0], K_SKIP, MMSystem, false, "TimerESD");
                else if(IniConfig.iI46_ActionWhenGpibFlowErr==2)
                    iRet=ShowErrorMessage(tESDError->Strings[0], K_RETRY, MMSystem, false, "TimerESD");
                else
                    iRet=ShowErrorMessage(tESDError->Strings[0], K_SKIP|K_RETRY, MMSystem, false, "TimerESD");

                if(iRet==K_SKIP)
                {
                    TestProcessSetToErr("Test flow error set socket device to Error bin");
                }
                else
                {
                }
            }
            else if(asOldESDError=="MES1713" ||                                 //RogerYang 20250626 偉測不可複測bin功能
                    asOldESDError=="MES1813" ||
                    asOldESDError=="MES1913")
            {
                ShowErrorMessage(tESDError->Strings[0], K_RETRY|K_SKIP, MMSystem, false, "TimerESD");
            }
            else
            {
                ShowErrorMessage(tESDError->Strings[0], K_RETRY, MMSystem, false, "TimerESD");
            }
//            dESDAlarmTime = MyTickCount();
            tESDAlarmTimer.LatchCycleTime(true);
        }

        tESDError->Delete(0);
        if(tESDError->Count==0)                                                 //釋放記憶體
        {
            tESDError->Clear();
        }
    }
    //<==
    //Ifor 20180821 : Add 避免ESD Alarm 短時間內重複發生

    if(tGPIBMsg->Count!=0)                                                      //Steven 20190116 : GPIB顯示MSG
    {
        ShowMyMessage(tGPIBMsg->Strings[0], "");
        tGPIBMsg->Delete(0);
        if(tGPIBMsg->Count==0)                                                  //釋放記憶體
        {
            tGPIBMsg->Clear();
        }
    }

    //=================== Yield Record Start======================
    //Ifor 20151221 :新增 Yield Record 格式紀錄
    if(IniConfig.bI29EnableYieldRecord==true)                                   //Ifor 20151221 :新增判斷Yeild CosFunction與IniConfig 是否開啟
    {
        iIntervalCount++;
        if(iIntervalCount>=IniConfig.fI29YieldRecordInterval)                   //Ifor 20151221 :判斷Yield Record 是否到達設定時間
        {
            iIntervalCount=0;                                                   //清除秒數暫存器
            fContactCT->SaveSiteYield("By Interval");
        }
    }
    //=================== Yield Record End======================

    if(IniConfig.bO06SaveLogTimePeriod)                                         //JerryYang 20151026 : 使用ProductionData週期時間存檔
    {
        iSaveLogTimePeridCount++;
        if(iSaveLogTimePeridCount>=IniConfig.iO06SaveLogTimePeriod*1200+600)    //JerryYang 20151026 : ProductionData週期時間(0->10mins,1->30mins)
        {
            iSaveLogTimePeridCount=0;
            AnsiString str, sTemp, sTemp1, sSetupfile, sTemper, sTray[eTrayCount], sTrayPassFail, sBin;                 //JerryYang 20160201 add sTrayPassFail   //JerryYang 20220909 : 9->24
            AnsiString Str1, Buffer1="", Buffer2="";
            fMain->TimerRecordLoaderDate();
            sSetupfile=fMain->cbSetupFileName->Text;
            if(LastSet.iTemperature==Tempture_Ambient)
                sTemper="25.0";
            else
                sTemper=edWorkTemperBase->Text.c_str();

            for(int i=0; i<iTestBinCount; i++)                                  //QQQ
            {
                int iTray=Prod.iT6PosCate[i];
                if(iTray>0)
                {
                    if(sTray[iTray-1]=="")
                    {
                        sTray[iTray-1]=IntToStr(i);
                    }
                    else
                    {
                        sTray[iTray-1]=sTray[iTray-1]+","+IntToStr(i);
                    }
                }
            }

            Buffer1="";
            Buffer2="";
            for(int i=0; i<eTrayCount; i++)
            {
                if(Prod.iTrayType[i]!=tNotUse &&
                   Prod.iTrayType[i]!=tTrayBox)
                {
                    Str1.sprintf("%s:%d;", asTrayAlias[i], LastSet.BinCT[0][iTo3Unload[i]]);
                    Buffer1=Buffer1+Str1;

                    if(Prod.iIsFailT6[i]==1)                                    //Steven 20240105 : Prod.bIsPass --> Prod.iIsFailT6
                    {
                        if(Prod.iIfErrorT6==i)
                        {
                            sTrayPassFail="FE";
                        }
                        else
                        {
                            sTrayPassFail="F";
                        }
                    }
                    else
                    {
                        sTrayPassFail="P";
                    }

                    Str1.sprintf("%s(%s):%s;", asTrayAlias[i], sTrayPassFail, sTray[i]);
                    Buffer2=Buffer2+Str1;
                }
            }

            str.sprintf("Load:%d;Total:%d;%s%s",
                        LastSet.SendCT[0],
                        RunInfo.iUnloadCount,
                        Buffer1,
                        Buffer2);

            for(int i=0; i<TestSocket.iShtRow; i++)                             //記錄Arm良率  //AI(ht9045-v899) 20260820: i由1改0, 原本Row A(index 0)整排未被記錄; 全樹其餘ArmSKET迴圈(cSocket/auto9045/SCK_ART等)皆由0起算
            {
                for(int j=0; j<TestSocket.iShtCol; j++)
                {
                    double dColA=double(ArmData[0]->ArmSKET[i][j]->GetPCA());
                    double dColB=double(ArmData[1]->ArmSKET[i][j]->GetPCA());
                    if(TestIF_File.iShuttleMode==0)
                    {
                        sTemp1.sprintf("%3.2f%%", (dColA+dColB)/2);
                    }
                    else
                    {
                        if(TestIF_File.iShuttle_Sel==0)
                        {
                            sTemp1.sprintf("%3.2f%%", dColA);
                        }
                        else
                        {
                            sTemp1.sprintf("%3.2f%%", dColB);
                        }
                    }

                    sTemp.sprintf("%c%c:%s;", 'A'+i, 'a'+j, sTemp1);            //AI(ht9045-v899) 20260820: 標籤第二字母原誤用外層i, 同一列所有j印出同一標籤(2x4只印出4個"Aa"), 改為row='A'+i/col='a'+j; 直接取列欄索引即不需除法, 故移除20260515的ChangeToFloatNonPcnt+(int), 語意等同cContactCT.cpp:202 flat index/欄數
                    str=str+sTemp;
                }
            }
            str=str+"SetupFile:"+sSetupfile+";Temperature:"+sTemper+";";        //JerryYang 20160201 修改Production log格式
            ProductionLog(str, true);
        }
    }

#ifndef SOFT_SIMULTE
    if(IniConfig.bSPILFunction==true)                                           //JerryYang 20181210 SPIL要求檢查Event log,有異常需跳message
    {
        iEventLogSavePeriod++;
        if(iEventLogSavePeriod>=600)
        {
            if(SystemStart)
            {
                iEventLogSavePeriod=0;
                asEventlogPath=CheckAndReadIniData("D:\\HT9045\\config\\config.ini", "Event Log","AutoSaveEventLogPath", AnsiString("D:\\RMS"));
                if(!DirectoryExists(asEventlogPath))
                {
                    str1.sprintf("Event log存檔路徑異常,請確認網路是否正常連線!");
                    str2.sprintf("Path:%s", asEventlogPath);
                    ShowMyMessage(str1, str2);
                }
            }
        }
    }
#endif

    bRun=false;                                                                 //這行要在最下面
}
