//---------------------------------------------------------------------------
void TfMain::OverBelowRangeTemp(int iNowChannel, int iNowTemp, int iSetTemp, int iRange)                                //Steven 20140617 : for 海思
{                                                                               //Hsiong 2014.06.10 OverBelowRangeTemp
    String FailTemperatureDate;
    AnsiString sFailFileName;                                                   //kevin 20150908

    sFailFileName.sprintf("%s\\%04d%02d\\", asHiSiLogPath, SystemYear, SystemMonth);                                    //kevin 20150908
    MyForceDirectories(sFailFileName);
    FailTemperatureDate=Now().FormatString("yyyy-mm-dd");
    String FailTemperatureName="";
    FailTemperatureName=sFailFileName+"\\"+FailTemperatureDate+"-fail.txt";     //kevin 20150908

    String NowFailTemperature=Now().FormatString("hh:nn:ss");                   //channel:1, Temp:51.2 , Set Temp:55 , Range:3
    NowFailTemperature+="  channel:";
    NowFailTemperature+=iNowChannel;
    NowFailTemperature+=",  Temp:";
    NowFailTemperature+=iNowTemp;
    NowFailTemperature+=",  Set Temp:";
    NowFailTemperature+=iSetTemp;
    NowFailTemperature+=",  Range:";
    NowFailTemperature+=iRange;
    WriteDataToFile(FailTemperatureName, NowFailTemperature);
}
