bool TfMain::CheckSiteMapState()                                                //checkautoSitemap
{
    bool bHasErr=false;
    AnsiString ErrPart="";
    for(int i=0; i<MAX_SOCKET_ROW; i++)
    {
        for(int j=0; j<MAX_SOCKET_COL; j++)                                     //Eliot 2009_12_25 4->8
        {
            if(TestIF_File.iSiteMap[i][j]>=1 &&
               TestMode.iDutOnOff[0][i][j]==0)                                  //kevin 20150115 AutoSiteMap不能關 site
            {
               ErrPart+=IndexSuckName[i][j];
               bHasErr=true;
            }
        }
    }

    if(bHasErr)
    {
        MyDBIProcess("System", "AutoSiteMap Do not close Site");
        ShowErrorMessage("WAR07400", 0, MMSystem, 0, ErrPart);
        return false;
    }
    return true;
}
