//---------------------------------------------------------------------------
// AutoSitMap site  順序判斷   kevin 20160125
//---------------------------------------------------------------------------
bool TfMain::CheckSiteMapPriority()
{
    int iDouble[33];                                                            //kevin 20180302 32->33
    int iMax=0;
    ZeroMemory(iDouble, sizeof(iDouble));
    for(int i=0; i<MAX_SOCKET_ROW; i++)
    {
        for(int j=0; j<MAX_SOCKET_COL; j++)
        {
            if(iMax<=iAutoSiteMap[i][j])
                iMax=iAutoSiteMap[i][j];
            iDouble[iAutoSiteMap[i][j]]++;
        }
    }

    for(int i=1; i<=iSiteTotal; i++)
    {
        if(iDouble[i]>=2)
            return false;
    }
    return true;
}
//-------------------------------------------------------------------------------
void __fastcall TfMain::Timer5Timer(TObject *Sender)
{
    static bool bTimerRunning=false;
    static int iCount=0;                                                        //kevin 20201202 add count

    if(InitialOK==false || bTimerRunning==true)
        return;

    bTimerRunning=true;
    if(Temperature.bATCActiveCooling && Temperature.bUseTjFunction)
    {
        MmoTj->Lines = ATCInterfaceForm->ATC_60_SYS.sTjLogList;

        if(ATCInterfaceForm->ATC_60_SYS.sTjLogList->Count > 10000)
        {
            Button3Click(Owner);
            Memo1->Lines->Clear();
        }
    }
    //Ifor 20160223 add ATC2.0 & ATC7.0 ATC斷線停機
    //Ifor 20160331 add SECS GEM ATC Online 旗標
    if(ATC_SYSTEM==eATCHonPrecType)
    {
        if(SystemStart==true)
        {
            if(Temperature.bATCActiveCooling==true)
            {
                if(ATCInterfaceForm->ATC_SYS_PAL[0]->LedATCConnect->Value==false)
                {
                    iATCOnLine=false;
                    if(LastSet.iTester==ON_LINE || CUSTOMER_CODE==CC_ASE_SG)    //JerryYang 20230322 : 新增2DID模式, != offline改為 ==online   //Ifor 20180222 (wei) :HT7045 Offline 不判斷 ATC是否連線
                        ShowErrorMessage("WAR15309", 0, MMATC_TCPIP, false, "Main--Timer5");                            //ATC software disconnect! Please check ATC software ==> ATC connect error, Please confirm whether to open? and connect ATC
                }
                else
                {
                    iATCOnLine=true;
                }
            }
            else if(Temperature.bATC70Active==true)
            {
                if(fLotInfo->aldATCPower->Value==false)
                {
                    iATCOnLine=false;
                    if(LastSet.iTester==ON_LINE || CUSTOMER_CODE==CC_ASE_SG)    //JerryYang 20230322 : 新增2DID模式, != offline改為 ==online   //Ifor 20180222 (wei) :HT7045 Offline 不判斷 ATC是否連線
                        ShowErrorMessage("WAR15309", 0, MMATC_TCPIP, false, "Main--Timer5");                            //ATC software disconnect! Please check ATC software ==> ATC connect error, Please confirm whether to open? and connect ATC
                }
                else
                {
                    iATCOnLine=true;
                }
            }
        }
    }
    #ifndef SOFT_SIMULTE
    if(ATC_SYSTEM==eNewATCSystem)
    {
        if(ATC_InterfaceForm->IsConnect()==true)
        {
            iATCOnLine=true;
        }
        else
        {
            iATCOnLine=false;
            if(SystemStart==true && Temperature.bATCActiveCooling==true)
            {
                if(LastSet.iTester==ON_LINE || CUSTOMER_CODE==CC_ASE_SG)        //JerryYang 20230322 : 新增2DID模式, != offline改為 ==online  //Ifor 20180222 (wei) :HT7045 Offline 不判斷 ATC是否連線
                {
                    ShowErrorMessage("WAR15309", 0, MMATC_TCPIP, false, "Main--Timer5");                                //ATC software disconnect! Please check ATC software ==> ATC connect error, Please confirm whether to open? and connect ATC
                }
            }
        }
    }
    #endif

    if(CUSTOMER_CODE==CC_ASE_KaohSiung &&
       ATC_SYSTEM==eNewATCSystem &&
       iATCOnLine==1 && iReceiveATCData==0 && iCount>=3)                        //kevin 20200630dd read atc
    {
        iReceiveATCData=1;                                                      //kevin 20200608 讀取ATC 參數資料
        ATC_InterfaceForm->AskATCDateToHandle();
        iCount=0;                                                               //kevin 20201202 add count
    }

    if(CUSTOMER_CODE==CC_ASE_KaohSiung)
        iCount++;                                                               //kevin 20201202 add count

    bTimerRunning=false;
}
//---------------------------------------------------------------------------
void __fastcall TfMain::Timer6Timer(TObject *Sender)
{
    int iResult=0;
    static int count=0;
    AnsiString sSiteMap="", sText="";
    static bool bTimerRunning=false;
    if(InitialOK==false || bTimerRunning==true)
        return;

    bTimerRunning=true;

    if(IniConfig.bEnable_SECS_GEM==true && IniConfig.bRCMDStart==true && bPhysicalStart==true)
    {
        count++;
        if(count>IniConfig.iN07RunCheckAlarmTime)
        {
            count=0;
            bPhysicalStart=false;
            Timer6->Enabled=false;
            ShowErrorMessage("WAR16110", 0, MMSystem, false, "Main--Timer6");   //JerryYang 20170817 (Steven) SPIL景桂要求run check time out要上報
            bSECSGEMAlarm=false;                                                //Ifor 20151208 :解除按鍵Lock
        }
    }
    else if(CUSTOMER_CODE==CC_ChipMos_ZHUBEI && IniConfig.bN25_1_EnableStartControl)                                    //Steven 20210413 : 南茂的自動Start功能
    {
        switch(iAutoStartTask)
        {
            case 1:
                iResult=fFTPClient->N25_ReadAutoStartFileFromFTP();
                if(iResult==1)
                {
                    SoftStart=true;
                    bSecsGemCanStart=false;
                    bSECSGEMAlarm=false;                                        //Ifor 20151208 :解除按鍵Lock
                    bHasSaveSet=false;                                          //Ifor 20151208 :清除設定檔變更旗標
                    bPhysicalStart=true;
                    Timer6->Enabled=false;
                }
                else if(iResult==-1)
                {
                    bPhysicalStart=false;
                    Timer6->Enabled=false;
                }
                else
                {
                    tAutoStartTimer.SetSecAndOn(60);
                    iAutoStartTask=100;
                }
                break;
            case 100:
                if(tAutoStartTimer.Off())
                {
                    iAutoStartTask=1;
                }
                break;
        }

        if(iResult==0 && tAutoStartTimeOutTimer.Off())
        {
            bPhysicalStart=false;
            Timer6->Enabled=false;
            ShowMyMessage("Auto Start Check Time Out!", "自動Start檢查超出設定時間!");
        }
    }
    else if(IniConfig.bN29_ParameterCheckForGMTest==true)                       //Steven 20220311 : GM Test工作檔比對功能
    {
        switch(iAutoStartTask)
        {
            case 1:
                tAutoStartTimer.SetSecAndOn(60);
                if(!DirectoryExists(IniConfig.sN29_FilePath))
                {
                    iAutoStartTask=100;
                    break;
                }

                if(!FileExists(IniConfig.sN29_FilePath+"\\Important Parameter.csv"))
                {
                    iAutoStartTask=200;
                }

                if(ImpParaCheck->Count<=1)
                {
                    try
                    {
                        ImpParaCheck->LoadFromFile(IniConfig.sN29_FilePath+"\\Important Parameter.csv");
                        iAutoStartTask=400;
                    }
                    catch(...)
                    {
                        iAutoStartTask=300;
                    }
                }
                else
                {
                    iAutoStartTask=400;
                }
                break;
            case 100:
                bPhysicalStart=false;
                Timer6->Enabled=false;
                ShowMyMessage("Important parameter check directory not exist!", IniConfig.sN29_FilePath);
                break;
            case 200:
                bPhysicalStart=false;
                Timer6->Enabled=false;
                ShowMyMessage("Important parameter check file not exist!", IniConfig.sN29_FilePath);
                break;
            case 300:
                bPhysicalStart=false;
                Timer6->Enabled=false;
                ShowMyMessage("Important parameter read file fail!", IniConfig.sN29_FilePath);
                break;
            case 400:
                iResult=-1;
                for(int i=1; i<ImpParaCheck->Count; i++)
                {
                    ImpParaCheckRecipe->Clear();
                    ImpParaCheckRecipe->CommaText=ImpParaCheck->Strings[i];
                    if(ImpParaCheckRecipe->Count!=4)
                    {
                        continue;
                    }
                    else if(iResult==-1 && ImpParaCheckRecipe->Strings[1]==cbSetupFileName->Text)
                    {
                        sText=ImpParaCheckRecipe->Text;
                        iResult=1;
                        sSiteMap="";
                        double dTemp=atof(ImpParaCheckRecipe->Strings[3].c_str());
                        if((LastSet.iTemperature==Tempture_Ambient && dTemp!=25) ||
                           (LastSet.iTemperature!=Tempture_Ambient && dTemp!=Temperature.fWorkTemperBase))
                        {
                            iResult=-2;
                        }
                        else
                        {
                            if(TestIF_File.iTestMode==SingleSite)
                                sSiteMap="1X1_";
                            else if(TestIF_File.iTestMode==DualSite)
                                sSiteMap="2X1_";
                            else if(TestIF_File.iTestMode==TriSite1X3)
                                sSiteMap="3X1_";
                            else if(TestIF_File.iTestMode==QualSite1X4)
                                sSiteMap="4X1_";
                            else if(TestIF_File.iTestMode==DualSite2x1)
                                sSiteMap="1X2_";
                            else if(TestIF_File.iTestMode==QualSite2X2 ||
                                    TestIF_File.iTestMode==QualSite2X2N)
                                sSiteMap="2X2_";
                            else if(TestIF_File.iTestMode==_6Site2X3 ||
                                    TestIF_File.iTestMode==_6Site2X3N)          //Steven 20220425 : 2X3NN Mode
                                sSiteMap="3X2_";
                            else if(TestIF_File.iTestMode==_8Site2X4 ||
                                    TestIF_File.iTestMode==_8Site2X4N)          //Wei 20231211 : 2X4NN Mode
                                sSiteMap="4X2_";
                            else if(TestIF_File.iTestMode==_10Site2X5)
                                sSiteMap="5X2_";
                            else if(TestIF_File.iTestMode==_12Site2X6)
                                sSiteMap="6X2_";
                            else if(TestIF_File.iTestMode==_16Site2X8)
                                sSiteMap="8X2_";
                            else if(TestIF_File.iTestMode==_16Site4X4)
                                sSiteMap="4X4_";
                            else if(TestIF_File.iTestMode==_32Site4X8N)
                                sSiteMap="8X4_";
                            else if(TestIF_File.iTestMode==_32Site4X8M)
                                sSiteMap="8X4_";

                            int iCt=0;
                            for(int x=0; x<TestSocket.iShtRow; x++)
                            {
                                for(int y=0; y<TestSocket.iShtCol; y++)
                                {
                                    if(iCt==0)
                                    {
                                        iCt++;
                                        if(TestIF_File.iSiteMap[x][y]<0)
                                            sSiteMap+=AnsiString("0");
                                        else
                                            sSiteMap+=AnsiString(TestIF_File.iSiteMap[x][y]);
                                    }
                                    else
                                    {
                                        if(TestIF_File.iSiteMap[x][y]<0)
                                            sSiteMap+=AnsiString(":0");
                                        else
                                            sSiteMap+=AnsiString(":")+AnsiString(TestIF_File.iSiteMap[x][y]);
                                    }
                                }
                            }

                            if(sSiteMap!=ImpParaCheckRecipe->Strings[2])
                            {
                                iResult=-3;
                            }
                        }
                    }
                }

                if(iResult==1)
                {
                    SoftStart=true;
                    bSecsGemCanStart=false;
                    bSECSGEMAlarm=false;                                        //Ifor 20151208 :解除按鍵Lock
                    bHasSaveSet=false;                                          //Ifor 20151208 :清除設定檔變更旗標
                    bPhysicalStart=true;
                    Timer6->Enabled=false;
                }
                else if(iResult==-1)
                {
                    bPhysicalStart=false;
                    Timer6->Enabled=false;
                    ShowMyMessage("Important parameter check, recipe not found in list!", cbSetupFileName->Text);
                }
                else if(iResult==-2)
                {
                    bPhysicalStart=false;
                    Timer6->Enabled=false;
                    ShowMyMessage("Important parameter check, temperature setting error!", sText);                      //Steven 20220523 : modify
                }
                else if(iResult==-3)
                {
                    bPhysicalStart=false;
                    Timer6->Enabled=false;
                    ShowMyMessage("Important parameter check, site map setting error!", sText);                         //Steven 20220523 : modify
                }
                break;
        }

        if(tAutoStartTimer.Off())
        {
            bPhysicalStart=false;
            Timer6->Enabled=false;
            ShowMyMessage("Important Parameter Check Time Out!", "");
        }
    }
    else
    {
        count=0;

        if(SoftStart==false && SystemStart==false)                              //JerryYang 20250303 : fix run check沒有跳Timeout
        {
            bSECSGEMAlarm=false;
            bPhysicalStart=false;
            RecordProcess("Run check was interrupted!");
        }
        Timer6->Enabled=false;
    }
    bTimerRunning=false;
}
//---------------------------------------------------------------------------
void __fastcall TfMain::Timer7Timer(TObject *Sender)                            //Frank 20150515 add
{
    static int iCount=0;
    static bool bTimerRunning=false;
    static bool bYieldFlagForVAT=false;                                         //marvin 20200424 (Kirin) Added always record report by time.//marvin 20170707 (Klutter) Add send machine yield to newWork.//
    static bool bOEEFlagForVAT=false;

    if(InitialOK==false || bTimerRunning==true)
        return;

    bTimerRunning=true;

    if(IniConfig.bVTESTFunction==true)                                          //marvin 20200424 (Kirin) Added always record report by time.
    {
        if(atoi(Now().FormatString("nn").c_str())<=2)
        {
            if(bOEEFlagForVAT==false)
            {
                bOEEFlagForVAT=true;
                fMesSystem->RecordByTimeOEE(atoi(Now().FormatString("hh").c_str()));
            }

            if(bYieldFlagForVAT==false && (Now().FormatString("hh")=="08" || Now().FormatString("hh")=="20"))
            {
                bYieldFlagForVAT=true;
                fMesSystem->DoSaveReportByTime();
            }
        }
        else if(atoi(Now().FormatString("nn").c_str())>2)
        {
            bYieldFlagForVAT=false;
            bOEEFlagForVAT=false;
        }
    }

    if(USE_ROTATE_KIT &&                                                        //JerryYang 20250220 : fix
       tRotate.ActiveRotate)                                                    //Frank 20150626 : for矽格 要有IC方向顯示
    {
        ImgInRotateAngle->Visible=true;
        ImgOutRotateAngle->Visible=true;
        if(IniConfig.bSPILFunction==true)
        {
            labInRotate->Visible=true;                                          //JerryYang 20230822 : add
            labOutRotate->Visible=true;
        }

        if(bRotateChange)                                                       //Frank 20150626 : for矽格 要有IC方向顯示
        {
            RotateChangePicture();
            bRotateChange=false;
        }
    }
    else
    {
        ImgInRotateAngle->Visible=false;
        ImgOutRotateAngle->Visible=false;
        labInRotate->Visible=false;                                             //JerryYang 20230822 : add
        labOutRotate->Visible=false;
    }

    if(bCloseExcelflag && iCount<=3)
    {
        bCloseExcelfinishflag=false;
        HANDLE DestHandle;
        DestHandle=FindWindow("XLMAIN", NULL);
        if(DestHandle!=0)
        {
            PostMessage(DestHandle, WM_CLOSE, 0, 0);
            iCount++;
        }
        else
        {
            bCloseExcelflag=false;
            bCloseExcelfinishflag=true;
            RecordUPH(RunInfo.iUPH);
            iCount=0;
        }
    }

    if(iCount>3)
    {
        ShowMyMessage("請關閉csv檔案");
        if(SystemStart==false)                                                  //Sam 20210620 : 避免直跳 Alarm
        {
            iCount=0;
        }
    }
    bTimerRunning=false;
}
