void __fastcall TfMain::RotateChangePicture()
{
    static int iRotateAngleSelect;

    if(USE_ROTATE_KIT==0 || FrmRotate->bShowRotateBySite==true)                 //Steven 20170425 (wei) : Add rotate motor
    {
        ImgInRotateAngle->Visible=false;
        ImgOutRotateAngle->Visible=false;
        labInRotate->Visible=false;                                             //JerryYang 20230822 : add
        labOutRotate->Visible=false;
        return;
    }

    //jou 20231122 : Rotate Use RT mode
    if(Prod.RotationCount[0]==0)
    {
        iRotateAngleSelect=1;
    }
    else if(Prod.RotationCount[0]==90)
    {
        iRotateAngleSelect=2;
    }
    else if(Prod.RotationCount[0]==180)
    {
        iRotateAngleSelect=3;
    }
    else if(Prod.RotationCount[0]==270)
    {
        iRotateAngleSelect=4;
    }

    if(tRotate.bUseDifferentAngle==true)                                        //Out Arm 使用不同角度
    {
        if(Prod.OutRotationCount[0]==0)
        {
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-ccw0.bmp");
        }
        else if(Prod.OutRotationCount[0]==-90)
        {
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-ccw90.bmp");
        }
        else if(Prod.OutRotationCount[0]==-180)
        {
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-ccw180.bmp");
        }
        else if(Prod.OutRotationCount[0]==-270)
        {
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-ccw270.bmp");
        }
        else if(Prod.OutRotationCount[0]==90)
        {
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw90.bmp");
        }
        else if(Prod.OutRotationCount[0]==180)
        {
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw180.bmp");
        }
        else if(Prod.OutRotationCount[0]==270)
        {
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw270.bmp");
        }

        if(Prod.RotationCount[0]==0)                                            //Frank 20150626 add 1: 0°2: 90°3: 180°4: 270°
        {
            ImgInRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw0.bmp");
        }
        else if(Prod.RotationCount[0]==90)
        {
            ImgInRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw90.bmp");
        }
        else if(Prod.RotationCount[0]==180)
        {
            ImgInRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw180.bmp");
        }
        else if(Prod.RotationCount[0]==270)
        {
            ImgInRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw270.bmp");
        }
    }
    else
    {
        if(iRotateAngleSelect==1)                                               //Frank 20150626 add 1: 0°2: 90°3: 180°4: 270°
        {
            ImgInRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw0.bmp");
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-ccw0.bmp");
        }
        else if(iRotateAngleSelect==2)
        {
            ImgInRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw90.bmp");
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-ccw90.bmp");
        }
        else if(iRotateAngleSelect==3)
        {
            ImgInRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw180.bmp");
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-ccw180.bmp");
        }
        else if(iRotateAngleSelect==4)
        {
            ImgInRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-cw270.bmp");
            ImgOutRotateAngle->Picture->LoadFromFile(BmpPath+"Rotate-ccw270.bmp");
        }
    }
}
//---------------------------------------------------------------------------
void __fastcall TfMain::ChangePassword()                                        //wei 20150803 SECSGEM更改PASSWORD
{
    int i=0;
    char dest[20];
    char str[256];
    AnsiString asPassword,asNewPassword;

    PassList[3]->Clear();
    PassList[3]->LoadFromFile(pwPath);                                          //2012-01-03    Dell modify
    for(i=0; i<PassList[3]->Count; i++)
    {
        strncpy(str, PassList[3]->Strings[i].c_str(), sizeof(str));

        SplitStrByDotSpaceOnly(str, dest, 20);
        PassList[0]->Add(dest);

        SplitStrByDotSpaceOnly(str, dest, 20);
        PassList[1]->Add(dest);

        SplitStrByDotSpaceOnly(str, dest, 20);
        asPassword=dest;
        PassList[2]->Add(asPassword);

        if(asSECSGEMChangeName==PassList[0]->Strings[i].c_str() && asSECSGEMChangePassword!=PassList[2]->Strings[i].c_str())
        {
            PassList[2]->Strings[i]=asSECSGEMChangePassword.c_str();
        }
        asNewPassword.sprintf("%s %s %s",PassList[0]->Strings[i],PassList[1]->Strings[i],PassList[2]->Strings[i]);
        PassList[3]->Strings[i]=asNewPassword.c_str();
    }
    PassList[3]->SaveToFile(pwPath);
}
//---------------------------------------------------------------------------
void TfMain::CheckOTDStatus()                                                   //wei 20150810  OTD Log
{
    static bool bOld240OTDStatus=false;
    static bool bOld360OTDStatus=false;
    if(USE_OTD==2)
    {
        if(bCheckOTDStatus==false)
        {
            if(Sen[SenAutoDocking240KG].Status() &&  Sen[SenAutoDocking360KG].Status())
            {
                RecordProcess("OTD Lock");
                EventReport(SECS_EVENT.OTDLock);                                //wei 20150811 SecsGem OTD Lock/UnLock Event
            }
            else
            {
                RecordProcess("OTD UnLock");
                EventReport(SECS_EVENT.OTDUnLock);                              //wei 20150811 SecsGem OTD Lock/UnLock Event
            }
            bOld240OTDStatus=Sen[SenAutoDocking240KG].Status();
            bOld360OTDStatus=Sen[SenAutoDocking360KG].Status();
            bCheckOTDStatus=true;
        }
        else if(bCheckOTDStatus)
        {
            if(Sen[SenAutoDocking240KG].Status()!=bOld240OTDStatus &&  Sen[SenAutoDocking360KG].Status()!=bOld360OTDStatus)
            {
                if(Sen[SenAutoDocking240KG].Status() &&  Sen[SenAutoDocking360KG].Status())
                {
                    RecordProcess("OTD Lock");
                    EventReport(SECS_EVENT.OTDLock);                            //wei 20150811 SecsGem OTD Lock/UnLock Event
                }
                else
                {
                    RecordProcess("OTD UnLock");
                    EventReport(SECS_EVENT.OTDUnLock);                          //wei 20150811 SecsGem OTD Lock/UnLock Event
                }
                bOld240OTDStatus=Sen[SenAutoDocking240KG].Status();
                bOld360OTDStatus=Sen[SenAutoDocking360KG].Status();
            }
        }
    }
    else if(CUSTOMER_CODE==CC_KYEC_LEE || CUSTOMER_CODE==CC_KYEC_XILINX)
    {
        if(bCheckOTDStatus==false)
        {
            if(Sen[SnAutoDockingOn].IsOn())
            {
                RecordProcess("OTD Lock");
                EventReport(SECS_EVENT.OTDLock);                                //wei 20150811 SecsGem OTD Lock/UnLock Event
            }
            else if(Sen[SnAutoDockingOff].IsOn())
            {
                RecordProcess("OTD UnLock");
                EventReport(SECS_EVENT.OTDUnLock);                              //wei 20150811 SecsGem OTD Lock/UnLock Event
            }
            bOld240OTDStatus=Sen[SnAutoDockingOff].IsOn();
            bOld360OTDStatus=Sen[SnAutoDockingOn].IsOn();
            bCheckOTDStatus=true;
        }
        else if(bCheckOTDStatus)
        {
            if(Sen[SnAutoDockingOff].IsOn()!=bOld240OTDStatus ||
               Sen[SnAutoDockingOn].IsOn()!=bOld360OTDStatus)
            {
                if(Sen[SnAutoDockingOn].IsOn())
                {
                    RecordProcess("OTD Lock");
                    EventReport(SECS_EVENT.OTDLock);                            //wei 20150811 SecsGem OTD Lock/UnLock Event
                }
                else if(Sen[SnAutoDockingOff].IsOn())
                {
                    RecordProcess("OTD UnLock");
                    EventReport(SECS_EVENT.OTDUnLock);                          //wei 20150811 SecsGem OTD Lock/UnLock Event
                }
                bOld240OTDStatus=Sen[SnAutoDockingOff].IsOn();
                bOld360OTDStatus=Sen[SnAutoDockingOn].IsOn();
            }
        }
    }
}
