//---------------------------------------------------------------------------
void __fastcall TfMain::edSetupFileNameKeyUp(TObject *Sender, WORD &Key, TShiftState Shift)                             //Frank 20150909 : CC_AMKOR 需要使用BarcodeReader讀取工作檔
{
    if(SystemStart)
    {
        edSetupFileName->Text=cbSetupFileName->Text;
        return;
    }

    AnsiString S, Str;
    bool bflag=false;

    if(Key==0x0d)                                                               //Enter
    {
        if(CheckCanChangeRealDummy()==false || HasICUnderMachine())             //Steven 20240719 : && --> ||
        {
            ShowErrorMessage("MES1646", 0, MMSystem, false, "SetupFileNameKeyUp");                                      //Must finish [Clean out]!!
            edSetupFileName->Text=cbSetupFileName->Text;
            return;
        }

        if(SoftStart==false)
        {
            Str=edSetupFileName->Text;
            for(int i=0; i<cbSetupFileName->Items->Count; i++)
            {
                if(Str==cbSetupFileName->Items->Strings[i])
                {
                    cbSetupFileName->ItemIndex=i;
                    bflag=true;
                }
            }
        }

        if(bflag)
        {
            cbSetupFileNameDropDown(Owner);
            cbSetupFileNameChange(Owner);
            ShowMyMessage("機台工作檔更換完成");
        }
        else
        {
            ShowMyMessage("機台未有此工作檔");
            edSetupFileName->Text=cbSetupFileName->Text;
        }
    }
}
