bool TfMain::ATCAmbientTemperCheck()                                            //wei 20151014
{
    if(IniConfig.dATCAmbientTemperature==0 ||
       IniConfig.dATCAmbientTemperature<25 ||
       IniConfig.dATCAmbientTemperature>30)
    {
        if(ATC_SYSTEM==eNewATCSystem &&
           (ATC_InterfaceForm->IS_ATC33() ||
            ATC_InterfaceForm->iATC_MODE_TYPE==ATC_TYPE_61))
        {
            if(IniConfig.dATCAmbientTemperature<-5)
                return false;
        }
        else
        {
            return false;
        }
    }
    return true;
}
