//------------------kevin 20130425----------------------------------------------
// 2015.11.11 , Joye , Add Jam Rate Record
void TfMain::RecordJamRateByTime()
{
    static clock_t ctStart=clock();
    if(IniConfig.bRecordJamRateByTime==false ||
       IniConfig.iRecordJamRateIntervalTime<=0)
    {
        return;
    }

    if(bRecordJamRateByTime_Clear==true)
    {
        ctStart=clock();
        bRecordJamRateByTime_Clear=false;
    }

    clock_t ctEnd=clock();
    if(ctEnd-ctStart>=IniConfig.iRecordJamRateIntervalTime*1000*60)
    {
        ctStart=clock();
        AnsiString sMTBFRecord="";
        double fH;
        int iH;

        if(iRecordJamRateByTime_JamCount==0)
        {
            fH = IniConfig.iRecordJamRateIntervalTime/60.;
            iH = fH*1000;
            fH = double(iH)/1000.;
            sMTBFRecord = AnsiString("  MTBF 0/") + AnsiString(fH) + AnsiString("hr");
        }
        else
        {
            fH =  iRecordJamRateByTime_JamCount/(IniConfig.iRecordJamRateIntervalTime/60.);
            iH = fH*1000;
            fH = double(iH)/1000.;
            sMTBFRecord = AnsiString("  MTBF 1/") + AnsiString(fH) + AnsiString("hr");
        }

        AnsiString sJamRateRecord   = "";
        sJamRateRecord = AnsiString("[Jam Rate Record] ") + AnsiString(iRecordJamRateByTime_JamCount) + "/" + AnsiString(iRecordJamRateByTime_LoaderCount) + sMTBFRecord;
        RecordProcess( sJamRateRecord );
        iRecordJamRateByTime_LoaderCount    = 0;
        iRecordJamRateByTime_JamCount       = 0;
    }
}
//---------------------------------------------------------------------------
TQPF_Timer LoaderCheckFullDelay;
//---------------------------------------------------------------------------
void __fastcall TfMain::Timer8Timer(TObject *Sender)
{
    static bool bTimerRunning=false;
    static bool bTimerOn=false;
    static unsigned int iTesterAlarmCount=0;
    if(InitialOK==false || bTimerRunning==true)
        return;

    bTimerRunning=true;

    if(bNeedClearFile)
    {
        try
        {
            if(CosFunction.bKeepOnly1SetupFile)
                fLotInfo->ClearAllSetupFile(PPID);                              //Steven 20210917 : Add for 下載完工作檔後, 只留一個就好
        }
        catch(...)
        {
        };

        bNeedClearFile=false;
        return;
    }

    if(IniConfig.bVTESTFunction==true)
    {
        iTesterAlarmCount++;
        if(Sen[SnTesterAlarm].IsOn() && iTesterAlarmCount>=10)
        {
            ShowErrorMessage("MES0732", K_RETRY, MMInterface);                  //jou 20240103 : LB Undocking，需QA確認補償檔，增加權限設定
            iTesterAlarmCount=0;
        }
    }

    if(bReadEpTime)                                                             //kevin 20170524 (wei) add ep read change time
    {
        fMain->ReadEPData();
        bReadEpTime=false;
    }

    if(IniConfig.bP29LoaderCheckIsFull)                                         //Steven 20160818 : CheckLoader滿盤
    {
        if(bTimerOn==false)
        {
            LoaderCheckFullDelay.SetSecAndOn(IniConfig.dP29LoaderCheckIsFullInterval);
            bTimerOn=true;
        }

        if(bTimerOn && LoaderCheckFullDelay.Off())
        {
            if(Sen[SnLoaderIsFull].Enable && Sen[SnLoaderIsFull].IsOn())
            {
                ShowErrorMessage("MES0921", 0, MMTrayZ, false, "Main--Timer8");
            }
            else
            {
                bTimerOn=false;
            }
        }
    }

    if(IniConfig.bA19UsePMAlarmFunction==true)                                  // 2015.05.26 , Mylin , PM Alarm {      //wei 20160225 PMAlarmFunction
    {
        AnsiString sDate=fPMAlarmInterFace->GetWhenAlarmShowPMDate();
        if(sDate!="")
        {
            sDate="PM Alarm Date " + sDate;
            lb_PMAlarmDate->Caption=sDate;
            lb_PMAlarmDate->Visible=true;
        }
        else
        {
            lb_PMAlarmDate->Visible=false;
        }
    }
    else
    {
        lb_PMAlarmDate->Visible=false;
    }

    if(IniConfig.bEnableAutoCleanFunction && TestIF_File.iAutoClean_Function)   //Steven 20240731 : add for auto clean count
    {
        pnlCleanCount->Visible=true;
    }
    else
    {
        pnlCleanCount->Visible=false;
    }

    if(TestIF_File.bEnableBarCode==true &&
       fMain->bHasPin1Error==true       &&
       CUSTOMER_CODE==CC_AMD_M)
    {
        AnsiString Buffer;
        fMain->bHasPin1Error=false;
        ShowErrorMessage("WAR07451", K_SKIP, MMTrayZ, false, "Main--Timer8");
        TestSocket.SetAllHASIC2ErrorBin();
        Buffer.printf("Place to Error bin : Device= %d",TestSocket.CountRealIC());
        MyDBIProcess("Message", Buffer);
        fMain->RunTestProgram(false);
    }
    RecordJamRateByTime();                                                      // 2015.11.11 , Joye , Add Jam Rate Record
    bTimerRunning=false;
}
//---------------------------------------------------------------------------
void TfMain::RunCheckStart()                                                    // Ifor 20151208 :新增Run Check 副程式
{
    if(CUSTOMER_CODE==CC_XINYUN && IniConfig.bEnable_SECS_GEM==true)            //RogerYang 20260610 : for 芯云定義
    {
        EventReport(SECS_EVENT.UnloadComplete);                                 // 送 102
        return;                                                                 // ← 跳過後面原本送 CEID 1 的邏輯
    }

    if(IniConfig.bSPILFunction==true &&                                         //JerryYang 20250912 : fix二次啟動會多送EVENT REPORT
       IniConfig.bEnable_SECS_GEM==true &&
       IniConfig.bRCMDStart==true &&
       bPhysicalStart==true)
    {
        bPhysicalStart=true;
        return;
    }

//    if(IniConfig.bSPILFunction==true)                                         //Steven 20211109 : Mark掉, 避免客戶使用START當作檢查工作檔的判斷
//    {                                                                         //Ifor 20151208 :矽品 Run Check 時機修改
        if((IniConfig.bSPILFunction==true ||
            (CUSTOMER_CODE==CC_ChipMos_ZHUBEI && IniConfig.bN25_1_EnableStartControl) ||
            (IniConfig.bRCMDStart==true && bPhysicalStart==true)) &&
           bHasSaveSet==true)                                                   //Steven 20220601 : 針對不同客戶的回覆值不同
        {
            EventReport(SECS_EVENT.DoStart);
        }
        else if(HasICUnderMachine()==false)                                     //Ifor 20151208 :判斷是否為第一次啟動 或者 設定檔案有變更
        {
            EventReport(SECS_EVENT.DoStart);
        }
        else
        {
            EventReport(SECS_EVENT.DoStartHasIC);
        }
//    }
//    else
//    {
//        EventReport(SECS_EVENT.DoStart);
//    }
}
