//---------------------------------------------------------------------------
//   生產中讀取EP資料 kevin 20160106
//---------------------------------------------------------------------------
AnsiString TfMain::ReadEPData()
{
    String NowEPData="";
    double dValue=0.0;
    if(CUSTOMER_CODE==CC_ASE_KaohSiung)                                         //kevin 20170117 (Steven) For ASE_KaohSiung資料傳輸
    {
        NowEPData = GetDateInfoByString("/") + " " + GetOnlyTimeInfoByString(":");
        if(ESD_Monitor || USE_NOVX3360)
            SendCommand_ESD(ESD_ESD_Data);                                      //kevin 20161229 add get ESD Data
    }
    else
    {
        NowEPData=Now().FormatString("hh:nn:ss");
    }

    if(IndexStatus==Z1Down_Z2Up ||
       (iContactMode==CONTACT_TEST && iIndexArm==0))                            //kevin 20310605 add contract mode
        NowEPData+=",1,";                                                       //Index 1
    else if(IndexStatus==Z1Up_Z2Down ||
            (iContactMode==CONTACT_TEST && iIndexArm==1))                       //kevin 20310605 add contract mode
        NowEPData+=",2,";                                                       //Index 2
    else
        NowEPData+=",NA,";

    NowEPData+=fContact->edSetKg->Text+",";
    int iReadData=ADAM_ReadPA(&dValue);                                         //wei 20220309 Add EP Return Voltage
    AnsiString StrData=IntToStr(iReadData);
    NowEPData+=StrData+",";
    double dbTransferKg=KpaTransferKG(iReadData);
    StrData=FormatFloat("0.0000", dbTransferKg/1000);
    NowEPData+=StrData;                                                         //kevin 20170117

    if(IniConfig.bD26EnableEPEncoderRange)
    {
        if(ADAM_Alarm())
        {
            NowEPData+="Alarm,";
        }
        else
        {
            NowEPData+="Pass,";
        }
    }

    Ase_SendEP = NowEPData;                                                     //kevin 20170117 for HISI
    if(Ase_SendESD=="")
        Ase_SendESD="NA";
    Ase_SendESDTempEPData="@e02007"+Ase_SendEP+";"+Ase_SendESD+";"+Ase_SendTemp;                                        //kevin 20161231 傳送資料給ASE
    if(CUSTOMER_CODE==CC_ASE_KaohSiung)                                         //kevin 20170103
        ASESendMessage->SendToASEData(Ase_SendESDTempEPData);

    return NowEPData;
}
