//----------------------------------------------------------------------------
bool TfMain::CheckInOutArmZHomeSensor()                                         //Frank 20160612 add Check In/Out Arm Home Sensor Function
{
    int iMotNoIn, iMotNoOut;
    for(int i=0; i<InArmSuck.iMotRow; i++)
    {
        for(int j=0; j<InArmSuck.iMotCol; j++)
        {
            iMotNoIn =(USE_PICKER_COUNT==ep16Picker && InOutArmPickerUseMotor==eptUseMotCyn)?MInArmZA:InArmSuck.Suck[i][j].iMotNo;
            iMotNoOut=(USE_PICKER_COUNT==ep16Picker && InOutArmPickerUseMotor==eptUseMotCyn)?MOutArmZA:OutArmSuck.Suck[i][j].iMotNo;
            if(MOT[iMotNoIn].ReadPos()>=0)
            {
                MOT[iMotNoIn].ScanMotorStatus();
                if(MOT[iMotNoIn].Motor->Enable && MOT[iMotNoIn].Led[iHomeLed]==false)
                {
                      MOT[MInArmX].PCIL132_StopMotor();
                      MOT[MInArmY].PCIL132_StopMotor();
                      ShowMyMessage(MOT[iMotNoIn].NumberAlias+" Home sensor error, if suck is down, maybe sensor fail!",
                                    MOT[iMotNoIn].NumberAlias+"歸零sensor錯誤；如果吸嘴在下方，可能是sensor壞掉");
                      return false;
                }
            }

            if(MOT[iMotNoOut].ReadPos()>=0)
            {
                MOT[iMotNoOut].ScanMotorStatus();
                if(MOT[iMotNoOut].Motor->Enable && MOT[iMotNoOut].Led[iHomeLed]==false)
                {
                      MOT[MInArmX].PCIL132_StopMotor();
                      MOT[MInArmY].PCIL132_StopMotor();
                      ShowMyMessage(MOT[iMotNoOut].NumberAlias+" Home sensor error, if suck is down, maybe sensor fail!",
                                    MOT[iMotNoOut].NumberAlias+"歸零sensor錯誤；如果吸嘴在下方，可能是sensor壞掉");
                      return false;
                }
            }
        }
    }
    return true;
}
