bool TfMain::CheckSLKSensor()                                                   //JerryYang 20160712 檢查SLK sensor改為函式
{
    if(TestIF_File.bUseSLKClamp==true)                                          //JerryYang 20160526 判斷SLK Sensor
    {
        if(TestIF_File.iSeparabilityTest==0)                                    //JerryYang 20160602 安裝分離式SLK,跑Direct contact mode
        {
            if(TestIF_File.iShuttleMode==1)                                     //單ARM
            {
                if(TestIF_File.iShuttle_Sel==0)                                 //只使用Arm1
                {
                    if(Cylinder[C_SLK1_Clamp].OnSensor()==false)
                    {
                        ShowMyMessage("Please check the clamp I/O of arm1 layout kit", "請確認Arm1 layout kit clamp汽缸的I/O是否正常");
                        return false;
                    }
                }
                else if(TestIF_File.iShuttle_Sel==1)                            //只使用Arm2
                {
                    if(Cylinder[C_SLK2_Clamp].OnSensor()==false)
                    {
                        ShowMyMessage("Please check the clamp I/O of arm2 layout kit", "請確認Arm2 layout kit clamp汽缸的I/O是否正常");
                        return false;
                    }
                }
            }
            else
            {
                if(Cylinder[C_SLK1_Clamp].OnSensor()==false)
                {
                    ShowMyMessage("Please check the clamp I/O of arm1 layout kit", "請確認Arm1 layout kit clamp汽缸的I/O是否正常");
                    return false;
                }
                else if(Cylinder[C_SLK2_Clamp].OnSensor()==false)
                {
                    ShowMyMessage("Please check the clamp I/O of arm2 layout kit", "請確認Arm2 layout kit clamp汽缸的I/O是否正常");
                    return false;
                }
            }
        }
        else                                                                    //JerryYang 20160602 安裝分離式SLK,跑分離測試流程
        {
            if(TestIF_File.iShuttleMode==1)                                     //單ARM
            {
                if(TestIF_File.iShuttle_Sel==0)                                 //只使用Arm1
                {
                    if(Cylinder[C_SLK1_Clamp].OnSensor()==false && Cylinder[C_SLK1_Unclamp].OnSensor()==false)
                    {
                        ShowMyMessage("Please check the clamp I/O of arm1 layout kit", "請確認Arm1 layout kit clamp汽缸的I/O是否正常");
                        return false;
                    }
                }
                else if(TestIF_File.iShuttle_Sel==1)                            //只使用Arm2
                {
                    if(Cylinder[C_SLK2_Clamp].OnSensor()==false && Cylinder[C_SLK2_Unclamp].OnSensor()==false)
                    {
                        ShowMyMessage("Please check the clamp I/O of arm2 layout kit", "請確認Arm2 layout kit clamp汽缸的I/O是否正常");
                        return false;
                    }
                }
            }
            else
            {
                if(Cylinder[C_SLK1_Clamp].OnSensor()==false && Cylinder[C_SLK1_Unclamp].OnSensor()==false)
                {
                    ShowMyMessage("Please check the clamp I/O of arm1 layout kit", "請確認Arm1 layout kit clamp汽缸的I/O是否正常");
                    return false;
                }
                else if(Cylinder[C_SLK2_Clamp].OnSensor()==false && Cylinder[C_SLK2_Unclamp].OnSensor()==false)
                {
                    ShowMyMessage("Please check the clamp I/O of arm2 layout kit", "請確認Arm2 layout kit clamp汽缸的I/O是否正常");
                    return false;
                }
            }
        }
    }
    return true;
}
//---------------------------------------------------------------------------
bool TfMain::CheckAuto1OnlyBin1()                                               //Alick 20160802 add for SCC Auto1 Only Bin1 Function
{
    if(CUSTOMER_CODE==CC_UNISEM_M && LastSet.iTester==OFF_LINE)                 //Ifor 20171213 (Steven) : add UNISEM_M 要求Offline 不卡 Auto1 Only Bin1 功能
        return false;

    for(int i=0; i<iTestBinCount; i++)
    {
        if(Prod.iT6PosCate[i]!=ePosAuto1 && i==1)
        {
            ShowMyMessage("Bin1未被設定在Auto1 !! 請確認 !!\n Bin1 is not set to Auto1 !! Please Check !!");
            return true;
        }
        else if(Prod.iT6PosCate[i]==ePosAuto1 && i!=1)
        {
            ShowMyMessage("只有Bin 1被允許設為 Auto1 !! 請確認 !!\n Only Bin 1 is allowed to set to Auto 1!!! Please check !!");
            return true;
        }
    }
    return false;
}
//---------------------------------------------------------------------------
bool TfMain::CheckAutoOnlySetOneBin()                                           //V3.27R.560 Ifor 20171213 (Steven) : Auto Tray 設定Pass時僅可設定一個Bin
{
    int iBinCount=0;

    AnsiString str1, str2;
    if(CosFunction.bUsePassBinOnlyCanSetOneBin==true)
    {
        for(int i=0; i<eTrayCount; i++)
        {
            if(Prod.iIsPassT6[i]==1)                                            //Steven 20240105 : Prod.bIsPass --> Prod.iIsFailT6
            {
                iBinCount=0;
                for(int j=0; j<iTestBinCount; j++)
                {
                    if(Prod.iT6CatData[j]==i)
                    {
                        iBinCount++;
                        if(iBinCount>1)
                        {
                            str1.sprintf("%s Pass Bin Only Can Set One Bin.", s6TrayName[i]);
                            str2.sprintf("%s Pass Bin 僅可設定一個Bin", s6TrayName[i]);
                            ShowMyMessage(str1, str2);
                            return true;
                        }
                    }
                }
            }
        }
    }
    return false;
}
