//---------------------------------------------------------------------------
bool TfMain::CheckRunMode()                                                    //Frank 20260710 ADD//Eastsun 20260710整合
{
    AnsiString asPath, Str, Str1;
    int iMode;
    TStringList *sList= new TStringList();

    asPath="d:\\HT9045\\system\\RunMode.txt";
    if(FileExists(asPath))
    {
        sList->LoadFromFile(asPath);
        Str=sList->Strings[0];
        iMode=atoi((Str.SubString(9, Str.Length())).c_str());
        if(LastSet.iRunStartMode!=iMode)
            return true;
        else
            return false;
    }
    sList->Clear();
    delete sList;
    return false;
}
