//---------------------------------------------------------------------------
void TfMain::AddTorqueLog(AnsiString Msg)                                       //Steven 20160908 : 整合成Function
{
    AnsiString sFileName="", sMegTime="", asLog="";

    GetTimeInfo();
    sMegTime.sprintf("%04d-%02d-%02d %02d:%02d:%02d %03d", SystemYear, SystemMonth, SystemDate, SystemHour, SystemMin, SystemSec, SystemMSec);
    asLog.sprintf("%s : %s", sMegTime,Msg);
    AnsiString S1="";

    if(ListBox14->Items->Count>300)
    {
        if(TorqueUseHPComCard)                                                  //kevin 20211022 : 使用鴻勁自製的通訊卡
            slTorquMUClog->MySaveToFile();                                      //Steven 20210524 : 連續讀取扭力

        ListBox14->Clear();
    }

    ListBox14->Items->Add(asLog);
    if(TorqueUseHPComCard)                                                      //kevin 20211022 : 使用鴻勁自製的通訊卡
    {
        S1.sprintf("MCU: %s",Msg);
        slTorquMUClog->AddTextWithDateTime(S1);
    }
}
//---------------------------------------------------------------------------
void __fastcall TfMain::sbPEModelClick(TObject *Sender)
{
    if(fSecurity->Insufficient(128)==false && HasICUnderMachine()==false)       //Ifor 20160826 add 機台內有IC不可切換PE模式 && PE模式權限卡控
        return;

    if(sbPEModel->Tag==0)
    {
        sbPEModel->Tag=1;
        sbPEModel->Caption = "PE Model ON";
        sbPEModel->Font->Color = clGreen;
        bHasEnteredPEModel=true;                                                //Ifor 20160822 進入PE工程模式
        bEnablePEModel=true;                                                    //Ifor 20160822 啟動PE工程模式
        edATCAmbientTemper->Enabled=true;                                       //Ifor 20160411 開啟常溫溫度修改
        edWorkTemperBase->Enabled=true;                                         //Ifor 20160411 開啟工作溫度修改
        edSoakTime->Enabled=true;                                               //Ifor 20160822 開啟Soak Time 修改
        WriteIniDataGeneral("System", "bHasEnteredPEModel",bHasEnteredPEModel);                                         //Ifor 20160824 避免 PE模式修改後程式被關閉上傳
        RecordProcess("Enable PE Model");
    }
    else
    {
        sbPEModel->Tag=0;
        sbPEModel->Caption = "PE Model OFF";
        sbPEModel->Font->Color = clRed;
        bEnablePEModel=false;                                                   //Ifor 20160822 關閉PE工程模式
        if(CosFunction.bHiSiliconFunction==true)                                //Ifor 20160822 關閉PE功能模式且為海思版本需鎖定溫度相關修改
        {
            edATCAmbientTemper->Enabled=false;                                  //Ifor 20160411 關閉常溫溫度修改
            edWorkTemperBase->Enabled=false;                                    //Ifor 20160411 關閉工作溫度修改
            edSoakTime->Enabled=false;                                          //Ifor 20160822 關閉Soak Time 修改
        }
        bFTPDownloadSetupFile=false;                                            //Ifor 20160822 關閉PE工程模式需強制下載Setup File
        RecordProcess("Disable PE Model");
        if(CUSTOMER_CODE==CC_KYEC_LEE)                                          //Ifor 20160830 add 離開PE模式 要將修改的Bin Cons Fail 強制寫回 True
        {
            AnsiString StrData="";
            for(int i=0; i<TEST_MAX_BIN; i++)
            {
                if(Prod.iT6CatData[i]==Prod.iIfErrorT6)
                {
                    StrData=StrData+"1";
                    Prod.bConsFail[i]=true;
                }
                else
                {
                    StrData=StrData+"0";
                }

                if(i!=TEST_MAX_BIN)
                    StrData=StrData+",";
            }
            fBinSel->sBinConsFail[iTestRunMode]->CommaText=StrData;
            fBinSel->spbSave->Click();
        }
    }
}
