//---------------------------------------------------------------------------
//JerryYang 20170610 (wei) JSCC要求Out shuttle lose IC需自動one cycle,並將對應的site設為Error bin
void __fastcall TfMain::JSCC_ResetForShuttleLoseIC()
{
    AnsiString asString,ErrCnt;
    int iSht1ErrCnt=0, iSht2ErrCnt=0, iArm1ErrCnt=0, iArm2ErrCnt=0, iSocketErrCnt=0;
    if(SystemStart==true || bResetMode==true ||                                 //must in system pause
        bResetModeAndCleanOut==true)                                            //JerryYang 20151007 : ResetMode可選OneCycle或CleanOut
        return;

    if(fAllMotorHome==false)
        return;

    if(SoftStart)                                                               //must in system pause
        return;

    if(bRunAutoClean)                                                           //Jou 2014-03-11 : Auto Clean時不能Reset
        return;

    for(int i=0; i<MAX_Index_Row; i++)
    {
        for(int j=0; j<NEW_MAX_Index_Col; j++)
        {
            if(bTestSiteNeedSetErrBin[i][j]==true ||                            //JerryYang 20220927 : 修正只有單一邊SHUTTLE/ARM被設定為ERROR BIN
               bTestSiteNeedSetErrBin[i+2][j]==true)                            //Steven 20210904 : 加入32site Out shuttle lose IC需自動one cycle,並將對應的site設為Error bin
            {
                if(FRCarryKit.Item[i][j]!=NULL_IC &&
                   FRCarryKit.Item[i][j]!=HAS_NULL_IC)
                {
                    FRCarryKit.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    FRCarryKit.PordRec[i][j].AddTestResultRecord(iTestBinCount, FRCarryKit.cSBin[i][j], "RESET_ForShuttleLoseIC");                              //Frank 20160505 add
                    iSht1ErrCnt++;
                }

                if(FTestSuck.Item[i][j]!=NULL_IC &&
                   FTestSuck.Item[i][j]!=HAS_NULL_IC)
                {
                    FTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    FTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, FTestSuck.cSBin[i][j], "RESET_ForShuttleLoseIC");                                //Frank 20160505 add
                    iArm1ErrCnt++;
                }

                if(BRCarryKit.Item[i][j]!=NULL_IC &&
                   BRCarryKit.Item[i][j]!=HAS_NULL_IC)
                {
                    BRCarryKit.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    BRCarryKit.PordRec[i][j].AddTestResultRecord(iTestBinCount, BRCarryKit.cSBin[i][j], "RESET_ForShuttleLoseIC");                              //Frank 20160505 add
                    iSht2ErrCnt++;
                }

                if(BTestSuck.Item[i][j]!=NULL_IC &&
                   BTestSuck.Item[i][j]!=HAS_NULL_IC)
                {
                    BTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    BTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, BTestSuck.cSBin[i][j], "RESET_ForShuttleLoseIC");                                //Frank 20160505 add
                    iArm2ErrCnt++;
                }
            }

            if(TestSocket.Item[i][j]!=NULL_IC &&
               TestSocket.Item[i][j]!=HAS_NULL_IC)
            {
                TestSocket.SetItemData(i, j, TEST_PASS+iTestBinCount);
                TestSocket.PordRec[i][j].AddTestResultRecord(iTestBinCount, TestSocket.cSBin[i][j], "RESET_ForShuttleLoseIC");                                  //Frank 20160505 add
                iSocketErrCnt++;
            }

            if(TestSocket.Item[i+2][j]!=NULL_IC &&
               TestSocket.Item[i+2][j]!=HAS_NULL_IC)                            //Steven 20210904 : 加入32site Out shuttle lose IC需自動one cycle,並將對應的site設為Error bin
            {
                TestSocket.SetItemData(i+2, j, TEST_PASS+iTestBinCount);
                TestSocket.PordRec[i+2][j].AddTestResultRecord(iTestBinCount, TestSocket.cSBin[i+2][j], "RESET_ForShuttleLoseIC");                              //Frank 20160505 add
                iSocketErrCnt++;
            }
        }
    }

    if(iSht1ErrCnt>0)
    {
        ErrCnt.sprintf("Shuttle lose IC, Shuttle 1 set to error Bin : %d pcs", iSht1ErrCnt);
        MyDBIProcess("Message", ErrCnt);
    }

    if(iSht2ErrCnt>0)
    {
        ErrCnt.sprintf("Shuttle lose IC, Shuttle 2 set to error Bin : %d pcs", iSht2ErrCnt);
        MyDBIProcess("Message", ErrCnt);
    }

    if(iArm1ErrCnt>0)
    {
        ErrCnt.sprintf("Shuttle lose IC, Arm 1 set to error Bin : %d pcs", iArm1ErrCnt);
        MyDBIProcess("Message", ErrCnt);
    }

    if(iArm2ErrCnt>0)
    {
        ErrCnt.sprintf("Shuttle lose IC, Arm 2 set to error Bin : %d pcs", iArm2ErrCnt);
        MyDBIProcess("Message", ErrCnt);
    }

    if(iSocketErrCnt>0)
    {
        ErrCnt.sprintf("Shuttle lose IC, Socket set to error Bin : %d pcs", iSocketErrCnt);
        MyDBIProcess("Message", ErrCnt);
    }
}
//---------------------------------------------------------------------------
void __fastcall TfMain::SPIL_ResetForIndexDrop()
{
    int i, j;
    AnsiString asString,ErrCnt;
    int iSht1ErrCnt=0, iSht2ErrCnt=0, iArm1ErrCnt=0, iArm2ErrCnt=0, iSocketErrCnt=0;
    if(SystemStart==true || bResetMode==true ||                                 //must in system pause
        bResetModeAndCleanOut==true)                                            //JerryYang 20151007 : ResetMode可選OneCycle或CleanOut
        return;

    if(fAllMotorHome==false)
        return;

    if(SoftStart)                                                               //must in system pause
        return;

    if(bRunAutoClean)                                                           //Jou 2014-03-11 : Auto Clean時不能Reset
        return;

    for(i=0; i<MAX_Index_Row; i++)
    {
        for(j=0; j<NEW_MAX_Index_Col; j++)
        {
            if(bTestSiteNeedSetErrBin[i][j]==true ||
               bTestSiteNeedSetErrBin[i+2][j]==true)                            //Steven 20210904 : 加入32site Out shuttle lose IC需自動one cycle,並將對應的site設為Error bin
            {
                if(FRCarryKit.Item[i][j]!=NULL_IC && FRCarryKit.Item[i][j]!=HAS_NULL_IC)
                {
                    FRCarryKit.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    FRCarryKit.PordRec[i][j].AddTestResultRecord(iTestBinCount, FRCarryKit.cSBin[i][j], "RESET_ForIndexArmDropErr");                            //Frank 20160505 add
                    iSht1ErrCnt++;
                }

                if(FTestSuck.AlreadyTest() && FTestSuck.Item[i][j]!=NULL_IC && FTestSuck.Item[i][j]!=HAS_NULL_IC)
                {
                    FTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    FTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, FTestSuck.cSBin[i][j], "RESET_ForIndexArmDropErr");                              //Frank 20160505 add
                    iArm1ErrCnt++;
                }

                if(BRCarryKit.Item[i][j]!=NULL_IC && BRCarryKit.Item[i][j]!=HAS_NULL_IC)
                {
                    BRCarryKit.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    BRCarryKit.PordRec[i][j].AddTestResultRecord(iTestBinCount, BRCarryKit.cSBin[i][j], "RESET_ForIndexArmDropErr");                            //Frank 20160505 add
                    iSht2ErrCnt++;
                }

                if(BTestSuck.AlreadyTest() && BTestSuck.Item[i][j]!=NULL_IC && BTestSuck.Item[i][j]!=HAS_NULL_IC)
                {
                    BTestSuck.SetItemData(i, j, TEST_PASS+iTestBinCount);
                    BTestSuck.PordRec[i][j].AddTestResultRecord(iTestBinCount, BTestSuck.cSBin[i][j], "RESET_ForIndexArmDropErr");                              //Frank 20160505 add
                    iArm2ErrCnt++;
                }
            }

            if(TestSocket.Item[i][j]!=NULL_IC && TestSocket.Item[i][j]!=HAS_NULL_IC)
            {
                TestSocket.SetItemData(i, j, TEST_PASS+iTestBinCount);
                TestSocket.PordRec[i][j].AddTestResultRecord(iTestBinCount, TestSocket.cSBin[i][j], "RESET_ForIndexArmDropErr");                                //Frank 20160505 add
                iSocketErrCnt++;
            }

            if(TestSocket.Item[i+2][j]!=NULL_IC &&
               TestSocket.Item[i+2][j]!=HAS_NULL_IC)                            //Steven 20210904 : 加入32site Out shuttle lose IC需自動one cycle,並將對應的site設為Error bin
            {
                TestSocket.SetItemData(i+2, j, TEST_PASS+iTestBinCount);
                TestSocket.PordRec[i+2][j].AddTestResultRecord(iTestBinCount, TestSocket.cSBin[i+2][j], "RESET_ForShuttleLoseIC");                              //Frank 20160505 add
                iSocketErrCnt++;
            }
        }
    }

    if(iSht1ErrCnt>0)
    {
        ErrCnt.sprintf("Index Arm Drop error, Out Shuttle 1 set to error Bin : %d pcs",iSht1ErrCnt);
        MyDBIProcess("Message", ErrCnt);
    }

    if(iSht2ErrCnt>0)
    {
        ErrCnt.sprintf("Index Arm Drop error, Out Shuttle 2 set to error Bin : %d pcs",iSht2ErrCnt);
        MyDBIProcess("Message", ErrCnt);
    }

    if(iArm1ErrCnt>0)
    {
        ErrCnt.sprintf("Index Arm Drop error, Arm 1 set to error Bin : %d pcs",iArm1ErrCnt);
        MyDBIProcess("Message", ErrCnt);
    }

    if(iArm2ErrCnt>0)
    {
        ErrCnt.sprintf("Index Arm Drop error, Arm 2 set to error Bin : %d pcs",iArm2ErrCnt);
        MyDBIProcess("Message", ErrCnt);
    }

    if(iSocketErrCnt>0)
    {
        ErrCnt.sprintf("Index Arm Drop error, Socket set to error Bin : %d pcs",iSocketErrCnt);
        MyDBIProcess("Message", ErrCnt);
    }
}
