//---------------------------------------------------------------------------
//V3.27G.531 Ifor 20170620 add Backup Setup File
//---------------------------------------------------------------------------
void __fastcall TfMain::BackupSetupFile()
{
    AnsiString sPath="D:\\HT9045_Backup\\";
    AnsiString sFileName=fMain->cbSetupFileName->Text;
    AnsiString sSetupFile="";
    if(CUSTOMER_CODE==CC_ASE_KaohSiung)                                         //kevin 20180824
        return;
    SetMD5ByFolder(DataPath+sFileName);                                         //Steven 20170927 (wei) : 將工作檔加入檢查碼

    if(CosFunction.bUseAutoBackUpSetupFile==true && IniConfig.bA24AutoBackupSetupFile==true)
    {
        if(MyForceDirectories(sPath)==false)
        {
            return;
        }

        sPath=sPath+"SetupFile\\";
        if(MyForceDirectories(sPath)==false)
        {
            return;
        }

        sPath=sPath+sFileName+"\\";
        if(MyForceDirectories(sPath)==false)
        {
            return;
        }

        sSetupFile=DataPath+sFileName+"\\*.*";
        TSearchRec srFile;
        if(FindFirst(sSetupFile, 0, srFile)==0)
        {
            do
            {
                AnsiString sCopyFile    =DataPath+sFileName+"\\"+srFile.Name;
                AnsiString sBackupFile  =sPath+srFile.Name;
                CopyFile(sCopyFile.c_str(), sBackupFile.c_str(), false);
            }
            while(FindNext(srFile)==0);
        }
    }

    if(CUSTOMER_CODE==CC_ASE_SG)
    {
        sPath="D:\\SetupFile\\";
        if(DirectoryExists(sPath)==true)
        {
            DeleteDirectory(sPath);
            MyForceDirectories(sPath);
        }
        else
        {
            MyForceDirectories(sPath);
        }

        sPath=sPath+sFileName+"\\";
        if(DirectoryExists(sPath)==false)
        {
            MyForceDirectories(sPath);
        }

        sSetupFile=DataPath+sFileName+"\\*.*";
        TSearchRec srFile;
        if(FindFirst(sSetupFile, 0, srFile)==0)
        {
            do
            {
                AnsiString sCopyFile    =DataPath+sFileName+"\\"+srFile.Name;
                AnsiString sBackupFile  =sPath+srFile.Name;
                CopyFile(sCopyFile.c_str(), sBackupFile.c_str(), false);
            }
            while(FindNext(srFile)==0);
        }
    }
}
//---------------------------------------------------------------------------
void __fastcall TfMain::mtAuto1MouseMove(TObject *Sender,
      TShiftState Shift, int X, int Y)
{
    //Steven 20171031 (wei) : Add TTMyTray滑鼠滑過去顯示Hint
    TTMyTray *Ptr;
    Ptr=(TTMyTray *)Sender;
    AnsiString asTemp="", Str2="";
    int iMyTray=MMAuto1;

    Ptr->ConvertIndexCells(X, Y);
    if(X<0 || Y<0 || X>=Ptr->XItem || Y>=Ptr->YItem)
    {
        Ptr->ShowHint=false;
        return;
    }

    if(Ptr->Name=="mtAuto1")
        iMyTray=MMAuto1;
    else if(Ptr->Name=="mtAuto2")
        iMyTray=MMAuto2;
    else if(Ptr->Name=="mtAuto3")
        iMyTray=MMAuto3;
    else if(Ptr->Name=="mtAuto4")
        iMyTray=MMAuto4;
    else if(Ptr->Name=="mtAuto5")
        iMyTray=MMAuto5;
    else if(Ptr->Name=="mtAuto6")
        iMyTray=MMAuto6;
    else if(Ptr->Name=="mtFix1")
        iMyTray=MManualTray1;
    else if(Ptr->Name=="mtFix2")
        iMyTray=MManualTray2;
    else if(Ptr->Name=="mtFix3")
        iMyTray=MManualTray3;
    else if(Ptr->Name=="mtFix4")
        iMyTray=MManualTray4;
    else if(Ptr->Name=="mtFix5")
        iMyTray=MManualTray5;
    else
        iMyTray=MManualTray6;

    if(MOT[iMyTray].fHasTray==false)
    {
        Ptr->ShowHint=false;
        return;
    }
    else
    {
        Ptr->ShowHint=true;
        Str2=Ptr->GetCellText(X, Y);
        if(Str2!="")
            asTemp.sprintf("(%d, %d) : %s", X+1,Y+1, Str2);
        Ptr->Hint=asTemp;
    }
}
//---------------------------------------------------------------------------
void __fastcall TfMain::ReadLightScaleTable()
{
    TStringList *MyList= new TStringList();
    AnsiString asPath, Path2, ppp[1000], Str1, Str2;
    int iPos1,iPos2;

    for(int i=0; i<8; i++)
    {
        asPath.sprintf("%s\\Motor%dPositive.csv", asLightScalePath, i+1);

        if(FileExists(asPath))                                                  //Steven 20160505 : 加上保護, 不然開程式會跳Error
        {
            MyList->Clear();
            MyList->LoadFromFile(asPath);
        }

        for(int j=0; j<MyList->Count; j++)
        {
            ppp[j]=MyList->Strings[j];
            iPos1=ppp[j].Pos("ArmPosition, ");
            iPos2=ppp[j].Pos("LightScalePos, ");
            Str1=ppp[j].SubString(iPos1+12, iPos2-(iPos1+12)-2);
            Str2=ppp[j].SubString(iPos2+14, 20);

            iMagneticScalePos[i*2][j]=atoi(Str1.c_str());
            iMagneticScalePos[i*2+1][j]=atoi(Str2.c_str());
        }
    }

    MyList->Clear();                                                            //Ifor 20170603 (wei) TStringList 刪除前先 Clean
    delete MyList;
}
