void __fastcall TfMain::palEQCClick(TObject *Sender)                            //JerryYang 20190701 SPIL要求主畫面可切換EQC mode
{
    if(SystemStart)                                                             //JerryYang (Steven) 20170420 新增防護
        return;

    if(IniConfig.bSPILFunction && bCanRunSCKART)                                //JerryYang 20220923 : add
    {
        return;
    }

    if(IniConfig.bShowFTandRTButtonCanClick==true ||                            //Steven 20131224 : FT & RT Buttion 可以按
       IniConfig.bEnable_SECS_GEM==true)                                        //Steven 20150604 : Add for SECS GEM
    {
        if(SystemStart || cbRunStartMode->Enabled==false ||                     //JerryYang 20170328 (wei) 非ART模式時機台內有IC不能切換FT/RT
          (LastSet.iRealDummy==REALLY && ((MOT[MMTrayY].fHasTray && MOT[MMTrayY].Tray.HasIC()) || MOT[MMTrayY_Car].fHasTray)))                                  //JerryYang 20170502 (Steven) loader有IC不能切換模式
            return;
            cbRunStartMode->Text=StartModeName[rsmQAMode];

        cbRunStartModeChange(this);
    }

    if(IniConfig.bSPILFunction==true)                                           //JerryYang 20160926 Add 矽品台中、矽品蘇州,切FT/RT要清Yield count  //JerryYang 20170328 (Jou) 矽品客戶碼統一用SPILFunction
    {
        fYieldMonitoring->ClearYieldCount();                                    //RogerYang 20170704 (Steven) 中科說要清掉

        fCounterClear->ClearCount(ctLoadingCounts);
        fCounterClear->ClearCount(ctIndexCount);                                //kevin 20130125 記錄 index吸取ic數量 index放置shuttle 數量
        fCounterClear->ClearCount(ctContactCounts);
        fCounterClear->ClearCount(ctContactCountsHis);
        fCounterClear->ClearCount(ctTraySortCount);
    }
}
