//---------------------------------------------------------------------------
void TfMain::DisableSiteMappingCheck(bool bSelect, AnsiString Func)             //Steven 20230130 : 加上紀錄
{
    static int iStatus=-1;

    AnsiString Str;
    cbDisableSiteMappingCheck->Checked=bSelect;
    bSiteMappingNeedCheck=!cbDisableSiteMappingCheck->Checked;                  //Ifor 20190308 : add 隨時開關 Site Mapping
    if(cbDisableSiteMappingCheck->Checked)
        Str.sprintf("Disable Site Mapping Check is seleceted!");
    else
        Str.sprintf("Disable Site Mapping Check is un-seleceted!");

    if(iStatus==-1)
    {
        RecordProcess(Str, Func);
        iStatus=bSelect?1:0;
    }
    else if(bSelect==true && iStatus==0)
    {
        RecordProcess(Str, Func);
        iStatus=1;
    }
    else if(bSelect==false && iStatus==1)
    {
        RecordProcess(Str, Func);
        iStatus=0;
    }
}
