//---------------------------------------------------------------------------
void TfMain::AddIndexPosLog(AnsiString Msg, bool bSave)
{
    AnsiString StrIndexLog, sFileName;

    StrIndexLog.sprintf("%04d-%02d-%02d, %02d:%02d:%02d.%03d : %s",
                        SystemYear, SystemMonth, SystemDate, SystemHour, SystemMin, SystemSec, SystemMSec, Msg);

    sFileName.sprintf("D:\\HT9045_Log\\IndexPos\\%04d\\%02d_IndexPosLog\\", SystemYear, SystemMonth);
    MyForceDirectories(sFileName);

    if(bSave)
    {
        sFileName.sprintf("D:\\HT9045_Log\\IndexPos\\%04d\\%02d_IndexPosLog\\Z1UpZ2Down_%04d%02d%02d%02d%02d%02d.logs",
                            SystemYear, SystemMonth, SystemYear, SystemMonth, SystemDate, SystemHour, SystemMin, SystemSec);

        fMain->MemoIndexPosLog->Lines->Add(StrIndexLog);
        fMain->MemoIndexPosLog->Lines->SaveToFile(sFileName);
        fMain->MemoIndexPosLog->Clear();
    }
    else
    {
        if(fMain->MemoIndexPosLog->Lines->Count>1024)
        {
            sFileName.sprintf("D:\\HT9045_Log\\IndexPos\\%04d\\%02d_IndexPosLog\\Z1UpZ2Down_%04d%02d%02d%02d%02d%02d.logs",
                                SystemYear, SystemMonth, SystemYear, SystemMonth, SystemDate, SystemHour, SystemMin, SystemSec);
            fMain->MemoIndexPosLog->Lines->SaveToFile(sFileName);
            fMain->MemoIndexPosLog->Clear();
        }
        fMain->MemoIndexPosLog->Lines->Add(StrIndexLog);
    }
}
