void __fastcall TfMain::sb_Gali_LogClick()                                      //kevin 20220221 add Gali  Command state
{
    AnsiString sRP="";
    AnsiString sTP="";
    AnsiString sSC="";
    AnsiString sTC="";
    AnsiString sTI="";
    AnsiString sTemp = "";

    int iMotorIndex[4]={MTestY1, MTestZ1, MTestZ2, MTestY2};
    AnsiString sMotorName[4]={"X", "Y", "Z", "W"};

    for(int i=0; i<4; i++)
    {
        AnsiString SelMot;
        SelMot=sMotorName[i];

        sRP=sRP+AnsiString(MOT[iMotorIndex[i]].Gali_Command("RP"+SelMot))+",";
        sTP=sTP+AnsiString(MOT[iMotorIndex[i]].Gali_Command("TP"+SelMot))+",";
        sSC=sSC+AnsiString(MOT[iMotorIndex[i]].Gali_Command("SC"+SelMot))+",";
        sTC=sTC+AnsiString(MOT[iMotorIndex[i]].Gali_Command("TC"))+",";
        sTI=sTI+AnsiString(MOT[iMotorIndex[i]].Gali_Command("TI"))+",";
    }

    sTemp="Gali_Log => sRP = "+sRP+
                     ",sTP = "+sTP+
                     ",sSC = "+sSC+
                     ",sTC = "+sTC+
                     ",sTI = "+sTI;

    RecordProcess(sTemp);
}
