        asHP1Row           .sprintf("%s\\HP1_Row.xls"          ,NewPath);
        rgHotplateShowMessage->ItemIndex=0;
        //ProcessICHotTime(true);                                               //Sam 20221124 : 修正 OneCycle 重新預熱問題 Mark
        SGDToXLS(StringGrid4, asHP2HotTime);
        SGDToXLS(StringGrid5, asHP1HotTime);
