//---------------------------------------------------------------------------
void TfMain::ChangeStateUploadServer()                                          //Sam 20230511 : 機台資料變更後須上傳 FTP
{
    if(CosFunction.bHandlerStateChangeUploadServer==false ||
       IniConfig.bN21_HandlerChangeStateUploadServer==false ||
       bHandlerChangeState==false)
    {
        return;
    }
    bHandlerChangeState=false;
    AnsiString sSiteState="",sPath="",sFile="";
    GetTimeInfo();

    sPath.sprintf("%s\\%04d\\%02d", abHandlerStateChangeUploadServerPath, SystemYear, SystemMonth);
    MyForceDirectories(sPath);
    sFile.sprintf("%s_%s.txt", IniConfig.asA32_1_HandlerID, Now().FormatString("yyyymmddhhnnss"));

    sSiteState=GetSiteState();
    WriteIniData(sPath+"\\"+sFile, "Change", "Site State", sSiteState);

    fFTPClient->UploadFileFTP(sPath,
                              sFile,
                              IniConfig.sN21_FTPUploadPath,
                              sFile,
                              IniConfig.sN21_FTPUserName,
                              IniConfig.sN21_FTPPassword,
                              IniConfig.sN21_FTPHost,
                              __FUNC__);
}
//--------------------------------------------------------------------------
void __fastcall TfMain::RecordCommunication(AnsiString aTitle, AnsiString Command)                                      //JerryYang 20230814 : add震動馬達通訊調速版本
{
    AnsiString sFileName="", sMegTime="", asLog;

    GetTimeInfo();
    sFileName.sprintf("%s\\%04d\\%02d\\%02d", asVibrateMotCommLogPath, SystemYear, SystemMonth, SystemDate);
    MyForceDirectories(sFileName);
    sFileName.sprintf("%s\\%04d\\%02d\\%02d\\%02d%02d.txt", asVibrateMotCommLogPath, SystemYear, SystemMonth, SystemDate, SystemHour, SystemMin);
    sMegTime.sprintf("%04d-%02d-%02d %02d:%02d:%02d %03d", SystemYear, SystemMonth, SystemDate, SystemHour, SystemMin, SystemSec, SystemMSec);
    asLog.sprintf("%s,   %s ==> %s", sMegTime, aTitle, Command);

    if(mmoVibrationMotor->Lines->Count>=1000)
    {
        mmoVibrationMotor->Lines->SaveToFile(sFileName);
        mmoVibrationMotor->Lines->Clear();
    }
    mmoVibrationMotor->Lines->Add(asLog);
    mmoVibrationMotor->SelLength=mmoVibrationMotor->Text.Length();              //顯示最後一行資料
    WriteDataToFile(sFileName.c_str(), asLog.c_str());
}
//------------------------------------------------------------------------------
bool TfMain::CheckOLPError()                                                    //Sam 20230921 : Bin 設定錯誤不能啟動
{
    bool bHasErr=false;
    for(int i=0; i<10; i++)
    {
        if(LastSet.OLPSetBinErr[i]>=3)
        {
            if(i==0)
            {
                ShowMyMessagePWD("CATEGORY_REQUEST has command error","Please call PE to check command", NULL, true, false, true);
            }
            else if(i==1)
            {
                if(LastSet.OLPSetBinErr[i]==4)
                    ShowMyMessagePWD("Categoty definie has pass and fail at same field","Please call PE to check bin setting", NULL, true, false, true);
                else
                    ShowMyMessagePWD("BINDEFINE_REQUEST has command error","Please call PE to check command", NULL, true, false, true);
            }
            else if(i==2)
            {
                ShowMyMessagePWD("FIXTRAYDEFINE_REQUEST has command error","Please call PE to check command", NULL, true, false, true);
            }
            bHasErr=true;
        }
    }
    return bHasErr;
}
