//---------------------------------------------------------------------------
void TfMain::SET_ESD_Tri_Temp(int iTemperature)
{
    if(USE_NOVX3360==true && Tri_Temp_Machine==1)
    {
        if(iTemperature==Tempture_Hot)
        {
            if (Temperature.fWorkTemperBase>=40 && Temperature.fWorkTemperBase<=130)
                SendCommand_ESD(ESD_TemperatureHot);
            else if (Temperature.fWorkTemperBase>130)
                SendCommand_ESD(ESD_TemperatureSuperHot);
            else if (Temperature.fWorkTemperBase<10)
                SendCommand_ESD(ESD_TemperatureCold);
        }
        else if(iTemperature==Tempture_AmbientHot)
        {
            SendCommand_ESD(ESD_TemperatureAmbient);
        }
        else
        {
            SendCommand_ESD(ESD_TemperatureAmbient);
        }
    }
}                                                                               //Ztex 2023.04.19 Add HT-1032 TriTemp Function
