void TfMain::RunStartByHotKey()
{
    if(InitialOK==false ||
       SystemStart)
    {
        return;
    }
    static bool bRun=false;
    if(bRun==true)
    {
        return;
    }
    bRun=true;

    if(CUSTOMER_CODE==CC_Greatek)
    {
        RecordProcess(AnsiString().sprintf("Func:%s ,Auto Start By Ctrl + Alt + F5",__FUNC__));
        Start("ActListenStartExecute");
    }
    bRun=false;
}
