//---------------------------------------------------------------------------
void __fastcall TfMain::edtLoginMouseDown(TObject *Sender,
      TMouseButton Button, TShiftState Shift, int X, int Y)
{
    int l;
    AnsiString S;
    bool bError;
    char str[256];
    char dest[20];

    PassList[0]->Clear();
    PassList[1]->Clear();
    PassList[2]->Clear();
    PassList[3]->Clear();
    PassList[4]->Clear();

    fQwertyKey->ShowQwertyKey(fMain->edtLogin, N_NO_SYMBOL|N_NO_SPACE|N_PASSWORD);
    PassList[4]->LoadFromFile(pwPath);                                          //2012-01-03    Dell modify

    for(int i=0; i<PassList[4]->Count; i++)
    {
        strncpy(str, PassList[4]->Strings[i].c_str(), sizeof(str));

        SplitStrByDotSpaceOnly(str, dest, 20);
        PassList[0]->Add(dest);

        SplitStrByDotSpaceOnly(str, dest, 20);
        PassList[1]->Add(dest);

        SplitStrByDotSpaceOnly(str, dest, 20);
        PassList[2]->Add(dest);

        SplitStrByDotSpaceOnly(str, dest, 20);
        PassList[3]->Add(dest);
    }

    for(int i=0; i<PassList[4]->Count; i++)
    {
        if(edtLogin->Text.UpperCase()==PassList[0]->Strings[i].UpperCase() && PassList[2]->Strings[i]!="")
        {
            l=atoi(PassList[1]->Strings[i].c_str());
            if(l>=0 && l<=3)
            {
                AccessLevel=l;
                cbUserSelect->ItemIndex=l;
                UseName=PassList[2]->Strings[i];
                fMain->ChangeLevelAttr();
//                    bEnter=false;
                if(l==3)
                {
                    cbUserSelect->Text="HonTech";
                    spbUserName->Caption="Hontech";
                }
                else
                {
                    spbUserName->Caption=cbUserSelect->Items->Strings[l];
                }
                asUser=UseName;
                S=UseName+AnsiString("===")+spbUserName->Caption;
                NewRecordProcess("MES2144", "======== USER login ========", S);
                edtLogin->Text="";
                btLogin->Caption="Logout";
                if(IniConfig.bShowLotInfo)                                      //Steven 20110113
                {
                    if(AccessLevel<iDefHonPrecLevel)                            //jou 2014-06-19 Security Have 5 Level 3->iDefHontechLevel
                    {
                        fMain->EnabledSetupFile(false);
                    }
                    else
                    {
                        if(CUSTOMER_CODE==CC_SCC ||
                           (CosFunction.bHiSiliconFunction==true &&
                            CUSTOMER_CODE==CC_JCET))                            //jou 20170921 (Steven) : center要求海思版hontech權限也不能選擇工作檔
                            fMain->EnabledSetupFile(false);
                        else
                            fMain->EnabledSetupFile(true);
                    }
                }
                else if(CUSTOMER_CODE==CC_KYEC_LEE ||
                        CUSTOMER_CODE==CC_KYEC_XILINX)                          //landam 20110324
                {
                    if(AccessLevel>=5)
                        fMain->EnabledSetupFile(true);
                    else
                        fMain->EnabledSetupFile(false);
                }
                else
                {
                    fMain->EnabledSetupFile(true);
                }
                return;
            }
        }
    }
    bError=true;

    edtLogin->Text="";
    if(bError==true)
    {
        cbUserSelect->ItemIndex=0;
        AccessLevel=0;
        fMain->EnabledSetupFile(false);
        fMain->ChangeLevelAttr();
//            bEnter=false;
        btLogin->Caption="Login";
        cbUserSelect->Text="Operator";
        spbUserName->Caption="Operator";
        ShowErrorMessage("WAR1677", 0, MMSystem, false, "Main--UserSelectChange");                                      //UserName or PassWord Error
        return;
    }
}
