void __fastcall TfMain::sbSaveMMIClick(TObject *Sender)                         //Eastsun 20260520 整合
{
    sbSaveMMI->Down=false;
    if(SystemStart)     //JerryYang (Steven) 20170420 新增防護
        return;

    AnsiString str;
    GetTimeInfo();
    AnsiString cBackUpTime;
    cBackUpTime.sprintf("%s_%s_%04d_%02d_%02d-%02d_%02d_%02d",IniConfig.sMachineType,IniConfig.SocketHandlerID,SystemYear, SystemMonth, SystemDate, SystemHour, SystemMin, SystemSec);
    AnsiString SourcePath;
    AnsiString SDataPath="D:\\BackupData\\";
    AnsiString NewPath=SDataPath+cBackUpTime;

    if(!DirectoryExists(SDataPath))
        ForceDirectories(SDataPath);

    SourcePath.sprintf("d:\\GPIB9045\\");
    str.sprintf("d:\\HT9045\\7z.exe a -tzip \"%s\" \%s\"", NewPath+".zip", SourcePath);
    system(str.c_str());

    SourcePath.sprintf("d:\\ESD_Program\\");
    str.sprintf("d:\\HT9045\\7z.exe a -tzip \"%s\" \%s\"", NewPath+".zip", SourcePath);
    system(str.c_str());

    SourcePath.sprintf("d:\\HT9045\\");
    str.sprintf("d:\\HT9045\\7z.exe a -tzip \"%s\" \%s\"", NewPath+".zip", SourcePath);
    system(str.c_str());

    if(IniConfig.bN40_1_HandlerDataBackUpUseFunction==true)
    {
        fFTPClient->BackUpDataToServerByFTP(SDataPath,cBackUpTime+".zip");
    }

    if(IniConfig.bN41_1_HandlerDataBackUpToDiskUseFunction==true)
    {
        BackUpDataToServerByDisk(SDataPath,cBackUpTime+".zip");
    }
}
//---------------------------------------------------------------------------
void TfMain::BackUpDataToServerByDisk(AnsiString asDirPath,AnsiString sFileName) //Eastsun 20260520 整合
{
    AnsiString asSourceFileName=asDirPath + sFileName;
    char str2[256];
    AnsiString asDestinationPath;

    if(DirectoryExists(IniConfig.sN41_DiskUploadPath)==false)
    {
        ForceDirectories(IniConfig.sN41_DiskUploadPath);
    }

    asDestinationPath.sprintf("%s\\%s",IniConfig.sN41_DiskUploadPath,sFileName);

    sprintf(str2,"copy \"%s\" \"%s\"",asSourceFileName,asDestinationPath);
    system(str2);

    MySleep(1000);
    if(CheckFileExist(asDestinationPath.c_str())==false)
    {
        ShowMyMessage("BackUp Data To Route Disk Fail");
    }
}
